        private void ResetBossOrder()
        {
            _bossOrderCount = 0;
            for (var index = 0; index < _bossOrder.Length; index++) _bossOrder[index] = -1;
        }

        private void AppendBossOrder(int slot)
        {
            if (slot < 0 || slot >= _bosses.Length || _bossOrderCount >= _bossOrder.Length) return;
            if (_bosses[slot].Active && Array.IndexOf(_bossOrder, slot, 0, _bossOrderCount) >= 0) return;
            _bossOrder[_bossOrderCount++] = slot;
        }

        private void RemoveBossOrder(int slot)
        {
            if (slot < 0 || slot >= _bosses.Length) return;
            var position = -1;
            for (var index = 0; index < _bossOrderCount; index++)
            {
                if (_bossOrder[index] != slot) continue;
                position = index;
                break;
            }
            if (position < 0) return;
            // Source bosses.filter(...) preserves survivor order. Shift rather
            // than swap so removing the first encounter cannot reorder the
            // remaining encounter before a later slot is appended.
            for (var index = position + 1; index < _bossOrderCount; index++)
                _bossOrder[index - 1] = _bossOrder[index];
            _bossOrder[--_bossOrderCount] = -1;
        }

        private void EnsureBossOrderEntries()
        {
            // Runtime spawns append explicitly. Reconcile active/death-fade
            // fixtures without disturbing the already established order.
            for (var index = 0; index < _bosses.Length; index++)
            {
                if (!_bosses[index].Active && _bosses[index].DeathTimer <= 0) continue;
                var present = false;
                for (var order = 0; order < _bossOrderCount; order++)
                {
                    if (_bossOrder[order] != index) continue;
                    present = true;
                    break;
                }
                if (!present) AppendBossOrder(index);
            }
            for (var order = _bossOrderCount - 1; order >= 0; order--)
            {
                var slot = _bossOrder[order];
                if (slot < 0 || (!_bosses[slot].Active && _bosses[slot].DeathTimer <= 0))
                    RemoveBossOrder(slot);
            }
        }

        private void ResetMeteorOrder()
        {
            _meteorOrderCount = 0;
            for (var index = 0; index < _meteorOrderPosition.Length; index++)
            {
                _meteorOrder[index] = -1;
                _meteorOrderPosition[index] = -1;
            }
        }

        private void AppendMeteorOrder(int slot)
        {
            if (slot < 0 || slot >= _meteors.Length || _meteorOrderCount >= _meteorOrder.Length) return;
            if (_meteorOrderPosition[slot] >= 0) return;
            _meteorOrderPosition[slot] = _meteorOrderCount;
            _meteorOrder[_meteorOrderCount++] = slot;
        }

        private void RemoveMeteorOrder(int slot)
        {
            if (slot < 0 || slot >= _meteors.Length) return;
            var position = _meteorOrderPosition[slot];
            if (position < 0 || position >= _meteorOrderCount || _meteorOrder[position] != slot) return;
            var lastPosition = --_meteorOrderCount;
            if (position != lastPosition)
            {
                var replacement = _meteorOrder[lastPosition];
                _meteorOrder[position] = replacement;
                _meteorOrderPosition[replacement] = position;
            }
            _meteorOrder[lastPosition] = -1;
            _meteorOrderPosition[slot] = -1;
        }

        private void EnsureMeteorOrderEntries()
        {
            // Runtime spawns append explicitly. This small reconciliation also
            // keeps reflection-seeded PlayMode fixtures deterministic without
            // changing the live compact order.
            for (var index = 0; index < _meteors.Length; index++)
            {
                if (_meteors[index].Active) AppendMeteorOrder(index);
            }
            for (var order = _meteorOrderCount - 1; order >= 0; order--)
            {
                var slot = _meteorOrder[order];
                if (slot < 0 || !_meteors[slot].Active) RemoveMeteorOrder(slot);
            }
        }

        private EnemyEffectTarget[] CaptureEnemyEffectSnapshot(out int snapshotCount)
        {
            // Browser effects iterate over [...this.enemies]. A copied target
            // list is important because damage can remove an enemy, chain an
            // Exploder, or immediately reuse the pooled slot for a fragment.
            snapshotCount = _enemyOrderCount;
            var snapshot = ArrayPool<EnemyEffectTarget>.Shared.Rent(Math.Max(1, snapshotCount));
            for (var order = 0; order < snapshotCount; order++)
            {
                var slot = _enemyOrder[order];
                snapshot[order] = new EnemyEffectTarget
                {
                    Slot = slot,
                    State = _enemies[slot],
                };
            }
            return snapshot;
        }

        private static void ReleaseEnemyEffectSnapshot(EnemyEffectTarget[] snapshot)
        {
            if (snapshot != null) ArrayPool<EnemyEffectTarget>.Shared.Return(snapshot);
        }

        private bool IsLiveEnemyEffectTarget(EnemyEffectTarget target)
        {
            if (target.Slot < 0 || target.Slot >= _enemies.Length) return false;
            var live = _enemies[target.Slot];
            return live.Active && live.SpawnId == target.State.SpawnId;
        }

        private void RebuildEnemyGrid()
        {
            _enemyGrid.Clear();
            Array.Clear(_enemyGridSpawnIds, 0, _enemyGridSpawnIds.Length);
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                if (_enemies[index].Active)
                {
                    _enemyGridSpawnIds[index] = _enemies[index].SpawnId;
                    _enemyGrid.Insert(index, _enemies[index].Position.x, _enemies[index].Position.y);
                }
            }
        }

        private bool IsCurrentGridEnemy(int index)
        {
            return index >= 0 && index < _enemies.Length && _enemies[index].Active &&
                _enemyGridSpawnIds[index] == _enemies[index].SpawnId;
        }

        private void SeparateEnemies()
        {
            // The browser runs one bounded grid-backed pair pass after enemy
            // movement. Querying a radius larger than the largest catalog body
            // keeps this exact rule allocation-free while avoiding an O(n^2)
            // scan when the director fills the pool.
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                var enemy = _enemies[index];
                if (!enemy.Active) continue;
                var candidateCount = _enemyGrid.QueryNeighborhood(
                    enemy.Position.x,
                    enemy.Position.y,
                    1,
                    _enemyGridSeparationCandidates);
                for (var candidate = 0; candidate < candidateCount; candidate++)
                {
                    var otherIndex = _enemyGridSeparationCandidates[candidate];
                    var other = _enemies[otherIndex];
                    // The browser resolves each pair once using the immutable
                    // spawn ID, not the pooled array slot. Slot reuse would
                    // otherwise reverse the push order for a live pair.
                    if (!IsCurrentGridEnemy(otherIndex) || other.SpawnId <= enemy.SpawnId) continue;

                    var delta = other.Position - enemy.Position;
                    var distanceSquared = delta.sqrMagnitude;
                    var minimumDistance = SeparationRules.MinimumDistance(enemy.Radius, other.Radius);
                    if (minimumDistance <= 0 || distanceSquared >= minimumDistance * minimumDistance ||
                        distanceSquared < 0.0001f) continue;

                    var distance = Mathf.Sqrt(distanceSquared);

                    var push = SeparationRules.PushMagnitude(minimumDistance, distance);
                    delta *= push;
                    var otherWeight = SeparationRules.OtherWeight(enemy.Radius, other.Radius);
                    enemy.Position -= delta * otherWeight;
                    other.Position += delta * (1f - otherWeight);
                    _enemies[otherIndex] = other;
                }
                _enemies[index] = enemy;
            }
        }

        private void UpdateBullets(float dt)
        {
            EnsureBulletOrderEntries();
            var initialOrderCount = _bulletOrderCount;
            for (var order = initialOrderCount - 1; order >= 0; order--)
            {
                var i = _bulletOrder[order];
                var bullet = _bullets[i];
                if (!bullet.Active)
                {
                    RemoveBulletOrder(i);
                    continue;
                }
                var railgun = bullet.WeaponIndex >= 0 &&
                    bullet.WeaponIndex < ContentCatalog.Weapons.Length &&
                    ContentCatalog.Weapons[bullet.WeaponIndex].Id == "railgun";
                if (bullet.Homing)
                {
                    bullet.HomingRefreshTimer -= dt;
                    var target = new HostileTarget
                    {
                        Valid = false,
                        Index = -1,
                    };
                    if (bullet.HomingTargetIndex >= 0)
                    {
                        if (bullet.HomingTargetBoss)
                        {
                            if (bullet.HomingTargetIndex < _bosses.Length)
                            {
                                var boss = _bosses[bullet.HomingTargetIndex];
                                if (boss.Active && boss.State != 4 &&
                                    BossIdentity(boss, bullet.HomingTargetIndex) == bullet.HomingTargetIdentity)
                                {
                                target = new HostileTarget
                                {
                                    Valid = true,
                                    Boss = true,
                                    Index = bullet.HomingTargetIndex,
                                    Identity = BossIdentity(boss, bullet.HomingTargetIndex),
                                    Position = boss.Position,
                                    DistanceSquared = (boss.Position - bullet.Position).sqrMagnitude,
                                };
                                }
                            }
                        }
                        else if (bullet.HomingTargetIndex < _enemies.Length)
                        {
                            var enemy = _enemies[bullet.HomingTargetIndex];
                            if (enemy.Active && enemy.Age >= 0.15f &&
                                EnemyIdentity(enemy, bullet.HomingTargetIndex) == bullet.HomingTargetIdentity)
                            {
                                target = new HostileTarget
                                {
                                    Valid = true,
                                    Boss = false,
                                    Index = bullet.HomingTargetIndex,
                                    Identity = EnemyIdentity(enemy, bullet.HomingTargetIndex),
                                    Position = enemy.Position,
                                    DistanceSquared = (enemy.Position - bullet.Position).sqrMagnitude,
                                };
                            }
                        }
                    }
                    if (bullet.HomingRefreshTimer <= 0 || !target.Valid ||
                        target.DistanceSquared > 620f * 620f * 1.44f)
                    {
                        target = FindNearestHostileFrom(bullet.Position, 620, bullet, false);
                        bullet.HomingTargetIndex = target.Valid ? target.Index : -1;
                        bullet.HomingTargetIdentity = target.Valid ? target.Identity : -1;
                        bullet.HomingTargetBoss = target.Valid && target.Boss;
                        bullet.HomingRefreshTimer = 0.09f + (order % 4) * 0.01f;
                    }
                    if (target.Valid)
                    {
                        var desired = Mathf.Atan2(target.Position.y - bullet.Position.y, target.Position.x - bullet.Position.x);
                        var current = Mathf.Atan2(bullet.Velocity.y, bullet.Velocity.x);
                        var difference = Mathf.Atan2(Mathf.Sin(desired - current), Mathf.Cos(desired - current));
                        var turn = Mathf.Clamp(
                            difference,
                            -bullet.HomingTurnRate * dt,
                            bullet.HomingTurnRate * dt);
                        var speed = bullet.Velocity.magnitude;
                        var angle = current + turn;
                        bullet.Velocity = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * speed;
                    }

                    // Browser updateBullets emits the projectile trail only for
                    // homing bullets, before movement, with the shared FX RNG.
                    // The browser guards the FX RNG draw behind the quality
                    // flag; Low quality must not advance the shared visual
                    // stream when projectile trails are disabled.
                    if (_qualityPreset.ProjectileTrails &&
                        SourceProjectileTrailEligible(true, true, _fxRng.Next()))
                    {
                        EmitTrailParticle(
                            bullet.Position,
                            new Vector2(
                                ((float)_fxRng.Next() - 0.5f) * 24f,
                                ((float)_fxRng.Next() - 0.5f) * 24f),
                            new Color(163f / 255f, 230f / 255f, 53f / 255f, 1f),
                            0.2f,
                            0.42f);
                    }
                }
                bullet.Position += bullet.Velocity * dt;
                bullet.Life -= dt;
                if (bullet.Life <= 0)
                {
                    bullet.Active = false;
                    Hide(_bulletViews[i]);
                    Hide(_bulletContrastViews[i]);
                    _bullets[i] = bullet;
                    RemoveBulletOrder(i);
                    continue;
                }
                var hit = false;
                var enemyCandidateCount = _enemyGrid.QueryNeighborhood(
                    bullet.Position.x,
                    bullet.Position.y,
                    1,
                    _enemyGridBulletCandidates);
                for (var candidate = 0; candidate < enemyCandidateCount; candidate++)
                {
                    var enemyIndex = _enemyGridBulletCandidates[candidate];
                    var enemy = _enemies[enemyIndex];
                    if (!IsCurrentGridEnemy(enemyIndex) || BulletAlreadyHitEnemy(bullet, enemyIndex)) continue;
                    var radius = bullet.Radius + enemy.Radius;
                    if (enemy.Age < 0.12f ||
                        (enemy.Position - bullet.Position).sqrMagnitude >= radius * radius) continue;
                    // Browser bullets retain Enemy object identity in hit0..3.
                    // A pooled slot can be reused after a kill, so store the
                    // stable SpawnId rather than the transient array index.
                    bullet.HitEnemy3 = bullet.HitEnemy2;
                    bullet.HitEnemy2 = bullet.HitEnemy1;
                    bullet.HitEnemy1 = bullet.HitEnemy0;
                    bullet.HitEnemy0 = EnemyIdentity(enemy, enemyIndex);
                    bullet.Hits++;
                    var critical = _rng.Next() < _critChance;
                    ApplyEnemyDamage(enemyIndex, bullet.Damage * (critical ? 2.1f : 1),
                        bullet.Velocity, bullet.Knockback, critical, bullet.WeaponIndex);
                    if (railgun) RailgunImpact(enemy.Position, bullet.Hits);
                    if (bullet.BlastRadius > 0)
                    {
                        var weaponId = ContentCatalog.Weapons[Mathf.Clamp(bullet.WeaponIndex, 0, ContentCatalog.Weapons.Length - 1)].Id;
                        DamageArea(bullet.Position, bullet.BlastRadius,
                            bullet.Damage * (weaponId == "seeker" ? 0.8f : 0.35f),
                            bullet.HitEnemy0, bullet.WeaponIndex);
                    }
                    if (bullet.Cluster)
                    {
                        bullet.Cluster = false;
                        SpawnClusterChargesAfterEnemyHit(bullet, bullet.HitEnemy0);
                    }
                    hit = true;
                    break;
                }

                if (!hit)
                {
                    EnsureBossOrderEntries();
                    for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
                    {
                        var bossIndex = _bossOrder[bossOrder];
                        var boss = _bosses[bossIndex];
                        if (!boss.Active || boss.State == 4 ||
                            BossAlreadyHit(bullet, boss, bossIndex)) continue;
                        var radius = bullet.Radius + boss.Radius;
                        if ((boss.Position - bullet.Position).sqrMagnitude >= radius * radius) continue;
                        bullet.BossHit3 = bullet.BossHit2;
                        bullet.BossHit2 = bullet.BossHit1;
                        bullet.BossHit1 = bullet.BossHit0;
                        bullet.BossHit0 = BossIdentity(boss, bossIndex);
                        // Keep the old slot mask populated for reflection
                        // fixtures; gameplay history uses stable IDs above.
                        bullet.BossHitMask |= 1 << bossIndex;
                        bullet.Hits++;
                        var critical = _rng.Next() < _critChance;
                        ApplyBossDamage(
                            bossIndex,
                            bullet.Damage * (critical ? 2.1f : 1),
                            bullet.WeaponIndex,
                            critical);
                        if (railgun) RailgunImpact(boss.Position, bullet.Hits);
                        if (bullet.BlastRadius > 0)
                        {
                            // The browser gives a boss hit a cyan presentation
                            // cue only; its blast damage is for enemy/meteor
                            // hits, not an extra boss-area hit.
                            BurstFx(
                                bullet.Position,
                                SourceDotColor("cyan"),
                                7,
                                190,
                                0.35f,
                                0.7f);
                        }
                        if (bullet.Cluster)
                        {
                            bullet.Cluster = false;
                            SpawnClusterCharges(bullet);
                        }
                        hit = true;
                        break;
                    }
                }

                if (!hit)
                {
                    EnsureMeteorOrderEntries();
                    for (var meteorOrder = _meteorOrderCount - 1; meteorOrder >= 0; meteorOrder--)
                    {
                        var meteorIndex = _meteorOrder[meteorOrder];
                        var meteor = _meteors[meteorIndex];
                        if (!meteor.Active || meteor.FuseTimer > 0 || meteor.HitTimer > 0) continue;
                        var radius = bullet.Radius + meteor.Radius;
                        if ((meteor.Position - bullet.Position).sqrMagnitude >= radius * radius) continue;
                        if (!DamageMeteor(meteorIndex, bullet.Damage)) continue;
                        bullet.Hits++;
                        if (railgun) RailgunImpact(meteor.Position, bullet.Hits);
                        if (bullet.BlastRadius > 0)
                        {
                            var weaponId = ContentCatalog.Weapons[
                                Mathf.Clamp(bullet.WeaponIndex, 0, ContentCatalog.Weapons.Length - 1)].Id;
                            DamageArea(
                                bullet.Position,
                                bullet.BlastRadius,
                                bullet.Damage * (weaponId == "seeker" ? 0.8f : 0.35f),
                                -1,
                                bullet.WeaponIndex);
                        }
                        hit = true;
                        break;
                    }
                }

                if (hit)
                {
                    if (bullet.Ricochets > 0 && RetargetRicochet(ref bullet))
                    {
                        bullet.Ricochets--;
                        bullet.Life = Mathf.Max(bullet.Life, 0.55f);
                        BurstFx(bullet.Position, SourceDotColor("white"), 4, 140, 0.24f, 0.55f);
                    }
                    else if (bullet.PierceRemaining > 0) bullet.PierceRemaining--;
                    else bullet.Active = false;
                }
                if (bullet.Life <= 0) bullet.Active = false;
                if (!bullet.Active)
                {
                    Hide(_bulletViews[i]);
                    Hide(_bulletContrastViews[i]);
                }
                _bullets[i] = bullet;
                if (!bullet.Active) RemoveBulletOrder(i);
            }
        }

        private static bool SourceProjectileTrailEligible(bool homing, bool trailsEnabled, double fxRoll)
        {
            return homing && trailsEnabled && fxRoll < 0.5;
        }

        private static bool SourceRosterPincerDashFxEligible(bool effectsEnabled, double fxRoll)
        {
            return effectsEnabled && fxRoll < 0.32;
        }

        private HostileTarget FindNearestHostileFrom(
            Vector2 origin,
            float range,
            BulletState bullet,
            bool excludeHitHistory = true,
            HashSet<int> visited = null,
            int[] visitedBuffer = null,
            int visitedCount = 0)
        {
            var target = new HostileTarget
            {
                Valid = false,
                Index = -1,
                DistanceSquared = range * range,
            };
            // Browser nearestHostile scans the enemy array in insertion order;
            // keep that order so equal-distance ties resolve identically.
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                var enemy = _enemies[index];
                if (!enemy.Active || enemy.Age < 0.15f ||
                    IsVisited(visited, visitedBuffer, visitedCount, EnemyIdentity(enemy, index)) ||
                    (excludeHitHistory && BulletAlreadyHitEnemy(bullet, index))) continue;
                var distance = (enemy.Position - origin).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = false,
                    Index = index,
                    Identity = EnemyIdentity(enemy, index),
                    Position = enemy.Position,
                    DistanceSquared = distance,
                };
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4 ||
                    IsVisited(visited, visitedBuffer, visitedCount, -BossIdentity(boss, index)) ||
                    (excludeHitHistory && BossAlreadyHit(bullet, boss, index))) continue;
                var distance = (boss.Position - origin).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = true,
                    Index = index,
                    Identity = BossIdentity(boss, index),
                    Position = boss.Position,
                    DistanceSquared = distance,
                };
            }
            return target;
        }

        private static bool IsVisited(
            HashSet<int> visited,
            int[] visitedBuffer,
            int visitedCount,
            int identity)
        {
            if (visited != null) return visited.Contains(identity);
            for (var index = 0; index < visitedCount; index++)
            {
                if (visitedBuffer[index] == identity) return true;
            }
            return false;
        }

        private static void AddVisited(int[] visitedBuffer, ref int visitedCount, int identity)
        {
            if (IsVisited(null, visitedBuffer, visitedCount, identity)) return;
            if (visitedCount < visitedBuffer.Length) visitedBuffer[visitedCount++] = identity;
        }

        private bool BulletAlreadyHitEnemy(BulletState bullet, int enemyIndex)
        {
            if (enemyIndex < 0 || enemyIndex >= _enemies.Length) return false;
            var identity = EnemyIdentity(_enemies[enemyIndex], enemyIndex);
            return bullet.HitEnemy0 == identity || bullet.HitEnemy1 == identity ||
                bullet.HitEnemy2 == identity || bullet.HitEnemy3 == identity;
        }

        private bool RetargetRicochet(ref BulletState bullet)
        {
            var target = FindNearestHostileFrom(bullet.Position, 420, bullet);
            if (!target.Valid) return false;
            var direction = target.Position - bullet.Position;
            var angle = Mathf.Atan2(direction.y, direction.x);
            var speed = bullet.Velocity.magnitude;
            bullet.Velocity = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * speed;
            return true;
        }

        private void SpawnClusterCharges(BulletState source)
        {
            SpawnClusterChargesCore(source, -1);
        }

        private void SpawnClusterChargesAfterEnemyHit(BulletState source, int excludedEnemyIdentity)
        {
            SpawnClusterChargesCore(source, excludedEnemyIdentity);
        }

        private void SpawnClusterChargesCore(BulletState source, int excludedEnemyIdentity)
        {
            var weaponIndex = 5;
            if (_upgradeProgress == null || _upgradeProgress.WeaponRanks.Length <= weaponIndex) return;
            var rank = _upgradeProgress.WeaponRanks[weaponIndex];
            if (rank <= 0) return;
            var stats = ContentCatalog.Weapons[weaponIndex].Ranks[Mathf.Clamp(rank, 1, 6) - 1].Stats;
            var visited = _clusterVisited;
            var visitedCount = 0;
            if (excludedEnemyIdentity >= 0) AddVisited(visited, ref visitedCount, excludedEnemyIdentity);
            for (var index = 0; index < _bosses.Length; index++)
            {
                if (BossAlreadyHit(source, _bosses[index], index))
                    AddVisited(visited, ref visitedCount, -BossIdentity(_bosses[index], index));
            }
            var sourceAngle = Mathf.Atan2(source.Velocity.y, source.Velocity.x);
            for (var charge = 0; charge < 3; charge++)
            {
                // React's nearestUnvisitedHostile uses only this local visited
                // set; parent enemy hit history must not suppress new cluster
                // targets, especially for a boss/meteor-triggered cluster.
                var target = FindNearestHostileFrom(
                    source.Position,
                    440,
                    source,
                    false,
                    null,
                    visited,
                    visitedCount);
                _clusterTargets[charge] = target;
                if (target.Valid)
                    AddVisited(visited, ref visitedCount, target.Boss
                        ? -target.Identity
                        : target.Identity);
            }
            for (var charge = 0; charge < 3; charge++)
            {
                if (ActiveBullets() >= MaxBullets) break;
                var target = _clusterTargets[charge];
                var angle = target.Valid
                    ? Mathf.Atan2(target.Position.y - source.Position.y, target.Position.x - source.Position.x)
                    : sourceAngle + charge * Mathf.PI * 2 / 3;
                SpawnWeaponProjectileFromPosition(
                    weaponIndex,
                    stats,
                    source.Position,
                    angle,
                    rank,
                    0.42f,
                    0.82f,
                    0,
                    Mathf.Max(24f, (float)stats.BlastRadius * 0.42f),
                    false,
                    0,
                    10f,
                    410f,
                    1.15f,
                    Mathf.Max(3f, source.Radius * 0.58f),
                    source.Knockback * 0.5f,
                    false,
                    excludedEnemyIdentity,
                    source.BossHit0,
                    source.BossHit1,
                    source.BossHit2,
                    source.BossHit3);
            }
            BurstFx(source.Position, SourceDotColor("lime"),
                9, 210, 0.38f, 0.7f);
            SpawnRingWave(source.Position, 7f, 180f, 0.26f,
                new Color(0.639f, 0.902f, 0.216f, 0.72f));
        }

        private static int EnemyIdentity(EnemyState enemy, int slot)
        {
            // SpawnId is the browser-equivalent object identity. A few
            // reflection fixtures construct a zero-initialized EnemyState, so
            // retain deterministic slot identity only for that test-only case.
            return enemy.SpawnId > 0 ? enemy.SpawnId : slot;
        }

        private static int BossIdentity(BossState boss, int slot)
        {
            // TelemetryInstanceId is the browser boss instance identity. A
            // slot fallback keeps reflection fixtures deterministic.
            return boss.TelemetryInstanceId > 0 ? boss.TelemetryInstanceId : slot + 1;
        }

        private static bool BossAlreadyHit(BulletState bullet, BossState boss, int slot)
        {
            var identity = BossIdentity(boss, slot);
            return bullet.BossHit0 == identity || bullet.BossHit1 == identity ||
                bullet.BossHit2 == identity || bullet.BossHit3 == identity;
        }

        private void UpdatePickups(float dt)
        {
            // Browser updatePickups walks the compact pickup array backwards.
            // The pooled runtime keeps the same newest-first swap-removal
            // semantics through a slot-order list; pickups spawned by a
            // same-step effect append after the captured range and wait for
            // the next simulation step, just like browser array growth.
            var initialOrderCount = _pickupOrderCount;
            for (var order = initialOrderCount - 1; order >= 0; order--)
            {
                var i = _pickupOrder[order];
                var pickup = _pickups[i];
                if (!pickup.Active) continue;
                pickup.Age += dt;
                var delta = _playerPosition - pickup.Position;
                var distanceSquared = delta.sqrMagnitude;
                var playerAlive = _playerHealth > 0 && !_gameOver && !_revivePending;
                var magnetRadius = _pickupRadius + _workshopMagnet * 8;
                if (playerAlive && (pickup.Pull || distanceSquared < magnetRadius * magnetRadius))
                {
                    pickup.Pull = true;
                    pickup.Speed = Mathf.Min(950, pickup.Speed + 2800 * dt);
                    pickup.Velocity = SourcePickupPullVelocity(delta, pickup.Speed);
                }
                else
                {
                    var decay = Mathf.Exp(-5 * dt);
                    pickup.Velocity *= decay;
                }
                pickup.Position += pickup.Velocity * dt;
                var collected = false;
                if (playerAlive && distanceSquared < (PlayerRadius + 7) * (PlayerRadius + 7))
                {
                    // Browser updatePickups removes the collected item before
                    // running its effect. This matters for Bomb: enemy death
                    // rewards must see the freed pickup slot in the same step.
                    collected = true;
                    pickup.Active = false;
                    pickup.Pull = false;
                    pickup.Velocity = Vector2.zero;
                    pickup.Speed = 0;
                    _pickups[i] = pickup;
                    Hide(_pickupViews[i]);
                    RemovePickupOrderAt(order);
                    if (pickup.Kind == PickupKind.Xp)
                    {
                        _xp += pickup.Value;
                        _telemetry.RecordXpCollected(pickup.Value);
                        _pickupStep = _pickupStepTimer > 0 ? _pickupStep + 1 : 0;
                        _pickupStepTimer = 0.9f;
                        _audio?.PlayGem(_pickupStep);
                        BurstFx(_playerPosition, SourceDotColor("emerald"), 2, 120, 0.25f, 0.6f);
                    }
                    else if (pickup.Kind == PickupKind.Part)
                    {
                        var parts = Mathf.Max(1, Mathf.RoundToInt(pickup.Value));
                        _partsEarned += parts;
                        SpawnFloater(
                            _playerPosition + Vector2.up * 18f,
                            "+" + parts + " Part" + (parts > 1 ? "s" : string.Empty),
                            new Color(0.98f, 0.79f, 0.08f, 1f),
                            12);
                        _audio?.Play(ProceduralAudio.Cue.Currency, 1f);
                        BurstFx(_playerPosition, SourceDotColor("yellow"), 3, 130, 0.28f, 0.65f);
                    }
                    else if (pickup.Kind == PickupKind.Magnet)
                    {
                        for (var otherIndex = 0; otherIndex < _pickups.Length; otherIndex++)
                        {
                            var other = _pickups[otherIndex];
                            if (other.Active && other.Kind == PickupKind.Xp)
                            {
                                other.Pull = true;
                                _pickups[otherIndex] = other;
                            }
                        }
                        _audio?.Play(ProceduralAudio.Cue.Pickup, 1f);
                        BurstFx(_playerPosition, SourceDotColor("cyan"), 12, 230, 0.45f, 0.8f);
                        ShowArenaToast("Experience pulled in", 2.5f, ToastKind.Reward);
                    }
                    else if (pickup.Kind == PickupKind.Repair)
                    {
                        var before = _playerHealth;
                        _playerHealth = Mathf.Min(
                            _playerMaxHealth,
                            _playerHealth + Mathf.Max(20, _playerMaxHealth * 0.22f));
                        var restored = SourceRound(_playerHealth - before);
                        _audio?.Play(ProceduralAudio.Cue.Pickup, 1f);
                        BurstFx(_playerPosition, SourceDotColor("emerald"), 12, 220, 0.45f, 0.8f);
                        ShowArenaToast(
                            "Integrity restored  " + (restored > 0 ? "+" + restored : "Already full"),
                            2.5f,
                            ToastKind.Reward);
                    }
                    else if (pickup.Kind == PickupKind.Bomb)
                    {
                        DetonateBomb();
                    }
                    else if (pickup.Kind == PickupKind.Overdrive)
                    {
                        _overdriveTimer = (float)PickupRules.OverdriveDurationSeconds;
                        _cyanFlash = Mathf.Max(_cyanFlash, 0.3f);
                        _audio?.Play(ProceduralAudio.Cue.Pickup, 1f);
                        SpawnRingWave(_playerPosition, 14f, 250f, 0.4f,
                            new Color(0.35f, 0.95f, 1f, 0.72f));
                        BurstFx(_playerPosition, SourceDotColor("yellow"), 16, 260, 0.5f, 0.8f);
                        BurstFx(_playerPosition, SourceDotColor("white"), 7, 180, 0.3f, 0.65f);
                        ShowArenaToast("Overclock  2x movement  1.35x fire rate  15s", 2.5f, ToastKind.Reward);
                    }
                    _telemetry.RecordPickup(PickupKindName(pickup.Kind), pickup.Value);
                }
                // A collected effect may reuse the freed pooled slot (Bomb
                // reward drops do exactly that). Do not restore the stale
                // collected value over the newly spawned pickup.
                if (!collected) _pickups[i] = pickup;
            }
            _pickupStepTimer = Mathf.Max(0, _pickupStepTimer - dt);
            if (_pickupStepTimer <= 0) _pickupStep = 0;
        }

        private void UpdateWeapons(float dt)
        {
            if (_upgradeProgress == null || _playerHealth <= 0 || _gameOver || _revivePending) return;
            UpdatePulseBurst(dt);
            var recoveryScale = WeaponRecoveryScale();
            for (var weaponIndex = 0; weaponIndex < ContentCatalog.Weapons.Length; weaponIndex++)
            {
                var weapon = ContentCatalog.Weapons[weaponIndex];
                var rank = _upgradeProgress.WeaponRanks[weaponIndex];
                _weaponCooldowns[weaponIndex] -= dt;
                if (rank <= 0 || weapon.Kind == "orbit") continue;
                var rankDefinition = weapon.Ranks[Mathf.Clamp(rank, 1, weapon.Ranks.Length) - 1];
                var stats = rankDefinition.Stats;
                if (_weaponCooldowns[weaponIndex] > 0) continue;
                var target = FindNearestHostile((float)stats.Range);
                if (!target.Valid)
                {
                    _weaponCooldowns[weaponIndex] = 0;
                    continue;
                }

                _weaponCooldowns[weaponIndex] = (float)stats.Cooldown * recoveryScale *
                    (weapon.Id == "pistol" && _upgradeProgress.Evolved[weaponIndex] ? 1.32f : 1f);
                if (weapon.Id == "pistol" && _upgradeProgress.Evolved[weaponIndex])
                {
                    if (_pulseBurstShots <= 0)
                    {
                        _pulseBurstShots = 3;
                        _pulseBurstTimer = 0;
                    }
                    continue;
                }

                FireWeapon(weaponIndex, stats, rank, target);
            }
        }

        private void UpdatePulseBurst(float dt)
        {
            if (_pulseBurstShots <= 0 || _playerHealth <= 0 || _gameOver || _revivePending) return;
            _pulseBurstTimer -= dt;
            if (_pulseBurstTimer > 0) return;

            var rank = _upgradeProgress.WeaponRanks[0];
            var weapon = ContentCatalog.Weapons[0];
            var stats = weapon.Ranks[Mathf.Clamp(rank, 1, weapon.Ranks.Length) - 1].Stats;
            var target = FindNearestHostile((float)stats.Range);
            if (!target.Valid)
            {
                _pulseBurstShots = 0;
                return;
            }

            var direction = target.Position - _playerPosition;
            var angle = Mathf.Atan2(direction.y, direction.x);
            var thirdRound = _pulseBurstShots == 1;
            var pulseAngles = CombatRules.ProjectileAngles(
                angle,
                stats.ProjectileCount,
                (float)stats.SpreadDegrees);
            for (var index = 0; index < pulseAngles.Length; index++)
            {
                // Browser pulse rounds retain the current rank's full
                // projectile count, including the third-round ricochet flag.
                SpawnWeaponProjectile(
                    0,
                    stats,
                    (float)pulseAngles[index],
                    rank,
                    thirdRound ? 1.35f : 0.9f,
                    thirdRound ? 1.35f : 1f,
                    thirdRound ? 1 : (int?)null,
                    null,
                    false,
                    thirdRound ? 1 : 0);
            }
            _audio?.Play(ProceduralAudio.Cue.Fire);
            BurstFx(
                _playerPosition + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 20f,
                thirdRound ? SourceDotColor("white") : SourceDotColor("cyan"),
                thirdRound ? 4 : 2,
                150,
                0.16f,
                0.55f);
            _pulseBurstShots--;
            _pulseBurstTimer = 0.085f *
                (float)PickupRules.OverdriveCooldownMultiplier(_overdriveTimer > 0);
        }

        private float WeaponRecoveryScale()
        {
            return (float)CombatRules.WeaponRecoveryMultiplier(
                _cooldownMultiplier,
                _adrenalTimer > 0 ? SupportRank("adrenal") : 0,
                (float)PickupRules.OverdriveCooldownMultiplier(_overdriveTimer > 0));
        }

        private HostileTarget FindNearestHostile(float range)
        {
            var target = new HostileTarget
            {
                Valid = false,
                Index = -1,
                DistanceSquared = range * range,
            };
            // Browser nearestHostile scans every enemy, rather than a spatial
            // candidate list. Preserve its exact candidate/tie order here.
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                var enemy = _enemies[index];
                if (!enemy.Active || enemy.Age < 0.15f) continue;
                var distance = (enemy.Position - _playerPosition).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = false,
                    Index = index,
                    Identity = EnemyIdentity(enemy, index),
                    Position = enemy.Position,
                    DistanceSquared = distance,
                };
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4) continue;
                var distance = (boss.Position - _playerPosition).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = true,
                    Index = index,
                    Identity = BossIdentity(boss, index),
                    Position = boss.Position,
                    DistanceSquared = distance,
                };
            }
            return target;
        }

        private HostileTarget FindNearestUnvisitedHostile(
            Vector2 origin,
            float range,
            int[] visited,
            int visitedCount)
        {
            var target = new HostileTarget
            {
                Valid = false,
                Index = -1,
                DistanceSquared = range * range,
            };
            // Browser chain retargeting also walks the enemy array directly.
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                var enemy = _enemies[index];
                if (!enemy.Active || enemy.Age < 0.15f ||
                    IsVisited(null, visited, visitedCount, EnemyIdentity(enemy, index))) continue;
                var distance = (enemy.Position - origin).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = false,
                    Index = index,
                    Identity = EnemyIdentity(enemy, index),
                    Position = enemy.Position,
                    DistanceSquared = distance,
                };
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4 ||
                    IsVisited(null, visited, visitedCount, -BossIdentity(boss, index))) continue;
                var distance = (boss.Position - origin).sqrMagnitude;
                if (distance >= target.DistanceSquared) continue;
                target = new HostileTarget
                {
                    Valid = true,
                    Boss = true,
                    Index = index,
                    Identity = BossIdentity(boss, index),
                    Position = boss.Position,
                    DistanceSquared = distance,
                };
            }
            return target;
        }

        private void FireWeapon(int weaponIndex, WeaponStatsDefinition stats, int rank, HostileTarget target)
        {
            var weapon = ContentCatalog.Weapons[weaponIndex];
            if (weapon.Kind == "chain")
            {
                FireArc(weaponIndex, stats, rank, target);
                return;
            }
            // Browser authority returns before any weapon cue or muzzle FX when
            // the player-bullet array is already at capacity. Preserve that
            // boundary so a rejected shot stays silent and side-effect free.
            if (ActiveBullets() >= MaxBullets) return;
            var direction = target.Position - _playerPosition;
            var baseAngle = Mathf.Atan2(direction.y, direction.x);
            var evolved = _upgradeProgress.Evolved[weaponIndex];
            var spread = weapon.Id == "scattergun" && evolved ? 14 : (float)stats.SpreadDegrees;
            var angles = CombatRules.ProjectileAngles(baseAngle, stats.ProjectileCount, spread);
            for (var index = 0; index < angles.Length; index++)
            {
                // Browser fireWeapon breaks before calculating the next
                // Scattergun jitter when the player-bullet array fills. Do
                // not consume gameplay RNG for a shot SpawnWeaponProjectile
                // cannot create.
                if (ActiveBullets() >= MaxBullets) break;
                var angle = (float)angles[index];
                if (weapon.Id == "scattergun")
                {
                    angle += ((float)_rng.Next() - 0.5f) * spread * Mathf.Deg2Rad * 0.12f;
                }
                SpawnWeaponProjectile(weaponIndex, stats, angle, rank, 1, 1, null, null,
                    weapon.Id == "seeker" && evolved);
            }

            if (weapon.Id == "scattergun" && evolved)
            {
                SpawnWeaponProjectile(weaponIndex, stats, baseAngle, rank, 2.35f,
                    Mathf.Max(1.45f, 7f / Mathf.Max(1f, (float)stats.ProjectileRadius)),
                    Mathf.Max(3, stats.Pierce + 2), 56, false);
            }
            if (weapon.Id == "railgun" && evolved)
            {
                var railDirection = new Vector2(Mathf.Cos(baseAngle), Mathf.Sin(baseAngle));
                var start = _playerPosition + railDirection * 18;
                StartRailTrail(
                    start,
                    start + railDirection * (float)stats.Range,
                    (float)stats.Damage * _damageMultiplier * 0.18f,
                    weaponIndex);
            }
            if (weapon.Id == "scattergun")
            {
                _audio?.Play(ProceduralAudio.Cue.Scattergun);
                AddCameraShake(0.12f);
            }
            else if (weapon.Id == "railgun")
            {
                _audio?.Play(ProceduralAudio.Cue.Railgun, 0.78f);
                AddCameraShake(0.24f);
                TriggerFreeze(0.035f);
            }
            else if (weapon.Id == "seeker")
            {
                _audio?.Play(ProceduralAudio.Cue.Seeker);
            }
            else
            {
                _audio?.Play(ProceduralAudio.Cue.Fire);
            }
            if (weapon.Id == "railgun")
            {
                var muzzle = _playerPosition + new Vector2(Mathf.Cos(baseAngle), Mathf.Sin(baseAngle)) * 22f;
                BurstFx(muzzle, SourceDotColor("white"), 6, 250, 0.2f, 0.48f);
                BurstFx(muzzle, SourceDotColor("violet"),
                    7, 190, 0.24f, 0.58f);
                SpawnRingWave(muzzle, 5f, 135f, 0.22f,
                    new Color(0.655f, 0.545f, 0.98f, 0.72f));
            }
            var muzzleColor = weapon.Id == "scattergun"
                ? SourceDotColor("orange")
                : weapon.Id == "railgun"
                    ? SourceDotColor("violet")
                    : weapon.Id == "seeker"
                        ? SourceDotColor("lime")
                        : SourceDotColor("cyan");
            BurstFx(
                _playerPosition + new Vector2(Mathf.Cos(baseAngle), Mathf.Sin(baseAngle)) * 20f,
                muzzleColor,
                2 + Mathf.FloorToInt(rank / 2f),
                130,
                0.16f,
                0.55f);
        }

        private void SpawnWeaponProjectile(
            int weaponIndex,
            WeaponStatsDefinition stats,
            float angle,
            int rank,
            float damageScale,
            float radiusScale,
            int? pierceOverride,
            float? blastRadiusOverride,
            bool cluster,
            int ricochetOverride = 0)
        {
            SpawnWeaponProjectileFromPosition(
                weaponIndex,
                stats,
                _playerPosition,
                angle,
                rank,
                damageScale,
                radiusScale,
                pierceOverride,
                blastRadiusOverride,
                cluster,
                ricochetOverride);
        }

        private void SpawnWeaponProjectileFromPosition(
            int weaponIndex,
            WeaponStatsDefinition stats,
            Vector2 origin,
            float angle,
            int rank,
            float damageScale,
            float radiusScale,
            int? pierceOverride,
            float? blastRadiusOverride,
            bool cluster,
            int ricochetOverride = 0,
            float homingTurnRateOverride = -1f,
            float projectileSpeedOverride = -1f,
            float lifeOverride = -1f,
            float radiusOverride = -1f,
            float knockbackOverride = -1f,
            bool offsetOrigin = true,
            int excludedEnemyIndex = -1,
            int bossHit0Override = -1,
            int bossHit1Override = -1,
            int bossHit2Override = -1,
            int bossHit3Override = -1)
        {
            if ((float)stats.ProjectileSpeed <= 0) return;
            var slot = FindInactive(_bullets);
            if (slot < 0) return;
            var weapon = ContentCatalog.Weapons[weaponIndex];
            var direction = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
            var radius = radiusOverride > 0
                ? radiusOverride
                : (float)stats.ProjectileRadius * radiusScale;
            var blastRadius = blastRadiusOverride.HasValue
                ? blastRadiusOverride.Value * _areaMultiplier
                : (float)stats.BlastRadius * _areaMultiplier;
            _bullets[slot] = new BulletState
            {
                Active = true,
                Position = offsetOrigin ? origin + direction * 18 : origin,
                Velocity = direction * (projectileSpeedOverride > 0 ? projectileSpeedOverride : (float)stats.ProjectileSpeed),
                Damage = (float)stats.Damage * _damageMultiplier * damageScale,
                Life = lifeOverride > 0
                    ? lifeOverride
                    : (float)stats.Range / Mathf.Max(1, (float)stats.ProjectileSpeed),
                Radius = radius,
                WeaponIndex = weaponIndex,
                Rank = rank,
                PierceRemaining = pierceOverride ?? stats.Pierce,
                HitEnemy0 = excludedEnemyIndex,
                HitEnemy1 = -1,
                HitEnemy2 = -1,
                HitEnemy3 = -1,
                BossHitMask = 0,
                BossHit0 = bossHit0Override,
                BossHit1 = bossHit1Override,
                BossHit2 = bossHit2Override,
                BossHit3 = bossHit3Override,
                Ricochets = ricochetOverride,
                Knockback = knockbackOverride >= 0 ? knockbackOverride : (float)stats.Knockback,
                BlastRadius = blastRadius,
                Homing = weapon.Id == "seeker",
                HomingTurnRate = weapon.Id == "seeker"
                    ? (homingTurnRateOverride > 0 ? homingTurnRateOverride : 7f)
                    : 0,
                HomingTargetIndex = -1,
                HomingTargetIdentity = -1,
                HomingTargetBoss = false,
                HomingRefreshTimer = 0,
                Cluster = cluster,
                Evolved = _upgradeProgress.Evolved[weaponIndex],
                Hits = 0,
                View = slot,
            };
            AppendBulletOrder(slot);
            var view = EnsureBulletView(slot);
            var frame = SourceProjectileFrameIndex(new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)));
            view.sprite = ProceduralSpriteFactory.ProjectileFrame(weapon.Id, frame);
            view.transform.rotation = Quaternion.identity;
            view.color = Color.white;
            view.enabled = true;
            var contrast = _bulletContrastViews[slot];
            contrast.sprite = view.sprite;
            contrast.transform.rotation = Quaternion.identity;
            contrast.color = new Color(1f, 1f, 1f, 0.9f);
            contrast.enabled = false;
        }

        private void FireArc(int weaponIndex, WeaponStatsDefinition stats, int rank, HostileTarget first)
        {
            if (!first.Valid) return;
            var visited = _arcVisited;
            var visitedCount = 0;
            var evolved = _upgradeProgress.Evolved[weaponIndex];
            var endpoint = FireArcChainBuffered(
                stats,
                first,
                visited,
                ref visitedCount,
                out var points,
                weaponIndex);
            CreateArcEffect(points.ToArray(), evolved);
            if (evolved)
            {
                // Browser authority resolves the evolved second chain before
                // emitting the first endpoint burst. If no second target is
                // available, the first endpoint still receives its burst.
                var second = FindNearestUnvisitedHostile(
                    _playerPosition,
                    (float)stats.Range,
                    visited,
                    visitedCount);
                if (second.Valid)
                {
                    var secondEndpoint = FireArcChainBuffered(
                        stats,
                        second,
                        visited,
                        ref visitedCount,
                        out var secondPoints,
                        weaponIndex);
                    CreateArcEffect(secondPoints.ToArray(), true);
                    ArcEndpointBurst(secondEndpoint, (float)stats.Damage * _damageMultiplier, weaponIndex);
                }
            }
            if (evolved) ArcEndpointBurst(endpoint, (float)stats.Damage * _damageMultiplier, weaponIndex);
            _audio?.Play(ProceduralAudio.Cue.Arc);
        }

        private void ArcEndpointBurst(HostileTarget endpoint, float damage, int weaponIndex)
        {
            if (!endpoint.Valid) return;
            DamageArea(
                endpoint.Position,
                62f * _areaMultiplier,
                damage * 0.58f,
                endpoint.Boss ? -1 : endpoint.Identity,
                weaponIndex);
            BurstFx(endpoint.Position, SourceDotColor("yellow"), 6, 170, 0.3f, 0.65f);
        }

        // Keep the original private signature for reflection fixtures and
        // older editor tooling. Live gameplay uses the fixed-buffer overload
        // below, so this compatibility path is not on the normal cast path.
        private HostileTarget FireArcChain(
            WeaponStatsDefinition stats,
            HostileTarget first,
            HashSet<int> visited,
            out List<Vector2> points,
            int weaponIndex)
        {
            var buffer = _arcVisited;
            var count = 0;
            foreach (var identity in visited) AddVisited(buffer, ref count, identity);
            var endpoint = FireArcChainBuffered(
                stats,
                first,
                buffer,
                ref count,
                out points,
                weaponIndex);
            for (var index = 0; index < count; index++) visited.Add(buffer[index]);
            return endpoint;
        }

        private HostileTarget FireArcChainBuffered(
            WeaponStatsDefinition stats,
            HostileTarget first,
            int[] visited,
            ref int visitedCount,
            out List<Vector2> points,
            int weaponIndex)
        {
            points = new List<Vector2> { _playerPosition };
            var current = first;
            for (var jump = 0; jump <= stats.ChainCount; jump++)
            {
                var key = current.Boss ? -current.Identity : current.Identity;
                if (IsVisited(null, visited, visitedCount, key)) break;
                AddVisited(visited, ref visitedCount, key);
                var previous = points[points.Count - 1];
                points.Add(current.Position);
                var critical = _rng.Next() < _critChance;
                var damage = (float)stats.Damage * _damageMultiplier * (critical ? 2.1f : 1);
                var direction = current.Position - previous;
                if (current.Boss) ApplyBossDamage(current.Index, damage, weaponIndex, critical);
                else ApplyEnemyDamage(current.Index, damage, direction, 40, critical, weaponIndex);

                if (jump == stats.ChainCount) break;
                var next = FindNearestUnvisitedHostile(
                    current.Position,
                    200f * _areaMultiplier,
                    visited,
                    visitedCount);
                // Browser fireArcPath keeps the last valid hostile as the
                // endpoint when no further chain target exists.
                if (!next.Valid) break;
                current = next;
            }

            return current;
        }

        private void UpdateBlades(float dt)
        {
            if (_upgradeProgress == null || _playerHealth <= 0 || _gameOver || _revivePending)
            {
                HideBlades(0);
                return;
            }
            if (_upgradeProgress.WeaponRanks.Length <= 3)
            {
                HideBlades(0);
                return;
            }
            var rank = _upgradeProgress.WeaponRanks[3];
            if (rank <= 0)
            {
                HideBlades(0);
                return;
            }
            var weapon = ContentCatalog.Weapons[3];
            var stats = weapon.Ranks[Mathf.Clamp(rank, 1, weapon.Ranks.Length) - 1].Stats;
            _bladeAngle += dt * (float)stats.OrbitSpeed;
            var recoveryScale = WeaponRecoveryScale();
            var evolved = _upgradeProgress.Evolved[3];
            if (evolved)
            {
                if (_hollowBladeActive)
                {
                    _hollowBladeAge += dt;
                    if (_hollowBladeAge >= 1.38f)
                    {
                        _hollowBladeActive = false;
                        _hollowBladeCooldown = 0.42f * recoveryScale;
                    }
                }
                else
                {
                    _hollowBladeCooldown -= dt;
                    if (_hollowBladeCooldown <= 0)
                    {
                        _hollowBladeAngle = DensestEnemyAngle(HollowBladeReach(stats));
                        _hollowBladeAge = 0;
                        _hollowBladeActive = true;
                        _audio?.Play(ProceduralAudio.Cue.BladeLaunch, 0.9f);
                    }
                }
            }
            else
            {
                _hollowBladeActive = false;
                _hollowBladeCooldown = 0;
                Hide(_hollowBladeView);
                Hide(_hollowBladeFarView);
                Hide(_hollowBladeNearView);
            }
            for (var bladeIndex = 0; bladeIndex < _bladeViews.Length; bladeIndex++)
            {
                if (bladeIndex >= stats.OrbitCount)
                {
                    Hide(_bladeViews[bladeIndex]);
                    continue;
                }
                var angle = _bladeAngle + bladeIndex / Mathf.Max(1f, stats.OrbitCount) * Mathf.PI * 2;
                var position = _playerPosition + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) *
                    (float)stats.OrbitRadius * _areaMultiplier;
                var view = EnsureBladeView(bladeIndex);
                view.transform.position = position;
                view.transform.localScale = Vector3.one * SourceBladeSpriteWorldSize(false);
                view.color = ParseColor(
                    _upgradeProgress.Evolved[3] ? "#5eead4" : weapon.Accent,
                    new Color(0.2f, 0.85f, 0.65f, 1));
                view.enabled = true;

                var enemyCandidateCount = _enemyGrid.QueryNeighborhood(
                    position.x,
                    position.y,
                    1,
                    _enemyGridBulletCandidates);
                for (var candidate = 0; candidate < enemyCandidateCount; candidate++)
                {
                    var enemyIndex = _enemyGridBulletCandidates[candidate];
                    var enemy = _enemies[enemyIndex];
                    if (!IsCurrentGridEnemy(enemyIndex) || enemy.Age < 0.2f || enemy.BladeCooldown > 0) continue;
                    var reach = enemy.Radius + (float)stats.ProjectileRadius;
                    if ((enemy.Position - position).sqrMagnitude > reach * reach) continue;
                    var critical = _rng.Next() < _critChance;
                    enemy.BladeCooldown = (float)stats.HitCooldown * recoveryScale;
                    _enemies[enemyIndex] = enemy;
                    ApplyEnemyDamage(enemyIndex,
                        (float)stats.Damage * _damageMultiplier * (critical ? 2.1f : 1),
                        enemy.Position - position,
                        190,
                        critical,
                        3);
                }
                EnsureBossOrderEntries();
                for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
                {
                    var bossIndex = _bossOrder[bossOrder];
                    var boss = _bosses[bossIndex];
                    if (!boss.Active || boss.State == 4 || boss.BladeCooldown > 0) continue;
                    var reach = boss.Radius + (float)stats.ProjectileRadius;
                    if ((boss.Position - position).sqrMagnitude >= reach * reach) continue;
                    boss.BladeCooldown = (float)stats.HitCooldown * recoveryScale;
                    _bosses[bossIndex] = boss;
                    var critical = _rng.Next() < _critChance;
                    ApplyBossDamage(
                        bossIndex,
                        (float)stats.Damage * _damageMultiplier * (critical ? 2.1f : 1),
                        3,
                        critical);
                }
            }

            if (!evolved || !_hollowBladeActive)
            {
                Hide(_hollowBladeView);
                Hide(_hollowBladeFarView);
                Hide(_hollowBladeNearView);
                return;
            }

            var progress = Mathf.Clamp01(_hollowBladeAge / 1.38f);
            var travel = progress < 0.42f
                ? progress / 0.42f
                : progress > 0.58f ? 1 - (progress - 0.58f) / 0.42f : 1;
            var orbitRadius = (float)stats.OrbitRadius * _areaMultiplier;
            var maximum = HollowBladeReach(stats);
            var hollowDistance = orbitRadius + (maximum - orbitRadius) * Mathf.Clamp01(travel);
            var hollowPosition = _playerPosition + new Vector2(
                Mathf.Cos(_hollowBladeAngle), Mathf.Sin(_hollowBladeAngle)) * hollowDistance;
            var hollowView = EnsureHollowBladeView();
            hollowView.transform.position = hollowPosition;
            hollowView.transform.rotation = Quaternion.Euler(0, 0, _hollowBladeAngle * Mathf.Rad2Deg);
            hollowView.transform.localScale = Vector3.one * SourceBladeSpriteWorldSize(true);
            hollowView.color = new Color(0.37f, 0.9f, 0.82f, 1f);
            hollowView.enabled = true;

            // Browser drawBlades keeps two dim hollow-blade afterimages behind
            // the travelling blade at offsets 27 and 14 with alpha 0.1/0.2.
            var direction = new Vector2(
                Mathf.Cos(_hollowBladeAngle),
                Mathf.Sin(_hollowBladeAngle));
            var trailScale = Vector3.one * SourceBladeSpriteWorldSize(true);
            var farTrail = EnsureHollowBladeTrailView(false);
            farTrail.transform.position = hollowPosition - direction * 27f;
            farTrail.transform.rotation = hollowView.transform.rotation;
            farTrail.transform.localScale = trailScale;
            farTrail.color = new Color(0.37f, 0.9f, 0.82f, 0.1f);
            farTrail.enabled = true;
            var nearTrail = EnsureHollowBladeTrailView(true);
            nearTrail.transform.position = hollowPosition - direction * 14f;
            nearTrail.transform.rotation = hollowView.transform.rotation;
            nearTrail.transform.localScale = trailScale;
            nearTrail.color = new Color(0.37f, 0.9f, 0.82f, 0.2f);
            nearTrail.enabled = true;
            UpdateHollowBladeDamage(hollowPosition, stats, recoveryScale);
        }

        private float HollowBladeReach(WeaponStatsDefinition stats)
        {
            return Mathf.Max(360f, (float)stats.Range * 4.25f, (float)stats.OrbitRadius + 180f) * _areaMultiplier;
        }

        private float DensestEnemyAngle(float maximumRange)
        {
            var maximumRangeSquared = maximumRange * maximumRange;
            var bestPosition = _playerPosition + new Vector2(Mathf.Cos(_bladeAngle), Mathf.Sin(_bladeAngle));
            var bestCount = -1;
            var eligibleCount = 0;
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var index = _enemyOrder[order];
                var candidate = _enemies[index];
                if (!candidate.Active || candidate.Age < 0.15f || (candidate.Position - _playerPosition).sqrMagnitude > maximumRangeSquared) continue;
                eligibleCount++;
                var count = 0;
                for (var otherOrder = 0; otherOrder < _enemyOrderCount; otherOrder++)
                {
                    var otherIndex = _enemyOrder[otherOrder];
                    var other = _enemies[otherIndex];
                    if (other.Active && (other.Position - candidate.Position).sqrMagnitude < 150f * 150f) count++;
                }
                if (count > bestCount)
                {
                    bestCount = count;
                    bestPosition = candidate.Position;
                }
                if (eligibleCount >= 48) break;
            }
            if (bestCount >= 0) return Mathf.Atan2(bestPosition.y - _playerPosition.y, bestPosition.x - _playerPosition.x);
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (boss.Active && (boss.Position - _playerPosition).sqrMagnitude <= maximumRangeSquared)
                {
                    return Mathf.Atan2(boss.Position.y - _playerPosition.y, boss.Position.x - _playerPosition.x);
                }
            }
            return _bladeAngle;
        }

        private void UpdateHollowBladeDamage(Vector2 position, WeaponStatsDefinition stats, float recoveryScale)
        {
            var enemyCandidateCount = _enemyGrid.QueryNeighborhood(
                position.x,
                position.y,
                1,
                _enemyGridBulletCandidates);
            for (var candidate = 0; candidate < enemyCandidateCount; candidate++)
            {
                var enemyIndex = _enemyGridBulletCandidates[candidate];
                var enemy = _enemies[enemyIndex];
                if (!IsCurrentGridEnemy(enemyIndex) || enemy.Age < 0.2f || enemy.HollowCooldown > 0) continue;
                var reach = enemy.Radius + (float)stats.ProjectileRadius * 1.25f;
                if ((enemy.Position - position).sqrMagnitude > reach * reach) continue;
                var critical = _rng.Next() < _critChance;
                enemy.HollowCooldown = (float)stats.HitCooldown * 0.62f * recoveryScale;
                _enemies[enemyIndex] = enemy;
                ApplyEnemyDamage(
                    enemyIndex,
                    (float)stats.Damage * _damageMultiplier * 1.45f * (critical ? 2.1f : 1),
                    enemy.Position - position,
                    280,
                    critical,
                    3);
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var bossIndex = _bossOrder[bossOrder];
                var boss = _bosses[bossIndex];
                if (!boss.Active || boss.State == 4 || boss.HollowCooldown > 0) continue;
                var reach = boss.Radius + (float)stats.ProjectileRadius * 1.25f;
                if ((boss.Position - position).sqrMagnitude >= reach * reach) continue;
                var critical = _rng.Next() < _critChance;
                boss.HollowCooldown = (float)stats.HitCooldown * 0.62f * recoveryScale;
                _bosses[bossIndex] = boss;
                ApplyBossDamage(
                    bossIndex,
                    (float)stats.Damage * _damageMultiplier * 1.45f * (critical ? 2.1f : 1),
                    3,
                    critical);
            }
        }

        private void HideBlades(int start)
        {
            for (var index = start; index < _bladeViews.Length; index++) Hide(_bladeViews[index]);
            if (start == 0)
            {
                Hide(_hollowBladeView);
                Hide(_hollowBladeFarView);
                Hide(_hollowBladeNearView);
            }
        }

        private void CreateArcEffect(Vector2[] points, bool evolved)
        {
            var slot = SelectArcEffectSlot(_arcEffects);
            var jaggedPoints = JaggedArcPoints(points);
            var view = EnsureArcView(slot);
            view.positionCount = jaggedPoints.Length;
            for (var index = 0; index < jaggedPoints.Length; index++)
                view.SetPosition(index, jaggedPoints[index]);
            var outerColor = evolved
                ? new Color(250f / 255f, 204f / 255f, 21f / 255f, 1f)
                : new Color(147f / 255f, 197f / 255f, 253f / 255f, 1f);
            var innerColor = evolved
                ? new Color(254f / 255f, 249f / 255f, 195f / 255f, 1f)
                : new Color(248f / 255f, 250f / 255f, 252f / 255f, 1f);
            var outerWidth = evolved ? 5.5f : 4.5f;
            var innerWidth = evolved ? 2f : 1.6f;
            view.startColor = outerColor;
            view.endColor = view.startColor;
            view.startWidth = outerWidth;
            view.endWidth = outerWidth;
            ConfigureRoundLine(view);
            view.enabled = true;
            var core = EnsureArcCoreView(slot);
            core.positionCount = jaggedPoints.Length;
            for (var index = 0; index < jaggedPoints.Length; index++)
                core.SetPosition(index, jaggedPoints[index]);
            core.startColor = innerColor;
            core.endColor = innerColor;
            core.startWidth = innerWidth;
            core.endWidth = innerWidth;
            ConfigureRoundLine(core);
            core.enabled = true;
            var maxLife = evolved ? 0.22f : 0.16f;
            _arcEffects[slot] = new ArcEffectState
            {
                Active = true,
                Points = jaggedPoints,
                Life = maxLife,
                MaxLife = maxLife,
                Sequence = _nextArcEffectSequence++,
                View = slot,
            };
        }

        private Vector2[] JaggedArcPoints(Vector2[] points)
        {
            if (points == null || points.Length < 2) return points ?? Array.Empty<Vector2>();
            var jagged = new List<Vector2>(1 + (points.Length - 1) * 3)
            {
                points[0],
            };
            for (var index = 1; index < points.Length; index++)
            {
                var previous = jagged[jagged.Count - 1];
                var next = points[index];
                var delta = next - previous;
                var length = SourceLengthOrOne(delta);
                var normal = new Vector2(-delta.y / length, delta.x / length);
                for (var tIndex = 0; tIndex < 2; tIndex++)
                {
                    var t = tIndex == 0 ? 0.33f : 0.66f;
                    var offset = ((float)_fxRng.Next() - 0.5f) * Mathf.Min(28f, length * 0.3f);
                    jagged.Add(previous + delta * t + normal * offset);
                }
                jagged.Add(next);
            }
            return jagged.ToArray();
        }

        private static int SelectArcEffectSlot(ArcEffectState[] effects)
        {
            var slot = -1;
            var oldestSequence = int.MaxValue;
            for (var index = 0; index < effects.Length; index++)
            {
                if (!effects[index].Active) return index;
                if (effects[index].Sequence < oldestSequence)
                {
                    oldestSequence = effects[index].Sequence;
                    slot = index;
                }
            }
            return slot < 0 ? 0 : slot;
        }

        private void UpdateArcEffects(float dt)
        {
            for (var index = 0; index < _arcEffects.Length; index++)
            {
                var effect = _arcEffects[index];
                if (!effect.Active) continue;
                effect.Life -= dt;
                if (effect.Life <= 0)
                {
                    effect.Active = false;
                    Hide(_arcViews[index]);
                    Hide(_arcCoreViews[index]);
                }
                else if (_arcViews[index] != null)
                {
                    var alpha = Mathf.Clamp01(
                        effect.Life / Mathf.Max(0.001f, effect.MaxLife));
                    var color = _arcViews[index].startColor;
                    color.a = alpha;
                    _arcViews[index].startColor = color;
                    _arcViews[index].endColor = color;
                    var core = _arcCoreViews[index];
                    if (core != null)
                    {
                        var coreColor = core.startColor;
                        coreColor.a = alpha;
                        core.startColor = coreColor;
                        core.endColor = coreColor;
                    }
                }
                _arcEffects[index] = effect;
            }
        }

        private void StartRailTrail(Vector2 start, Vector2 end, float damage, int weaponIndex)
        {
            var slot = SelectRailTrailSlot(_railTrails);
            var trail = new RailTrailState
            {
                Active = true,
                Start = start,
                End = end,
                Life = 2.25f,
                DamageLife = 1.05f,
                Tick = 0,
                Damage = damage,
                WeaponIndex = weaponIndex,
                Sequence = _nextRailTrailSequence++,
                View = slot,
            };
            _railTrails[slot] = trail;
            EnsureRailTrailView(slot);
            RenderRailTrail(slot, trail);
        }

        private static int SelectRailTrailSlot(RailTrailState[] trails)
        {
            var slot = -1;
            var oldestSequence = int.MaxValue;
            for (var index = 0; index < trails.Length; index++)
            {
                if (!trails[index].Active) return index;
                if (trails[index].Sequence < oldestSequence)
                {
                    oldestSequence = trails[index].Sequence;
                    slot = index;
                }
            }
            return slot < 0 ? 0 : slot;
        }

        private void UpdateRailTrails(float dt)
        {
            // Browser railTrails is an append-ordered list updated newest first.
            // Slots are reusable, so array index is not insertion order after
            // the first oldest-trail replacement. Select by sequence instead.
            var processedMask = 0;
            for (var order = 0; order < _railTrails.Length; order++)
            {
                var index = -1;
                var newestSequence = int.MinValue;
                for (var candidate = 0; candidate < _railTrails.Length; candidate++)
                {
                    var bit = 1 << candidate;
                    var candidateTrail = _railTrails[candidate];
                    if ((processedMask & bit) != 0 || !candidateTrail.Active ||
                        candidateTrail.Sequence <= newestSequence) continue;
                    newestSequence = candidateTrail.Sequence;
                    index = candidate;
                }
                if (index < 0) break;
                processedMask |= 1 << index;
                var trail = _railTrails[index];
                trail.Life -= dt;
                trail.DamageLife -= dt;
                trail.Tick -= dt;
                if (trail.DamageLife > 0 && trail.Tick <= 0)
                {
                    trail.Tick = 0.22f;
                    var segmentDirection = trail.End - trail.Start;
                    var enemySnapshot = CaptureEnemyEffectSnapshot(out var enemySnapshotCount);
                    try
                    {
                        for (var target = 0; target < enemySnapshotCount; target++)
                        {
                            var snapshot = enemySnapshot[target];
                            if (!IsLiveEnemyEffectTarget(snapshot)) continue;
                            var enemy = snapshot.State;
                            if (enemy.Age < 0.15f || DistanceToSegment(enemy.Position, trail.Start, trail.End) > enemy.Radius + 13) continue;
                            ApplyEnemyDamage(snapshot.Slot, trail.Damage, segmentDirection, 42, false, trail.WeaponIndex);
                        }
                    }
                    finally
                    {
                        ReleaseEnemyEffectSnapshot(enemySnapshot);
                    }
                    EnsureBossOrderEntries();
                    for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
                    {
                        var bossIndex = _bossOrder[bossOrder];
                        var boss = _bosses[bossIndex];
                        if (!boss.Active || DistanceToSegment(boss.Position, trail.Start, trail.End) >= boss.Radius + 13) continue;
                        ApplyBossDamage(bossIndex, trail.Damage, trail.WeaponIndex);
                    }
                }

                if (trail.Life <= 0)
                {
                    trail.Active = false;
                    Hide(_railTrailViews[index]);
                }
                else
                {
                    RenderRailTrail(index, trail);
                }
                _railTrails[index] = trail;
            }
        }

        private void RenderRailTrail(int index, RailTrailState trail)
        {
            var mesh = _railTrailMeshViews[index]?.sharedMesh;
            if (mesh == null) return;

            var vertices = _railTrailVertices[index];
            var colors = _railTrailColors[index];
            var direction = trail.End - trail.Start;
            direction = SourceVisualDirection(direction);
            var normal = new Vector2(-direction.y, direction.x);
            var progress = Mathf.Clamp01(trail.Life / 2.25f);
            for (var segment = 0; segment < RailTrailSegmentCount; segment++)
            {
                var step = 0.16f + segment * 0.13f;
                var centre = Vector2.Lerp(trail.Start, trail.End, step) +
                    normal * (Mathf.Sin(step * 37f) * 5f);
                var halfLength = (16f + progress * 10f) * 0.5f;
                const float halfWidth = 1.5f;
                var along = direction * halfLength;
                var across = normal * halfWidth;
                var vertex = segment * 4;
                vertices[vertex] = centre - along - across;
                vertices[vertex + 1] = centre + along - across;
                vertices[vertex + 2] = centre + along + across;
                vertices[vertex + 3] = centre - along + across;

                var bright = step > 0.7f
                    ? new Color(0.914f, 0.835f, 1f, 1f)
                    : new Color(0.545f, 0.361f, 0.988f, 1f);
                bright.a = progress * (0.3f + step * 0.38f);
                colors[vertex] = bright;
                colors[vertex + 1] = bright;
                colors[vertex + 2] = bright;
                colors[vertex + 3] = bright;
            }
            mesh.SetVertices(vertices);
            mesh.SetColors(colors);
            mesh.SetTriangles(_railTrailTriangles[index], 0);
            mesh.RecalculateBounds();
            _railTrailViews[index].enabled = true;
        }

        private void RailgunImpact(Vector2 position, int hitCount)
        {
            var major = hitCount == 1 || hitCount % 3 == 0;
            BurstFx(position, SourceDotColor("white"), major ? 5 : 3, 230, 0.18f, 0.46f);
            if (_qualityPreset.ParticleScale > 0.01f)
                BurstFx(position, SourceDotColor("violet"), major ? 4 : 2, 180, 0.22f, 0.52f);
            if (major)
            {
                SpawnRingWave(
                    position,
                    5f,
                    105f,
                    0.18f,
                    new Color(0.78f, 0.68f, 1f, 0.78f));
            }
            TriggerFreeze(0.014f);
            AddCameraShake(0.022f);
            if (hitCount >= 3 && hitCount % 3 == 0)
            {
                SpawnFloater(
                    position + Vector2.up * 18f,
                    "x" + hitCount,
                    new Color(0.87f, 0.84f, 1f, 1f),
                    9);
            }
        }

        private static float DistanceToSegment(Vector2 point, Vector2 start, Vector2 end)
        {
            var segment = end - start;
            var lengthSquared = segment.sqrMagnitude;
            // Browser distanceToSegment() substitutes a unit denominator only
            // for an exactly zero-length segment. Do not widen that degenerate
            // case to tiny but valid segments.
            if (lengthSquared <= 0f) lengthSquared = 1f;
            var projection = Mathf.Clamp01(Vector2.Dot(point - start, segment) / lengthSquared);
            return Vector2.Distance(point, start + segment * projection);
        }

        private bool SpawnEnemy(string id)
        {
            return SpawnEnemy(id, null);
        }

        private static float EnemyHealthScaleAt(float elapsedSeconds, int bossCycle, float healthMultiplier)
        {
            var time = Mathf.Max(0, elapsedSeconds);
            var cycle = Mathf.Max(0, bossCycle);
            return (1f + time / 105f + Mathf.Pow(time / 420f, 1.45f) + cycle * 0.18f) *
                Mathf.Max(0, healthMultiplier);
        }

        private static float EnemySpeedScaleAt(float elapsedSeconds, int bossCycle)
        {
            var time = Mathf.Max(0, elapsedSeconds);
            var cycle = Mathf.Max(0, bossCycle);
            return Mathf.Min(1.52f, 1f + time / 1600f + cycle * 0.025f);
        }

        private static float EnemyDamageScaleAt(float elapsedSeconds, int bossCycle)
        {
            var time = Mathf.Max(0, elapsedSeconds);
            var cycle = Mathf.Max(0, bossCycle);
            return Mathf.Min(4.5f, 1f + time / 720f + cycle * 0.08f);
        }

        private static float HarvesterSpeedCapAt(float elapsedSeconds, int bossCycle)
        {
            return EnemySpeedScaleAt(elapsedSeconds, bossCycle) * 1.3f;
        }

        private static float HarvesterDamageGainScaleAt(float elapsedSeconds, int bossCycle)
        {
            return EnemyDamageScaleAt(elapsedSeconds, bossCycle);
        }

        private static float ExplosiveMeteorShardDamageAt(float elapsedSeconds, int bossCycle)
        {
            return (float)MeteorRules.ExplosiveShardDamage(
                elapsedSeconds,
                EnemyDamageScaleAt(elapsedSeconds, bossCycle));
        }

        private static int ExplosiveMeteorPlayerDamageAt(
            float elapsedSeconds,
            int bossCycle,
            float enemyDamage)
        {
            return MeteorRules.ExplosivePlayerDamage(
                enemyDamage,
                EnemyDamageScaleAt(elapsedSeconds, bossCycle));
        }

        private bool SpawnEnemy(
            string id,
            Vector2? forcedPosition,
            EliteVariantId? eliteKind,
            bool carrierDrone,
            bool splitterFragment)
        {
            return SpawnEnemy(
                id,
                forcedPosition,
                eliteKind,
                carrierDrone,
                splitterFragment,
                0);
        }

        private bool SpawnEnemy(
            string id,
            Vector2? forcedPosition,
            EliteVariantId? eliteKind,
            bool carrierDrone,
            bool splitterFragment,
            int summonedByBossTelemetryId)
        {
            return SpawnEnemy(
                id,
                forcedPosition,
                eliteKind,
                carrierDrone,
                splitterFragment,
                summonedByBossTelemetryId,
                1f,
                null);
        }

        private bool SpawnEnemy(
            string id,
            Vector2? forcedPosition,
            EliteVariantId? eliteKind = null,
            bool carrierDrone = false,
            bool splitterFragment = false,
            int summonedByBossTelemetryId = 0,
            float healthMultiplier = 1f,
            EnemyRoster? forcedRoster = null)
        {
            if (id == "harvester" && ActiveEnemyTypeCount(id) >= 3) return false;
            var slot = FindInactive(_enemies);
            if (slot < 0) return false;
            var standardElite = id == ContentCatalog.Elite.Id;
            var definition = standardElite ? null : FindEnemy(id);
            if (!standardElite && definition == null) return false;
            var elite = standardElite || eliteKind.HasValue;
            DiscoverBestiary(id);
            if (elite) DiscoverBestiary("elite");
            var variantDefinition = eliteKind.HasValue ? EliteRules.EliteVariantDef(eliteKind.Value) : null;
            var variantStats = eliteKind.HasValue
                ? EliteRules.EliteVariantStatsFor(eliteKind.Value)
                : default(EliteVariantStats);
            var enemyId = _nextEnemyId++;
            var roster = forcedRoster ?? (elite || carrierDrone || splitterFragment
                ? EnemyRoster.One
                : EnemyRosterRules.EnemyRosterForSpawn(
                    id,
                    _time,
                    EnemyRosterRules.RosterSpawnRoll(_runSeed, enemyId)));
            var angle = (float)(_rng.Next() * Math.PI * 2);
            var viewportHalf = GameplayViewportHalfExtent();
            var distance = Mathf.Sqrt(
                    Mathf.Pow(viewportHalf.x * 2f, 2) + Mathf.Pow(viewportHalf.y * 2f, 2)) * 0.5f +
                70f + (float)_rng.Next() * 130f;
            var position = forcedPosition ?? _playerPosition + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * distance;
            // Browser carrier drones pass hpScale=0.55 through spawnEnemy;
            // keep that source-specific health reduction coupled to the flag
            // so every carrier-drone spawn path uses the same rule.
            var healthScale = EnemyHealthScaleAt(
                _time,
                _bossCycle,
                healthMultiplier * (carrierDrone ? 0.55f : 1f));
            var speedScale = EnemySpeedScaleAt(_time, _bossCycle);
            var damageScale = EnemyDamageScaleAt(_time, _bossCycle);
            var rosterHealth = roster == EnemyRoster.Two ? EnemyRosterRules.RosterTwoHealthMultiplier : 1;
            var rosterRadius = roster == EnemyRoster.Two ? EnemyRosterRules.RosterTwoRadiusMultiplier : 1;
            var rosterSpeed = roster == EnemyRoster.Two ? EnemyRosterRules.RosterTwoSpeedMultiplier : 1;
            var rosterDamage = roster == EnemyRoster.Two ? EnemyRosterRules.RosterTwoDamageMultiplier : 1;
            var baseHealth = eliteKind.HasValue
                ? variantStats.Health
                : standardElite ? ContentCatalog.Elite.Health : definition.Health;
            var baseSpeed = eliteKind.HasValue
                ? variantStats.Speed
                : (standardElite ? ContentCatalog.Elite.Speed : definition.Speed) *
                    (splitterFragment ? 1.55 : carrierDrone ? 1.18 : 1);
            var baseRadius = eliteKind.HasValue
                ? variantStats.Radius
                : (splitterFragment ? 8 : carrierDrone ? 7 : standardElite ? ContentCatalog.Elite.Radius : definition.Radius);
            var baseDamage = eliteKind.HasValue
                ? variantStats.ContactDamage
                : (standardElite ? ContentCatalog.Elite.ContactDamage : definition.ContactDamage) *
                    (splitterFragment ? 0.55 : carrierDrone ? 0.7 : 1);
            var baseXp = splitterFragment || carrierDrone
                ? 1
                : standardElite ? ContentCatalog.Elite.Xp : definition.Xp;
            var shield = !elite && id == "guard"
                ? (float)((definition.Shield ?? 0) * healthScale * rosterHealth)
                : 0;
            var enemy = new EnemyState
            {
                Active = true,
                Id = id,
                Position = position,
                MaxHealth = (float)baseHealth * healthScale * (float)rosterHealth,
                Radius = (float)baseRadius * (float)rosterRadius,
                Speed = (float)baseSpeed * speedScale * (float)rosterSpeed * (0.92f + (float)_rng.Next() * 0.16f),
                Damage = (float)baseDamage * damageScale * (float)rosterDamage,
                Xp = Mathf.Max(1, SourceRound((float)(baseXp * (roster == EnemyRoster.Two ? EnemyRosterRules.RosterTwoXpMultiplier : 1)))),
                Age = 0,
                Shield = shield,
                MaxShield = shield,
                Roster = roster,
                Elite = elite,
                EliteKind = eliteKind,
                CarrierDrone = carrierDrone,
                SplitterFragment = splitterFragment,
                SummonedByBossTelemetryId = summonedByBossTelemetryId,
                SummonedByCarrierSpawnId = 0,
                SpawnId = enemyId,
                Facing = (_playerPosition - position).sqrMagnitude > 0.001f
                    ? (_playerPosition - position).normalized
                    : Vector2.right,
                State = 0,
                StateTimer = standardElite
                    ? 2.2f
                    : eliteKind.HasValue ? (float)variantStats.TelegraphSeconds : 0,
                AttackCooldown = !elite &&
                    (id == "gunner" ||
                        id == "twinGunner" ||
                        id == "technician" ||
                        id == "mortar" ||
                        id == "carrier" ||
                        (roster == EnemyRoster.Two && id == "guard"))
                    ? 1.2f + (float)_rng.Next()
                    : 0,
                Rotation = (float)(_rng.Next() * Math.PI * 2),
                Spin = !elite && id == "exploder"
                    ? (_rng.Next() < 0.5 ? -0.48f : 0.48f)
                    : ((float)_rng.Next() - 0.5f) * 2.2f,
                Seed = (float)_rng.Next() * 100,
                Volley = 0,
                View = slot,
            };
            if (eliteKind.HasValue && eliteKind.Value == EliteVariantId.Exploder)
                enemy.Spin = _rng.Next() < 0.5 ? -0.42f : 0.42f;
            enemy.Health = enemy.MaxHealth;
            _enemies[slot] = enemy;
            AppendEnemyOrder(slot);
            if (elite)
                _telemetry.RecordEliteSpawn(
                    ArenaIdName(_arenaId),
                    standardElite ? "standard" : variantDefinition.BaseId);
            else if (roster == EnemyRoster.Two)
                _telemetry.RecordRosterTwoSpawn(ArenaIdName(_arenaId));
            var view = EnsureEnemyView(slot);
            var accent = eliteKind.HasValue
                ? ParseColor(variantDefinition.Accent, Color.magenta)
                : standardElite
                    ? ParseColor(ContentCatalog.Elite.Color, Color.yellow)
                : ParseColor(definition.Color, Color.magenta);
            view.sprite = ProceduralSpriteFactory.Enemy(
                SourceEnemySpriteId(id, elite, variantDefinition?.BaseId),
                EnemySpriteAccent(enemy),
                false);
            view.color = Color.white;
            view.enabled = true;
            return true;
        }

        private void SpawnBoss(string id, double healthScale, double damageScale)
        {
            var encounterCycle = Mathf.Max(0, (_bossSequence - 1) / Mathf.Max(1, ContentCatalog.Bosses.Length));
            SpawnBoss(id, healthScale, damageScale, encounterCycle);
        }

        private void SpawnBoss(string id, double healthScale, double damageScale, int encounterCycle)
        {
            // The browser keeps defeated bosses in its array until the 1.4 s
            // fade is over. Do not overwrite that logical entry early just
            // because its fixed Unity slot is no longer damageable.
            var slot = FindInactiveBossSlot();
            if (slot < 0) return;
            var definition = FindBoss(id);
            if (definition == null) return;
            _bossCycle = Mathf.Max(_bossCycle, Mathf.Max(0, encounterCycle));
            var activeBeforeSpawn = ActiveBosses();
            DiscoverBestiary(id);
            var angle = (float)(_rng.Next() * Math.PI * 2) +
                activeBeforeSpawn * (Mathf.PI * 2f / Mathf.Max(2, activeBeforeSpawn + 1));
            var viewportHalf = GameplayViewportHalfExtent();
            var distance = Mathf.Min(
                480f,
                Mathf.Sqrt(Mathf.Pow(viewportHalf.x * 2f, 2) + Mathf.Pow(viewportHalf.y * 2f, 2)) * 0.5f + 120f);
            var position = _playerPosition + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * distance;
            var boss = new BossState
            {
                Active = true,
                Id = id,
                Position = position,
                MaxHealth = (float)(definition.Health * healthScale * DirectorRules.BossHealthScaleAt(_time, id)),
                Radius = (float)definition.Radius,
                Speed = (float)definition.Speed,
                Damage = (float)(definition.ContactDamage * damageScale),
                DamageScale = (float)damageScale,
                AttackCooldown = 1.2f + activeBeforeSpawn * 0.8f,
                State = 4,
                StateTimer = 1.6f,
                DeathTimer = 0,
                AttackIndex = 0,
                Reinforced = false,
                TierPressureTriggered = false,
                PressureTier = DirectorRules.BossPressureTierAt(_time),
                EncounterIndex = Mathf.Max(0, _bossSequence - 1),
                TargetPosition = position,
                TelemetryInstanceId = _nextBossTelemetryId++,
                View = slot,
            };
            boss.Health = boss.MaxHealth;
            _bosses[slot] = boss;
            AppendBossOrder(slot);
            _telemetry.RecordBossSpawn(
                id,
                boss.TelemetryInstanceId,
                Mathf.Max(0, _bossSequence - 1),
                (float)_time,
                boss.MaxHealth,
                Mathf.Max(0, ActiveBosses() - 1));
            var view = EnsureBossView(slot);
            view.sprite = ProceduralSpriteFactory.Boss(
                id,
                ParseColor(definition.Color, Color.magenta),
                false);
            view.color = Color.white;
            view.enabled = true;
            TriggerFreeze(0.06f);
            var bossAccent = BossAccent(boss);
            bossAccent.a = 0.78f;
            SpawnRingWave(position, 30f, 420f, 0.6f, bossAccent);
            BurstFx(position, BossParticleColor(boss.Id), 18, 300, 0.6f, 0.9f);
        }

        private int FindInactiveBossSlot()
        {
            for (var index = 0; index < _bosses.Length; index++)
            {
                if (!_bosses[index].Active && _bosses[index].DeathTimer <= 0) return index;
            }
            return -1;
        }

        private void SpawnHostileShot(
            Vector2 position,
            Vector2 direction,
            float damage,
            float speed,
            float curvature,
            bool meteorOwned = false,
            int visualVariant = -1)
        {
            var slot = FindInactive(_hostileShots);
            if (slot < 0) return;
            // Browser spawnHostileShot uses an exact non-zero check for
            // curvature; tiny valid values still consume the curved-shot cap
            // and receive lateral acceleration.
            var curved = curvature != 0f;
            if (curved && _curvedShotCount >= EliteRules.MaxCurvedProjectiles) return;
            // Browser spawnHostileShot stores the supplied nx/ny directly; it
            // does not substitute a right-facing unit vector for zero input.
            var angle = Mathf.Atan2(direction.y, direction.x);
            var acceleration = curved
                ? new Vector2(
                    Mathf.Cos(angle + Mathf.PI / 2) * curvature * (float)EliteRules.CurvedLateralAcceleration,
                    Mathf.Sin(angle + Mathf.PI / 2) * curvature * (float)EliteRules.CurvedLateralAcceleration)
                : Vector2.zero;
            _hostileShots[slot] = new HostileShotState
            {
                Active = true,
                Position = position,
                Velocity = direction * speed,
                Acceleration = acceleration,
                Damage = damage,
                Life = curved ? 3.6f : 3.2f,
                Radius = curved ? 7f : 6f,
                Curved = curved,
                MeteorOwned = meteorOwned,
                Variant = visualVariant,
                View = slot,
            };
            AppendHostileShotOrder(slot);
            if (curved) _curvedShotCount++;
            var view = EnsureHostileShotView(slot);
            view.sprite = curved
                ? ProceduralSpriteFactory.Projectile("curved")
                : meteorOwned
                    ? ProceduralSpriteFactory.MeteorCore()
                    : ProceduralSpriteFactory.ProjectileFrame(
                        "gunner",
                        SourceProjectileFrameIndex(direction));
            view.sharedMaterial = meteorOwned ? ResolveAdditiveSpriteMaterial() : null;
            view.transform.rotation = Quaternion.identity;
            // Browser meteor-owned hostile shots draw the hot core at a fixed
            // 18 px square with 0.82 alpha; ordinary and curved shots keep
            // their authored sprite alpha untouched.
            view.color = meteorOwned ? new Color(1f, 1f, 1f, 0.82f) : Color.white;
            view.enabled = true;
        }

        private void UpdateHostileShots(float dt)
        {
            EnsureHostileShotOrderEntries();
            var initialOrderCount = _hostileShotOrderCount;
            for (var order = initialOrderCount - 1; order >= 0; order--)
            {
                var index = _hostileShotOrder[order];
                var shot = _hostileShots[index];
                if (!shot.Active)
                {
                    RemoveHostileShotOrder(index);
                    continue;
                }
                if (shot.Curved) shot.Velocity += shot.Acceleration * dt;
                shot.Position += shot.Velocity * dt;
                shot.Life -= dt;
                if (shot.Life > 0 && _playerHealth > 0 && !_gameOver && !_revivePending &&
                    _dyingTimer <= 0 && _playerIframes <= 0 &&
                    Vector2.Distance(shot.Position, _playerPosition) < shot.Radius + AttackPlayerRadius)
                {
                    var impactDirection = shot.Velocity / SourceLengthOrOne(shot.Velocity);
                    DamagePlayer(shot.Damage, impactDirection);
                    if (shot.MeteorOwned) _telemetry.RecordMeteorPlayerHit(ArenaIdName(_arenaId));
                    shot.Life = 0;
                }

                if (shot.Life <= 0)
                {
                    shot.Active = false;
                    if (shot.Curved) _curvedShotCount = Mathf.Max(0, _curvedShotCount - 1);
                    Hide(_hostileShotViews[index]);
                    RemoveHostileShotOrder(index);
                }

                _hostileShots[index] = shot;
            }
        }

        private void SpawnPickup(Vector2 position, float value)
        {
            var drops = PickupRules.XpDropValues(
                Mathf.Max(0, Mathf.FloorToInt(value)),
                () => _rng.Next());
            var released = 0;
            for (var index = 0; index < drops.Length; index++)
            {
                var drop = drops[index];
                released += drop;
                var slot = FindInactive(_pickups);
                if (slot < 0)
                {
                    var target = FindXpOverflowTarget(position);
                    if (target >= 0)
                    {
                        var existing = _pickups[target];
                        existing.Value += drop;
                        existing.Position = position;
                        var mergeAngle = (float)(_rng.Next() * Math.PI * 2);
                        var mergeSpeed = 40f + (float)_rng.Next() * 60f;
                        existing.Velocity = new Vector2(Mathf.Cos(mergeAngle), Mathf.Sin(mergeAngle)) * mergeSpeed;
                        existing.Age = 0;
                        existing.Pull = false;
                        existing.Speed = 0;
                        _pickups[target] = existing;
                        RefreshPickupView(target);
                    }
                    // The extra pickup slot preserves one XP gem when a full
                    // set consists entirely of special drops. If that slot is
                    // also occupied, the browser has no reclaimable target.
                    continue;
                }

                var angle = (float)(_rng.Next() * Math.PI * 2);
                var speed = 40f + (float)_rng.Next() * 85f;
                _pickups[slot] = new PickupState
                {
                    Active = true,
                    Position = position,
                    Velocity = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * speed,
                    Value = drop,
                    Age = (float)_rng.Next() * 5f,
                    Speed = 0,
                    Kind = PickupKind.Xp,
                    Pull = false,
                    View = slot,
                };
                AppendPickupOrder(slot);
                RefreshPickupView(slot);
            }
            if (released > 0) _telemetry.RecordXpReleased(released);
        }

        private bool SpawnSpecialPickup(Vector2 position, float value, PickupKind kind)
        {
            var slot = FindInactive(_pickups);
            if (slot < 0) return false;
            _pickups[slot] = new PickupState
            {
                Active = true,
                Position = position,
                Velocity = new Vector2(
                    ((float)_rng.Next() - 0.5f) * 90f,
                    ((float)_rng.Next() - 0.5f) * 90f),
                Value = value,
                Age = 0,
                Speed = 0,
                Kind = kind,
                Pull = false,
                View = slot,
            };
            AppendPickupOrder(slot);
            RefreshPickupView(slot);
            return true;
        }

        private void SpawnRarePickup(Vector2 position)
        {
            var roll = _rng.Next();
            var kind = roll < 0.3
                ? PickupKind.Magnet
                : roll < 0.64
                    ? PickupKind.Repair
                    : roll < 0.86
                        ? PickupKind.Bomb
                        : PickupKind.Overdrive;
            SpawnSpecialPickup(position, 1, kind);
        }

        private void RefreshPickupView(int slot)
        {
            var pickup = _pickups[slot];
            var view = EnsurePickupView(slot);
            view.sprite = pickup.Kind == PickupKind.Xp
                ? ProceduralSpriteFactory.Gem(XpPickupTier(pickup.Value))
                : ProceduralSpriteFactory.Pickup(PickupKindName(pickup.Kind));
            view.color = Color.white;
            view.enabled = true;
        }

        private int FindXpOverflowTarget(Vector2 dropPosition)
        {
            var nearbyIndex = -1;
            var nearbyDistanceSquared = 180f * 180f;
            var farthestIndex = -1;
            var farthestDistanceSquared = -1f;
            for (var index = 0; index < _pickups.Length; index++)
            {
                var pickup = _pickups[index];
                if (!pickup.Active || pickup.Kind != PickupKind.Xp) continue;
                var dropDistanceSquared = (pickup.Position - dropPosition).sqrMagnitude;
                if (dropDistanceSquared < nearbyDistanceSquared)
                {
                    nearbyDistanceSquared = dropDistanceSquared;
                    nearbyIndex = index;
                }
                var playerDistanceSquared = (pickup.Position - _playerPosition).sqrMagnitude;
                if (playerDistanceSquared > farthestDistanceSquared)
                {
                    farthestDistanceSquared = playerDistanceSquared;
                    farthestIndex = index;
                }
            }
            return nearbyIndex >= 0 ? nearbyIndex : farthestIndex;
        }

        private static string PickupKindName(PickupKind kind)
        {
            switch (kind)
            {
                case PickupKind.Xp: return "xp";
                case PickupKind.Part: return "part";
                case PickupKind.Magnet: return "magnet";
                case PickupKind.Repair: return "repair";
                case PickupKind.Bomb: return "bomb";
                case PickupKind.Overdrive: return "overdrive";
                default: return "unknown";
            }
        }

        private static int XpPickupTier(float value)
        {
            return value >= 10 ? 2 : value >= 4 ? 1 : 0;
        }

        private static float SourcePickupPulseScale(string kind, float age, bool pickupPulse)
        {
            if (!pickupPulse) return kind == "xp" ? 1f : 0.88f;
            var pulse = Mathf.Sin(age * 5f);
            return kind == "xp" ? 1f + pulse * 0.1f : 0.88f + pulse * 0.06f;
        }

        private static float SourcePickupRotationRadians(string kind, float age)
        {
            return kind == "part" || kind == "bomb" ? age * 0.7f : 0f;
        }

        private static float SourceXpPickupTierScale(int tier)
        {
            return Mathf.Clamp(tier, 0, 2) == 0
                ? 1f
                : tier == 1 ? 60f / 52f : 72f / 52f;
        }

        private static float SourceXpPickupFrameSize(int tier)
        {
            return Mathf.Clamp(tier, 0, 2) == 0
                ? 52f
                : tier == 1 ? 60f : 72f;
        }

        private static float SourceSpecialPickupFrameSize()
        {
            return 42f;
        }

        private static bool SourceEnemyVisualFlash(
            string id,
            bool elite,
            int state,
            float hitTimer,
            bool harvesterFull,
            float seed,
            float ambientClock)
        {
            return hitTimer > 0
                || (elite && state == 1 && Mathf.Sin(ambientClock * 30f) > 0)
                || (id == "dasher" && state == 1 && Mathf.Sin(ambientClock * 36f) > 0)
                || (id == "gunner" && state == 1 && Mathf.Sin(ambientClock * 28f) > 0)
                || (id == "twinGunner" && state == 1 && Mathf.Sin(ambientClock * 28f) > 0)
                || (harvesterFull && Mathf.Sin(ambientClock * 9f + seed) > 0.35f);
        }

        private static float SourceEnemyRotationFromDirection(Vector2 direction)
        {
            return direction.sqrMagnitude > 0f
                ? Mathf.Atan2(direction.y, direction.x)
                : 0f;
        }

        private static float SourceLengthOrOne(Vector2 value)
        {
            var length = value.magnitude;
            return length > 0f ? length : 1f;
        }

        private static Vector2 SourcePickupPullVelocity(Vector2 delta, float speed)
        {
            // Browser updatePickups divides by Math.sqrt(distanceSq) || 1:
            // tiny non-zero offsets still become a full-speed pull vector.
            return delta / SourceLengthOrOne(delta) * speed;
        }

        private static Vector2 SourceNormalizedDirection(Vector2 value)
        {
            var length = value.magnitude;
            // Mirrors combat.normalizedDirection(): tiny finite vectors are
            // treated as stationary, while larger vectors are normalized.
            if (float.IsNaN(length) || float.IsInfinity(length) || length < 0.0001f)
                return Vector2.zero;
            return value / length;
        }

        private static float SourceEnemyRotationAdvance(float rotation, float spin, float dt)
        {
            return rotation + spin * dt;
        }

        private static float SourceHarvesterFullOverlayAlpha(float ambientClock, float seed)
        {
            return 0.16f + (0.5f + Mathf.Sin(ambientClock * 7f + seed) * 0.5f) * 0.2f;
        }

        private static float SourceEliteRingSize(float ambientClock)
        {
            return 112f * (1f + Mathf.Sin(ambientClock * 4f) * 0.1f);
        }

        private static float SourceEliteRingAlpha(bool eliteVariant)
        {
            return eliteVariant ? 0.55f : 0.4f;
        }

        private static float SourceBossBodyRotationRadians(float ambientClock)
        {
            return Mathf.Sin(ambientClock * 0.8f) * 0.05f;
        }

        private static float SourceLowHealthOverlayAlpha(bool lowHealth, float ambientClock)
        {
            return lowHealth ? 0.28f + 0.14f * Mathf.Sin(ambientClock * 5f) : 0f;
        }

        private static float SourceEnemyIntroScale(float age)
        {
            if (age >= 0.35f) return 1f;
            var progress = Mathf.Clamp01(age / 0.35f);
            return BackOut(progress);
        }

        private static float SourceExploderArmedScale(
            float stateTimer,
            float telegraph,
            float ambientClock)
        {
            var progress = Mathf.Clamp01(1f - stateTimer / Mathf.Max(0.01f, telegraph));
            return 1f + progress * 0.16f +
                Mathf.Max(0f, Mathf.Sin(ambientClock * (16f + progress * 10f))) * 0.06f;
        }

        private static float SourceExploderWarningAlpha(
            float stateTimer,
            float telegraph,
            bool eliteExploder,
            float ambientClock)
        {
            var progress = Mathf.Clamp01(1f - stateTimer / Mathf.Max(0.01f, telegraph));
            var pulseRate = eliteExploder
                ? (float)EliteRules.EliteExploderFlashRate(stateTimer, telegraph)
                : 7f + progress * 20f;
            var pulse = 0.5f + Mathf.Sin(ambientClock * pulseRate) * 0.5f;
            var hardFlash = pulse > 0.58f - progress * 0.22f;
            return hardFlash
                ? 0.34f + progress * 0.24f
                : 0.08f + pulse * 0.1f;
        }

        private void ApplyEnemyDamage(int index, float damage)
        {
            ApplyEnemyDamage(index, damage, Vector2.zero, 0, false, -1);
        }

        private static void ApplySourcePlayerKnockback(ref EnemyState enemy, Vector2 impactDirection)
        {
            var direction = SourceNormalizedDirection(impactDirection);
            if (direction == Vector2.zero) return;
            var resistance = enemy.Elite ? 0.12f : enemy.Id == "brute" ? 0.32f : 1f;
            enemy.Knockback -= direction * 150f * resistance;
        }

        private void DamagePlayer(float damage, Vector2 sourceDirection)
        {
            if (_gameOver || _revivePending || _dyingTimer > 0 || _playerIframes > 0) return;
            var appliedDamage = Mathf.Max(1, damage);
            // Commit the browser's player state before any hurt presentation:
            // later effects in the same simulation step observe the reduced
            // health, pressure timer, and invulnerability window immediately.
            _damageTaken += appliedDamage;
            _playerHealth -= appliedDamage;
            _pressureReliefTimer = Mathf.Max(
                _pressureReliefTimer,
                _playerHealth < _playerMaxHealth * 0.35f ? 5f : 2.5f);
            _playerIframes = 0.65f;
            _redFlash = 1f;
            TriggerFreeze(0.04f);
            _audio?.Play(ProceduralAudio.Cue.Hurt, 0.82f);
            AddCameraShake(0.5f);
            BurstFx(_playerPosition, SourceDotColor("red"), 9, 250, 0.48f, 0.85f);
            SpawnDamageIndicator(sourceDirection);
            var impactDirection = SourceNormalizedDirection(sourceDirection);
            if (impactDirection != Vector2.zero)
                _playerVelocity += impactDirection * 250f;
            if (SupportRank("adrenal") > 0 && _playerHealth > 0)
            {
                _adrenalTimer = 5;
                _amberFlash = Mathf.Max(_amberFlash, 0.15f);
                SpawnFloater(
                    _playerPosition + Vector2.up * 22f,
                    "ADRENAL SURGE",
                    new Color(0.984f, 0.576f, 0.188f, 1f),
                    12);
            }
            if (_playerHealth <= 0)
            {
                _playerHealth = 0;
                _dyingTimer = 1.1f;
                _playerIframes = 10f;
                _targetTimeScale = 0.22f;
                TriggerFreeze(0.08f);
                AddCameraShake(1f);
                // Browser authority gives a revivable defeat the boss cue, and
                // reserves the full game-over sting for a terminal defeat.
                _audio?.Play(DefeatCueFor(_revivesRemaining));
                BurstFx(_playerPosition, SourceDotColor("cyan"), 34, 390, 0.85f, 1.1f);
                BurstFx(_playerPosition, SourceDotColor("white"), 18, 270, 0.65f, 0.85f);
                SpawnRingWave(
                    _playerPosition,
                    20f,
                    320f,
                    0.68f,
                    new Color(0.133f, 0.827f, 0.933f, 1f));
            }
        }

        private void ApplyEnemyDamage(
            int index,
            float damage,
            Vector2 direction,
            float knockback,
            bool critical,
            int weaponIndex = -1)
        {
            var enemy = _enemies[index];
            if (!enemy.Active) return;
            var appliedDamage = Mathf.Max(0, damage);
            if (enemy.Id == "bulwark" && direction.sqrMagnitude > 0.001f)
            {
                var sourceDirection = -direction.normalized;
                if (Vector2.Dot(enemy.Facing, sourceDirection) > Mathf.Cos(1.08f))
                {
                    appliedDamage *= 0.25f;
                    if (enemy.BlockCooldown <= 0)
                    {
                        enemy.BlockCooldown = 0.16f;
                        SpawnFloater(
                            enemy.Position + Vector2.up * enemy.Radius,
                            "BLOCK",
                            new Color(0.49f, 0.82f, 0.99f, 1f),
                            10);
                        BurstFx(enemy.Position, SourceDotColor("cyan"), 3, 110, 0.22f, 0.5f);
                    }
                }
            }
            var remaining = appliedDamage;
            var shieldBroken = false;
            if (enemy.Shield > 0)
            {
                var absorbed = Mathf.Min(enemy.Shield, remaining);
                enemy.Shield -= absorbed;
                remaining -= absorbed;
                _damageDealt += absorbed;
                TrackWeaponDamage(weaponIndex, absorbed);
                shieldBroken = absorbed > 0 && enemy.Shield <= 0;
            }

            if (shieldBroken)
            {
                BurstFx(enemy.Position, SourceDotColor("cyan"), 12, 220, 0.45f, 0.8f);
                SpawnRingWave(enemy.Position, enemy.Radius, 150f, 0.35f,
                    new Color(0.35f, 0.85f, 1f, 0.72f));
                _audio?.Play(ProceduralAudio.Cue.ShieldBreak, 0.9f);
            }

            var appliedHealth = Mathf.Min(Mathf.Max(0, remaining), enemy.Health);
            enemy.Health -= remaining;
            enemy.HitTimer = 0.09f;
            _damageDealt += appliedHealth;
            TrackWeaponDamage(weaponIndex, appliedHealth);
            if (knockback > 0)
            {
                var resistance = enemy.Id == "brute" ? 0.28f : enemy.Elite ? 0.1f : 1f;
                enemy.Knockback += direction / SourceLengthOrOne(direction) * knockback * resistance;
            }
            _enemies[index] = enemy;
            if (remaining > 0)
            {
                // Browser damageEnemy creates the damage number before the
                // hit burst, so the shared FX RNG stays source-ordered.
                SpawnDamageFloater(
                    index + 1,
                    enemy.Position + Vector2.up * enemy.Radius,
                    remaining,
                    critical);
                BurstFx(enemy.Position, EnemyParticleColor(enemy), critical ? 5 : 3, 190, 0.35f, 0.7f);
                _audio?.Play(ProceduralAudio.Cue.Hit, critical ? 1f : 0.9f);
                if (critical)
                {
                    _audio?.Play(ProceduralAudio.Cue.Crit, 1f);
                    TriggerFreeze(0.018f);
                }
            }
            if (critical && SupportRank("overload") > 0 && remaining > 0)
            {
                DamageOverloadArea(enemy.Position, 76f * _areaMultiplier,
                    remaining * 0.25f * SupportRank("overload"),
                    EnemyIdentity(enemy, index), weaponIndex);
                BurstFx(enemy.Position, SourceDotColor("cyan"),
                    4, 160, 0.3f, 0.6f);
            }
            if (enemy.Health <= 0) KillEnemy(index);
        }

        private bool IsMatriarchShielded(BossState boss)
        {
            if (!boss.Active || boss.Id != "matriarch" || boss.TelemetryInstanceId <= 0) return false;
            var livingSummons = 0;
            for (var index = 0; index < _enemies.Length; index++)
            {
                var enemy = _enemies[index];
                if (!enemy.Active || enemy.SummonedByBossTelemetryId != boss.TelemetryInstanceId) continue;
                livingSummons++;
                if (livingSummons >= 3) return true;
            }
            return false;
        }

        private void ApplyBossDamage(int index, float damage, int weaponIndex = -1, bool critical = false)
        {
            if (index < 0 || index >= _bosses.Length) return;
            var boss = _bosses[index];
            if (!boss.Active || boss.State == 4) return;
            if (IsMatriarchShielded(boss))
            {
                if (boss.ShieldHitTimer <= 0)
                {
                    boss.ShieldHitTimer = 0.24f;
                    SpawnFloater(
                        boss.Position + Vector2.up * boss.Radius,
                        "SHIELDED",
                        new Color(0.431f, 0.906f, 0.718f, 1f),
                        12);
                    BurstFx(
                        boss.Position,
                        SourceDotColor("emerald"),
                        4,
                        150,
                        0.3f,
                        0.65f);
                }
                _bosses[index] = boss;
                return;
            }
            var appliedDamage = Mathf.Min(Mathf.Max(0, damage), boss.Health);
            _damageDealt += appliedDamage;
            TrackWeaponDamage(weaponIndex, appliedDamage);
            boss.Health -= appliedDamage;
            boss.HitTimer = 0.08f;
            _bosses[index] = boss;
            if (appliedDamage > 0)
            {
                // Browser damageBoss creates the damage number before the
                // hit burst, preserving the shared FX RNG sequence.
                SpawnDamageFloater(
                    MaxEnemies + index + 1,
                    boss.Position + Vector2.up * boss.Radius,
                    appliedDamage,
                    critical);
                BurstFx(boss.Position, BossParticleColor(boss.Id), critical ? 5 : 3, 180, 0.32f, 0.7f);
                _audio?.Play(ProceduralAudio.Cue.Hit, critical ? 1f : 0.9f);
                if (critical) _audio?.Play(ProceduralAudio.Cue.Crit, 1f);
            }
            if (boss.Health <= 0) KillBoss(index);
        }

        private void DamageOverloadArea(
            Vector2 origin,
            float radius,
            float damage,
            int excludedEnemyIdentity,
            int weaponIndex)
        {
            // Browser overload uses its own copied enemy/boss loops. It does
            // not call damageArea: meteors and the orange blast presentation
            // must stay out of this critical-hit-only effect.
            var enemySnapshot = CaptureEnemyEffectSnapshot(out var enemySnapshotCount);
            try
            {
                for (var target = 0; target < enemySnapshotCount; target++)
                {
                    var snapshot = enemySnapshot[target];
                    if (EnemyIdentity(snapshot.State, snapshot.Slot) == excludedEnemyIdentity ||
                        !IsLiveEnemyEffectTarget(snapshot)) continue;
                    var enemy = snapshot.State;
                    var delta = enemy.Position - origin;
                    var reach = radius + enemy.Radius;
                    if (delta.sqrMagnitude >= reach * reach) continue;
                    ApplyEnemyDamage(snapshot.Slot, damage, delta, 60, false, weaponIndex);
                }
            }
            finally
            {
                ReleaseEnemyEffectSnapshot(enemySnapshot);
            }

            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4) continue;
                var delta = boss.Position - origin;
                if (delta.sqrMagnitude >= (radius + boss.Radius) * (radius + boss.Radius)) continue;
                ApplyBossDamage(index, damage, weaponIndex, false);
            }
        }

        private void DamageArea(
            Vector2 origin,
            float radius,
            float damage,
            int excludedEnemyIdentity,
            int weaponIndex = -1)
        {
            DamageMeteorsInRadius(origin, radius, damage);
            var cellSpan = Mathf.CeilToInt(radius / CollisionGrid.CellSize) + 1;
            var candidateCount = _enemyGrid.QueryNeighborhood(
                origin.x,
                origin.y,
                cellSpan,
                _enemyGridAreaCandidates);
            // The browser grid stores enemy object references. Capture the
            // queried identities before applying damage so recursive effects
            // cannot read a newly spawned enemy from a recycled pooled slot.
            var enemySnapshot = ArrayPool<EnemyEffectTarget>.Shared.Rent(Math.Max(1, candidateCount));
            var enemySnapshotCount = 0;
            try
            {
                for (var candidate = 0; candidate < candidateCount; candidate++)
                {
                    var index = _enemyGridAreaCandidates[candidate];
                    var enemy = _enemies[index];
                    if (!IsCurrentGridEnemy(index) ||
                        EnemyIdentity(enemy, index) == excludedEnemyIdentity) continue;
                    enemySnapshot[enemySnapshotCount++] = new EnemyEffectTarget
                    {
                        Slot = index,
                        State = enemy,
                    };
                }
                for (var target = 0; target < enemySnapshotCount; target++)
                {
                    var snapshot = enemySnapshot[target];
                    if (!IsLiveEnemyEffectTarget(snapshot)) continue;
                    var enemy = snapshot.State;
                    var reach = radius + enemy.Radius;
                    if ((enemy.Position - origin).sqrMagnitude >= reach * reach) continue;
                    ApplyEnemyDamage(snapshot.Slot, damage, enemy.Position - origin, 90, false, weaponIndex);
                }
            }
            finally
            {
                ReleaseEnemyEffectSnapshot(enemySnapshot);
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4) continue;
                var reach = radius + boss.Radius;
                if ((boss.Position - origin).sqrMagnitude >= reach * reach) continue;
                ApplyBossDamage(index, damage, weaponIndex);
            }
            // The browser's shared damageArea presentation is emitted once
            // after all target resolution, including meteor-only blasts.
            BurstFx(origin, SourceDotColor("orange"), 8, 190, 0.35f, 0.7f);
            SpawnRingWave(
                origin,
                8f,
                radius * 2f,
                0.3f,
                new Color(1f, 0.46f, 0.12f, 0.68f));
        }

        private void DamageMeteorsInRadius(Vector2 origin, float radius, float damage)
        {
            EnsureMeteorOrderEntries();
            for (var order = _meteorOrderCount - 1; order >= 0; order--)
            {
                var index = _meteorOrder[order];
                var meteor = _meteors[index];
                if (!meteor.Active || meteor.FuseTimer > 0) continue;
                var reach = radius + meteor.Radius;
                if ((meteor.Position - origin).sqrMagnitude > reach * reach) continue;
                DamageMeteor(index, damage);
            }
        }

        private bool DamageMeteor(int index, float damage)
        {
            if (index < 0 || index >= _meteors.Length) return false;
            var meteor = _meteors[index];
            if (!meteor.Active || meteor.FuseTimer > 0) return false;
            meteor.Health -= damage;
            meteor.HitTimer = 0.09f;
            if (meteor.Health > 0)
            {
                _meteors[index] = meteor;
                return true;
            }

            meteor.Health = 0;
            if (meteor.Explosive)
            {
                _telemetry.RecordMeteorDestroyed(ArenaIdName(_arenaId), true);
                meteor.FuseTimer = (float)MeteorRules.ExplosiveFlashSeconds;
                PlayFuseWarning(5);
                _meteors[index] = meteor;
                return true;
            }

            _telemetry.RecordMeteorDestroyed(ArenaIdName(_arenaId), false);
            meteor.Active = false;
            RemoveMeteorOrder(index);
            ShatterMeteor(meteor, 0.6f);
            Hide(_meteorViews[index]);
            Hide(_meteorHitViews[index]);
            Hide(_meteorCoreViews[index]);
            Hide(_meteorDangerArcViews[index]);
            Hide(_meteorDangerRingViews[index]);
            Hide(_meteorHealthArcViews[index]);
            _audio?.Play(ProceduralAudio.Cue.Die, 0.78f);
            _meteors[index] = meteor;
            _meteorTarget = MeteorRules.MinOrdinaryMeteors +
                Mathf.FloorToInt((float)(_rng.Next() *
                    (MeteorRules.MaxOrdinaryMeteors - MeteorRules.MinOrdinaryMeteors + 1)));
            return true;
        }

        private void TrackWeaponDamage(int weaponIndex, float damage)
        {
            if (weaponIndex < 0 || weaponIndex >= _weaponDamage.Length || damage <= 0) return;
            _weaponDamage[weaponIndex] += damage;
        }

        private void DetonateBomb()
        {
            var viewportHalf = GameplayViewportHalfExtent();
            var waveRadius = new Vector2(viewportHalf.x * 2f, viewportHalf.y * 2f).magnitude * 0.68f + 80f;
            SpawnBlastWave(_playerPosition, waveRadius, 0.72f, true);
            // The browser bomb is a screen-wide presentation event. Its
            // damage scope is enemies and bosses; meteors are intentionally
            // not included in that source path.
            SpawnRingWave(
                _playerPosition,
                22f,
                1120f,
                0.78f,
                new Color(1f, 0.78f, 0.16f, 0.82f));
            SpawnRingWave(
                _playerPosition,
                12f,
                760f,
                0.58f,
                new Color(1f, 0.46f, 0.12f, 0.78f));
            BurstFx(_playerPosition, SourceDotColor("white"), 18, 360, 0.42f, 0.82f);
            BurstFx(_playerPosition, SourceDotColor("yellow"), 24, 440, 0.64f, 0.95f);
            BurstFx(_playerPosition, SourceDotColor("orange"), 34, 520, 0.78f, 1.08f);
            var normalDamage = 120f + _time * 0.4f;
            var enemySnapshot = CaptureEnemyEffectSnapshot(out var enemySnapshotCount);
            try
            {
                for (var target = 0; target < enemySnapshotCount; target++)
                {
                    var snapshot = enemySnapshot[target];
                    if (!IsLiveEnemyEffectTarget(snapshot)) continue;
                    var enemy = snapshot.State;
                    var damage = enemy.Elite
                        ? enemy.MaxHealth * 0.2f
                        : Mathf.Max(normalDamage, enemy.MaxHealth * 0.72f);
                    // Source detonateBomb uses the fixed (0, -1) direction for
                    // knockback/blocking; it is not aimed from the player.
                    ApplyEnemyDamage(snapshot.Slot, damage, Vector2.down, 260, false);
                }
            }
            finally
            {
                ReleaseEnemyEffectSnapshot(enemySnapshot);
            }
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                // Browser detonateBomb skips bosses while their intro
                // telegraph is active; they become damageable only after the
                // intro state resolves.
                if (_bosses[index].Active && _bosses[index].State != 4)
                    ApplyBossDamage(index, _bosses[index].MaxHealth * 0.04f);
            }
            // Browser detonateBomb() emits the final flash, shake, freeze,
            // cue, and toast after all enemy and boss damage side effects.
            _amberFlash = 1f;
            AddCameraShake(0.96f);
            TriggerFreeze(0.12f);
            _audio?.Play(ProceduralAudio.Cue.Bomb, 0.9f);
            ShowArenaToast("Bomb detonated", 2.5f);
        }

        private void KillEnemy(int index)
        {
            ResolveEnemyDeath(index, false);
        }

        private void ResolveEnemyDeath(int index, bool selfDetonated)
        {
            var enemy = _enemies[index];
            if (!enemy.Active) return;
            // Browser removeEnemy marks the object dead and compacts the
            // dynamic array before resolving death effects. Do the same in
            // the logical order list while retaining the pooled slot.
            enemy.Active = false;
            _enemies[index] = enemy;
            RemoveEnemyOrder(index);
            var enemyDefinition = FindEnemy(enemy.Id);
            SpawnDeathGhost(enemy, index);
            var destroyedExploder = enemy.Id == "exploder";
            var shouldReward = !selfDetonated || enemy.EliteKind.HasValue;
            if (!shouldReward)
            {
                Hide(_enemyViews[index]);
                Hide(_enemyHarvesterFullViews[index]);
                Hide(_enemyExploderWarningViews[index]);
                Hide(_enemyHarvesterCapacityRingViews[index]);
                Hide(_enemyTelegraphExploderFillViews[index]);
                for (var segment = 0; segment < ExploderTelegraphSegmentCount; segment++)
                    Hide(_enemyTelegraphExploderSegmentViews[index * ExploderTelegraphSegmentCount + segment]);
                Hide(_eliteMarkViews[index]);
                Hide(_eliteChargeLaneViews[index]);
                Hide(_eliteChargeArrowViews[index]);
                return;
            }
            _kills++;
            var rewardXp = enemy.Xp;
            // Browser removeEnemy awards a flat 10 score to normal enemies;
            // XP is a separate reward and must not change the kill score.
            var rewardScore = enemy.Elite ? 275 : 10;
            var rewardParts = 0;
            if (enemy.EliteKind.HasValue)
            {
                TriggerFreeze(0.06f);
                _eliteKills++;
                _telemetry.RecordEliteKill(
                    ArenaIdName(_arenaId),
                    EliteRules.EliteVariantDef(enemy.EliteKind.Value).BaseId);
                var arena = FindArena(ArenaIdName(_arenaId));
                var reward = EliteRules.EliteVariantRewardFor(
                    enemy.EliteKind.Value,
                    arena?.EliteRewardMultiplier ?? 1);
                // Browser removeEnemy releases the base enemy XP plus the
                // elite-variant bounty; the bounty is not a replacement.
                rewardXp = enemy.Xp + reward.Xp;
                rewardScore = reward.Score;
                rewardParts = reward.Parts;
            }
            else if (enemy.Elite)
            {
                _eliteKills++;
                _telemetry.RecordEliteKill(ArenaIdName(_arenaId), "standard");
                rewardScore = 275;
                rewardParts = 8;
            }
            else if (enemy.Roster == EnemyRoster.Two)
            {
                _telemetry.RecordRosterTwoKill(ArenaIdName(_arenaId));
            }

            _score += rewardScore;
            if (rewardParts > 0)
            {
                _partsEarned += rewardParts;
            }
            Hide(_enemyViews[index]);
                Hide(_enemyHarvesterFullViews[index]);
                Hide(_enemyExploderWarningViews[index]);
                Hide(_enemyHarvesterCapacityRingViews[index]);
                Hide(_enemyTelegraphExploderFillViews[index]);
                for (var segment = 0; segment < ExploderTelegraphSegmentCount; segment++)
                    Hide(_enemyTelegraphExploderSegmentViews[index * ExploderTelegraphSegmentCount + segment]);
                Hide(_eliteMarkViews[index]);
            Hide(_eliteChargeLaneViews[index]);
            Hide(_eliteChargeArrowViews[index]);

            if (enemy.EliteKind.HasValue)
            {
                AddCameraShake(0.5f);
                SpawnRingWave(enemy.Position, 22f, 320f, 0.5f,
                    new Color(1f, 0.86f, 0.08f, 0.78f));
                BurstFx(enemy.Position, SourceDotColor("yellow"), 20, 320, 0.62f, 0.9f);
                // Browser removeEnemy emits eliteDie after the variant death
                // layers and immediately before its clear toast.
                _audio?.Play(ProceduralAudio.Cue.Elite, 0.72f);
                ShowArenaToast(
                    $"{EliteRules.EliteVariantDef(enemy.EliteKind.Value).Name} cleared",
                    2.5f,
                    ToastKind.Reward,
                    $"+{rewardParts} Parts");
            }

            if (enemy.Elite && !enemy.EliteKind.HasValue)
            {
                // Standard Elite defeat presentation is separate from normal
                // enemy death FX in the browser.
                TriggerFreeze(0.085f);
                AddCameraShake(0.65f);
                SpawnRingWave(enemy.Position, 28f, 390f, 0.58f,
                    new Color(0.98f, 0.8f, 0.08f, 0.82f));
                BurstFx(enemy.Position, SourceDotColor("yellow"), 28, 350, 0.75f, 1f);
                // Keep the standard elite cue ordered after its presentation
                // effects, matching the browser's eliteDie() call.
                _audio?.Play(ProceduralAudio.Cue.Elite, 0.72f);
                ShowArenaToast("Elite cleared", 2.5f, ToastKind.Reward, "+8 Parts");
            }
            else if (destroyedExploder && !selfDetonated)
            {
                // A destroyed Exploder, including the Elite Exploder variant,
                // produces the browser's friendly-side chain blast. Its self-
                // fuse path above remains separate and deactivates in place.
                DetonateExploderBlast(enemy, EnemyIdentity(enemy, index));
            }
            else
            {
                var brute = enemy.Id == "brute";
                var runner = enemy.Id == "runner";
                AddCameraShake(brute ? 0.12f : 0.055f);
                BurstFx(
                    enemy.Position,
                    EnemyParticleColor(enemy),
                    brute ? 16 : 8,
                    runner ? 330 : 250,
                    runner ? 0.34f : 0.52f,
                    0.85f);
                if (brute)
                {
                    SpawnRingWave(enemy.Position, 18f, 170f, 0.4f,
                        new Color(1f, 0.46f, 0.12f, 0.68f));
                }
                else if (enemy.Id == "guard")
                {
                    SpawnRingWave(enemy.Position, 14f, 190f, 0.35f,
                        new Color(0.25f, 0.85f, 1f, 0.68f));
                }
                else if (enemy.Id == "gunner" || enemy.Id == "twinGunner")
                {
                    BurstFx(enemy.Position, SourceDotColor("orange"), 5, 290, 0.4f, 0.7f);
                }
                _audio?.Play(ProceduralAudio.Cue.Die, 1.08f);
            }

            if (enemy.Id == "splitter" && !enemy.SplitterFragment)
            {
                for (var fragment = 0; fragment < 3; fragment++)
                {
                    var angle = fragment / 3f * Mathf.PI * 2 + enemy.Seed;
                    SpawnEnemy(
                        "splitter",
                        enemy.Position + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * 14,
                        null,
                        false,
                        true,
                        0,
                        0.3f);
                }
                SpawnRingWave(enemy.Position, 12f, 145f, 0.3f,
                    ParseColor(enemyDefinition?.Color, new Color(0.96f, 0.45f, 0.71f, 0.72f)));
            }

            if (enemy.Id == "carrier")
            {
                for (var child = 0; child < _enemies.Length; child++)
                {
                    if (_enemies[child].Active &&
                        _enemies[child].CarrierDrone &&
                        _enemies[child].SummonedByCarrierSpawnId == enemy.SpawnId)
                        KillEnemy(child);
                }
            }

            // Browser resolves splitter/carrier death side effects first, then
            // releases the defeated enemy's XP. Keep this order so pooled slot
            // reuse and gameplay RNG consume the same sequence.
            SpawnPickup(enemy.Position, rewardXp);

            // Browser removeEnemy applies the Part roll to every non-Elite
            // enemy, including Carrier Drones and Splitter Fragments.
            if (!enemy.Elite && _rng.Next() < 0.045)
            {
                SpawnSpecialPickup(enemy.Position, 1, PickupKind.Part);
            }
            var rareChance = enemy.EliteKind.HasValue ? 0.35 : 0.011;
            if ((enemy.Elite && !enemy.EliteKind.HasValue) || _rng.Next() < rareChance)
            {
                SpawnRarePickup(enemy.Position);
            }
            // Browser removeEnemy checks kill milestones after each individual
            // death, before the frame-level score milestone pass.
            CheckKillMilestone();
        }

        private void DetonateExploderBlast(EnemyState enemy, int excludedEnemyIdentity)
        {
            var definition = FindEnemy("exploder");
            var radius = (float)(definition?.BlastRadius ?? 76) * 1.1f;
            var damage = 55f + _time * 0.25f;

            SpawnBlastWave(enemy.Position, radius, 0.42f, false);
            BurstFx(enemy.Position, SourceDotColor("orange"), 16, 300, 0.5f, 0.85f);
            BurstFx(enemy.Position, SourceDotColor("yellow"), 8, 220, 0.4f, 0.7f);
            AddCameraShake(0.22f);
            _audio?.Play(ProceduralAudio.Cue.ExploderBlast, 0.86f);

            // Keep the source's strict circle edge and copied-array behavior.
            // Recursive chain kills can remove enemies and reuse pooled slots,
            // so the snapshot also carries SpawnId identity for each target.
            var enemySnapshot = CaptureEnemyEffectSnapshot(out var enemySnapshotCount);
            try
            {
                for (var target = 0; target < enemySnapshotCount; target++)
                {
                    var snapshot = enemySnapshot[target];
                    if (EnemyIdentity(snapshot.State, snapshot.Slot) == excludedEnemyIdentity ||
                        !IsLiveEnemyEffectTarget(snapshot)) continue;
                    var other = snapshot.State;
                    var delta = other.Position - enemy.Position;
                    var reach = radius + other.Radius;
                    if (delta.sqrMagnitude >= reach * reach) continue;
                    ApplyEnemyDamage(snapshot.Slot, damage, delta, 240, false, -1);
                }
            }
            finally
            {
                ReleaseEnemyEffectSnapshot(enemySnapshot);
            }

            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active || boss.State == 4) continue;
                var delta = boss.Position - enemy.Position;
                if (delta.magnitude >= radius + boss.Radius) continue;
                ApplyBossDamage(index, damage * 0.5f, -1, false);
            }
        }

        private void KillBoss(int index)
        {
            var boss = _bosses[index];
            if (!boss.Active) return;
            // Browser killBoss marks the encounter dead and schedules the next
            // boss before any reward-drop RNG is consumed. Keep the pooled
            // presentation state, but commit the defeated state first.
            boss.Active = false;
            boss.State = 5;
            boss.StateTimer = 1.4f;
            boss.DeathTimer = 1.4f;
            boss.Health = 0;
            boss.ActiveAttack = null;
            _bosses[index] = boss;
            var noBossesRemain = ActiveBosses() == 0;
            TriggerFreeze(0.14f);
            AddCameraShake(0.85f);
            _telemetry.RecordBossDefeat(boss.TelemetryInstanceId, (float)_time);
            if (noBossesRemain)
            {
                var schedule = DirectorRules.BossScheduleAfterClear(
                    _time,
                    _nextBossTime,
                    _rng.Next());
                _bossRecoveryUntil = (float)schedule.RecoveryUntil;
                _nextBossTime = (float)schedule.NextBossTime;
                _bossWarned = false;
                _pendingDoubleBoss = false;
            }
            var bossAccent = BossAccent(boss);
            bossAccent.a = 0.95f;
            // Browser killBoss emits the defeat ring before either burst
            // layer. Preserve that order so the ring gets the last cosmetic
            // slot when the shared particle budget is nearly full.
            SpawnRingWave(boss.Position, 40f, 560f, 0.95f, bossAccent);
            BurstFx(boss.Position, BossParticleColor(boss.Id), 36, 390, 0.9f, 1.2f);
            bossAccent.a = 0.82f;
            BurstFx(boss.Position, SourceDotColor("white"), 18, 280, 0.7f, 0.9f);
            _bossKills++;
            _score += 1000;
            var definition = FindBoss(boss.Id);
            if (definition != null)
            {
                _partsEarned += (int)definition.RewardParts;
            }
            SpawnPickup(boss.Position, 70f + boss.EncounterIndex * 5f);
            SpawnRarePickup(boss.Position);
            // Browser killBoss() emits the death cue after its reward drops,
            // then shows the named clear toast with the Parts detail.
            _audio?.Play(ProceduralAudio.Cue.BossDeath, 0.9f);
            if (definition != null)
            {
                ShowArenaToast(
                    definition.Name + " cleared",
                    2.5f,
                    ToastKind.Reward,
                    "+" + definition.RewardParts + " Parts");
            }
        }

        private int WorkshopRank(string id)
        {
            if (_saveData?.workshop == null) return 0;
            foreach (var entry in _saveData.workshop)
            {
                if (entry != null && entry.id == id) return entry.rank;
            }
            return 0;
        }

        private void EndRun()
        {
            if (_gameOver) return;
            _revivePending = false;
            _dyingTimer = 0;
            _gameOver = true;
            _gameOverScroll = Vector2.zero;
            _paused = true;
            _audio?.StopPad();
            // Browser endRun() records the terminal state before exporting the
            // game-over report, including the final frame sample.
            RecordTelemetrySample(Mathf.Max(0.0001f, _debugFrameEmaMs / 1000f));
            SaveRun();
        }

        private static ProceduralAudio.Cue DefeatCueFor(int revivesRemaining)
        {
            return revivesRemaining > 0
                ? ProceduralAudio.Cue.Boss
                : ProceduralAudio.Cue.GameOver;
        }

        private void AcceptRevive()
        {
            if (!_revivePending || _revivesRemaining <= 0) return;
            _revivesRemaining--;
            _revivePending = false;
            _dyingTimer = 0;
            _playerHealth = Mathf.Ceil(_playerMaxHealth * 0.5f);
            _playerIframes = 2.5f;
            _playerVelocity = Vector2.zero;
            _cyanFlash = 0.9f;
            _paused = false;
            _targetTimeScale = 1;
            TriggerFreeze(0.08f);
            _audio?.Play(ProceduralAudio.Cue.LevelUp, 1.12f);
            BurstFx(_playerPosition, SourceDotColor("cyan"), 26, 380, 0.7f, 1f);
            BurstFx(_playerPosition, SourceDotColor("white"), 14, 300, 0.55f, 0.8f);
            SpawnRingWave(_playerPosition, 26f, 640f, 0.72f, new Color(0.133f, 0.827f, 0.933f, 1f));
            SpawnRingWave(_playerPosition, 14f, 420f, 0.55f, new Color(0.133f, 0.827f, 0.933f, 1f));

            var enemySnapshot = CaptureEnemyEffectSnapshot(out var enemySnapshotCount);
            try
            {
                for (var target = 0; target < enemySnapshotCount; target++)
                {
                    var snapshot = enemySnapshot[target];
                    if (!IsLiveEnemyEffectTarget(snapshot)) continue;
                    var enemy = snapshot.State;
                    var delta = enemy.Position - _playerPosition;
                    var reach = 340f + enemy.Radius;
                    if (delta.sqrMagnitude >= reach * reach) continue;
                    ApplyEnemyDamage(snapshot.Slot, 60f + _time * 0.2f, delta, 460, false);
                }
            }
            finally
            {
                ReleaseEnemyEffectSnapshot(enemySnapshot);
            }
            EnqueueToast(
                "Revived",
                _revivesRemaining > 0 ? $"{_revivesRemaining} left" : null,
                2.2f,
                ToastKind.Reward);
            SetMenuNotice(_revivesRemaining > 0 ? $"Revived — {_revivesRemaining} left." : "Revived.");
        }

        private void DeclineRevive()
        {
            if (!_revivePending) return;
            EndRun();
        }

        private static int AddCounter(int current, int amount)
        {
            var total = (long)Math.Max(0, current) + Math.Max(0, amount);
            return (int)Math.Min(999_999_999L, total);
        }

        private static void CommitRunParts(SaveData saveData, int partsEarned)
        {
            if (saveData == null) return;
            saveData.parts = AddCounter(saveData.parts, partsEarned);
        }

        private static long AddDamageCounter(long current, long amount)
        {
            var total = Math.Max(0, current) + Math.Max(0, amount);
            return Math.Min(999_999_999_999L, total);
        }

        private static long RoundedDamageCounter(double value)
        {
            // JavaScript Math.round is floor(value + 0.5) for non-negative
            // damage totals; do not use Convert.ToInt64, which is banker’s
            // rounding at exact .5 values.
            return (long)Math.Floor(Math.Max(0d, value) + 0.5d);
        }

        private int CurrentScore()
        {
            return Mathf.FloorToInt(_score + _time * 5f + (_level - 1) * 35f + 0.5f);
        }

        private void SaveRun()
        {
            // Browser recordRun runs only after the terminal Game Over path. Do
            // not turn an application close during a live run into a fake score.
            if (_runSaved || _mainMenuBrowsing || !_gameOver) return;
            _runSaved = true;
            _lastRunSaved = false;
            if (_saveStore == null || _saveData == null) return;
            var savedDamageDealt = RoundedDamageCounter(_damageDealt);
            var savedDamageTaken = RoundedDamageCounter(_damageTaken);
            var previousBestScore = _saveData.highScores != null && _saveData.highScores.Length > 0 && _saveData.highScores[0] != null
                ? _saveData.highScores[0].score
                : -1;
            _saveData.stats.totalRuns = AddCounter(_saveData.stats.totalRuns, 1);
            _saveData.stats.totalPlaySeconds = AddCounter(
                _saveData.stats.totalPlaySeconds, Mathf.Max(0, Mathf.FloorToInt(_time)));
            _saveData.stats.totalKills = AddCounter(_saveData.stats.totalKills, _kills);
            _saveData.stats.totalEliteKills = AddCounter(_saveData.stats.totalEliteKills, _eliteKills);
            _saveData.stats.totalBossKills = AddCounter(_saveData.stats.totalBossKills, _bossKills);
            _saveData.stats.totalDamageDealt = AddDamageCounter(_saveData.stats.totalDamageDealt, savedDamageDealt);
            _saveData.stats.totalDamageTaken = AddDamageCounter(_saveData.stats.totalDamageTaken, savedDamageTaken);
            _saveData.stats.totalPartsEarned = AddCounter(_saveData.stats.totalPartsEarned, _partsEarned);
            // The browser keeps run rewards in partsEarned until recordRun at
            // terminal Game Over. Commit the complete run total here so
            // pickups, elite/boss rewards, and tune-limit Parts are all saved
            // once and a live run cannot mutate the profile early.
            CommitRunParts(_saveData, _partsEarned);
            _saveData.stats.bestScore = Mathf.Max(_saveData.stats.bestScore, CurrentScore());
            _saveData.stats.bestTime = Mathf.Max(_saveData.stats.bestTime, Mathf.FloorToInt(_time));
            _saveData.stats.bestKills = Mathf.Max(_saveData.stats.bestKills, _kills);
            _saveData.stats.highestLevel = Mathf.Max(_saveData.stats.highestLevel, _level);

            var run = new RunRecordEntry
            {
                score = CurrentScore(),
                kills = _kills,
                time = Mathf.Max(0, Mathf.FloorToInt(_time)),
                level = Mathf.Max(1, _level),
                eliteKills = _eliteKills,
                bossKills = _bossKills,
                partsEarned = _partsEarned,
                date = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                damageDealt = savedDamageDealt,
                damageTaken = savedDamageTaken,
                weapons = BuildRankEntries(WeaponIds(), _upgradeProgress?.WeaponRanks),
                weaponDamage = BuildWeaponDamageEntries(),
                supports = BuildRankEntries(SupportIds(), _upgradeProgress?.SupportRanks),
                late = BuildRankEntries(LateIds(), _upgradeProgress?.LateRanks),
                evolved = BuildEvolvedEntries(),
            };
            _lastRunIsBest = run.score > previousBestScore;
            var recentRuns = new List<RunRecordEntry>();
            foreach (var previous in _saveData.recentRuns ?? Array.Empty<RunRecordEntry>())
            {
                if (previous != null) recentRuns.Add(previous);
            }
            recentRuns.Insert(0, run);
            if (recentRuns.Count > SaveStore.MaxRecentRuns)
                recentRuns.RemoveRange(SaveStore.MaxRecentRuns, recentRuns.Count - SaveStore.MaxRecentRuns);
            _saveData.recentRuns = recentRuns.ToArray();

            var scoreEntry = new HighScoreEntry
            {
                score = run.score,
                kills = run.kills,
                time = run.time,
                level = run.level,
                eliteKills = run.eliteKills,
                bossKills = run.bossKills,
                partsEarned = run.partsEarned,
                date = run.date,
            };
            var highScores = new List<HighScoreEntry>();
            foreach (var previous in _saveData.highScores ?? Array.Empty<HighScoreEntry>())
            {
                if (previous != null) highScores.Add(previous);
            }
            highScores.Add(scoreEntry);
            highScores.Sort(SaveStore.CompareScores);
            var rawRank = highScores.IndexOf(scoreEntry);
            _lastRunRank = rawRank >= 0 && rawRank < SaveStore.MaxHighScores ? rawRank : -1;
            if (highScores.Count > SaveStore.MaxHighScores)
                highScores.RemoveRange(SaveStore.MaxHighScores, highScores.Count - SaveStore.MaxHighScores);
            _saveData.highScores = highScores.ToArray();
            try
            {
                _saveStore.Save(_saveData);
                _lastRunSaved = true;
            }
            catch (Exception exception)
            {
                Debug.LogError("VoidFall run save failed: " + exception.Message);
            }
            ExportTelemetrySnapshot(_gameOver ? "gameover" : "active");
            if (!_lastRunSaved) SetMenuNotice("Progress was not saved.");
        }

        private void ExportTelemetrySnapshot(string status)
        {
            if (_time <= 0)
            {
                EnqueueToast("No run data yet", null, 2.2f, ToastKind.Info);
                SetMenuNotice("No run data yet.");
                return;
            }
            _lastTelemetryPath = _telemetry.Export(
                status,
                (float)_time,
                CurrentScore(),
                _kills,
                _eliteKills,
                _bossKills,
                _level,
                RoundedDamageCounter(_damageDealt),
                RoundedDamageCounter(_damageTaken),
                _partsEarned,
                ActiveBosses(),
                ActiveEnemies(),
                ActivePickups(),
                BuildTelemetryProgress(),
                BuildTelemetryDamage(),
                Mathf.FloorToInt(XpOnGround()),
                XpHeldByHarvesters());
            if (!string.IsNullOrEmpty(_lastTelemetryPath))
            {
                EnqueueToast("Run data exported", _lastTelemetryPath, 2.2f, ToastKind.Info);
                SetMenuNotice("Run data exported.");
            }
        }

        private static WorkshopEntry[] BuildRankEntries(string[] ids, int[] ranks)
        {
            if (ids == null || ranks == null) return Array.Empty<WorkshopEntry>();
            var result = new List<WorkshopEntry>();
            for (var index = 0; index < Mathf.Min(ids.Length, ranks.Length); index++)
            {
                if (ranks[index] <= 0) continue;
                result.Add(new WorkshopEntry { id = ids[index], rank = ranks[index] });
            }
            return result.ToArray();
        }

        private WeaponDamageEntry[] BuildWeaponDamageEntries()
        {
            var result = new List<WeaponDamageEntry>();
            for (var index = 0; index < Mathf.Min(ContentCatalog.Weapons.Length, _weaponDamage.Length); index++)
            {
                var damage = RoundedDamageCounter(_weaponDamage[index]);
                if (damage <= 0) continue;
                result.Add(new WeaponDamageEntry
                {
                    id = ContentCatalog.Weapons[index].Id,
                    damage = damage,
                });
            }
            return result.ToArray();
        }

        private UnityTelemetryProgress BuildTelemetryProgress()
        {
            var evolved = new List<string>();
            if (_upgradeProgress?.Evolved != null)
            {
                for (var index = 0; index < Mathf.Min(_upgradeProgress.Evolved.Length, ContentCatalog.Weapons.Length); index++)
                    if (_upgradeProgress.Evolved[index]) evolved.Add(ContentCatalog.Weapons[index].Id);
            }
            return new UnityTelemetryProgress
            {
                weapons = BuildTelemetryRanks(WeaponIds(), _upgradeProgress?.WeaponRanks),
                supports = BuildTelemetryRanks(SupportIds(), _upgradeProgress?.SupportRanks),
                late = BuildTelemetryRanks(LateIds(), _upgradeProgress?.LateRanks),
                evolved = evolved.ToArray(),
            };
        }

        private static UnityTelemetryNamedValue[] BuildTelemetryRanks(string[] ids, int[] ranks)
        {
            if (ids == null || ranks == null) return Array.Empty<UnityTelemetryNamedValue>();
            var result = new List<UnityTelemetryNamedValue>();
            for (var index = 0; index < Mathf.Min(ids.Length, ranks.Length); index++)
            {
                if (ranks[index] <= 0) continue;
                result.Add(new UnityTelemetryNamedValue { id = ids[index], value = ranks[index] });
            }
            return result.ToArray();
        }

        private UnityTelemetryDamageValue[] BuildTelemetryDamage()
        {
            var result = new List<UnityTelemetryDamageValue>();
            for (var index = 0; index < Mathf.Min(ContentCatalog.Weapons.Length, _weaponDamage.Length); index++)
            {
                var damage = RoundedDamageCounter(_weaponDamage[index]);
                if (damage <= 0) continue;
                result.Add(new UnityTelemetryDamageValue
                {
                    id = ContentCatalog.Weapons[index].Id,
                    value = damage,
                });
            }
            return result.ToArray();
        }

        private float TelemetryQualityValue()
        {
            return _qualityPreset.Detail;
        }

        private static string[] WeaponIds()
        {
            var ids = new string[ContentCatalog.Weapons.Length];
            for (var index = 0; index < ids.Length; index++) ids[index] = ContentCatalog.Weapons[index].Id;
            return ids;
        }

        private static string[] SupportIds()
        {
            var ids = new string[ContentCatalog.Supports.Length];
            for (var index = 0; index < ids.Length; index++) ids[index] = ContentCatalog.Supports[index].Id;
            return ids;
        }

        private static string[] LateIds()
        {
            var ids = new string[ContentCatalog.LateUpgrades.Length];
            for (var index = 0; index < ids.Length; index++) ids[index] = ContentCatalog.LateUpgrades[index].Id;
            return ids;
        }

        private WorkshopEntry[] BuildEvolvedEntries()
        {
            if (_upgradeProgress?.Evolved == null) return Array.Empty<WorkshopEntry>();
            var result = new List<WorkshopEntry>();
            for (var index = 0; index < Mathf.Min(ContentOrder.Weapons.Length, _upgradeProgress.Evolved.Length); index++)
            {
                if (!_upgradeProgress.Evolved[index]) continue;
                result.Add(new WorkshopEntry { id = ContentCatalog.Weapons[index].Id, rank = 1 });
            }
            return result.ToArray();
        }

        private void DiscoverBestiary(string id)
        {
            if (_saveData?.bestiary == null || string.IsNullOrEmpty(id)) return;
            foreach (var entry in _saveData.bestiary)
            {
                if (entry != null && entry.id == id)
                {
                    entry.discovered = true;
                    return;
                }
            }
        }

        private void OpenLevelUp()
        {
            if (_upgradeProgress == null) return;
            if (_levelUpTimer >= 0) return;
            _audio?.Play(ProceduralAudio.Cue.LevelUp);
            _cyanFlash = 0.8f;
            BurstFx(_playerPosition, SourceDotColor("cyan"), 20, 310, 0.66f, 0.95f);
            SpawnRingWave(_playerPosition, 18f, 430f, 0.62f, new Color(0.133f, 0.827f, 0.933f, 1f));
            _levelOptions = null;
            _levelUpActive = false;
            _levelUpTimer = 0.38f;
            _targetTimeScale = 0.12f;
        }

        private void ApplyLevelRecovery()
        {
            var recovery = WorkshopRank("recovery") * 3;
            if (recovery > 0)
                _playerHealth = Mathf.Min(_playerMaxHealth, _playerHealth + recovery);
        }

        private UpgradeOptionDefinition[] RollLevelOptions()
        {
            var options = UpgradeRules.RollProgressionOptions(_upgradeProgress, _rng, 3);
            if (_playerHealth >= _playerMaxHealth * 0.45f) return options;

            var repair = new UpgradeOptionDefinition
            {
                Id = "repair",
                TargetId = "repair",
                Kind = UpgradeOptionKind.Repair,
                Name = "Field Repair",
                Description = "Restore 35 integrity now",
                CurrentRank = 0,
                NextRank = 1,
                MaxRank = 1,
                Accent = "#fb7185",
                Weight = 0,
            };
            var result = new List<UpgradeOptionDefinition>(options);
            var replaceIndex = -1;
            for (var index = result.Count - 1; index >= 0; index--)
            {
                if (result[index].Kind != UpgradeOptionKind.Evolution)
                {
                    replaceIndex = index;
                    break;
                }
            }

            if (result.Count < 3) result.Add(repair);
            else if (replaceIndex >= 0) result[replaceIndex] = repair;
            return result.ToArray();
        }

        private void SelectLevelOption(int index)
        {
            if (!_levelUpActive || _levelOptions == null || index < 0 || index >= _levelOptions.Length) return;
            var option = _levelOptions[index];
            var previousMaxHealth = _playerMaxHealth;
            var previousSlotLimit = UpgradeRules.WeaponSlotLimit(_upgradeProgress);
            if (!UpgradeRules.Apply(_upgradeProgress, option)) return;
            var expandedWeaponSlots = option.Kind == UpgradeOptionKind.Weapon &&
                UpgradeRules.WeaponSlotLimit(_upgradeProgress) > previousSlotLimit;
            if (option.Kind == UpgradeOptionKind.Evolution)
            {
                BeginEvolutionReveal(option);
                _audio?.Play(ProceduralAudio.Cue.Evolution);
                TriggerFreeze(0.12f);
                _cyanFlash = 0.85f;
                AddCameraShake(0.55f);
                SpawnRingWave(_playerPosition, 26f, 680f, 0.72f, new Color(0.35f, 0.95f, 1f, 0.84f));
                SpawnRingWave(_playerPosition, 14f, 430f, 0.52f, new Color(0.35f, 0.95f, 1f, 0.72f));
                BurstFx(_playerPosition, SourceDotColor("white"), 18, 300, 0.65f, 0.9f);
                BurstFx(_playerPosition, EvolutionAccent(option.TargetId), 24, 390, 0.78f, 1f);
            }
            else if (option.Kind == UpgradeOptionKind.Repair)
            {
                _playerHealth = Mathf.Min(_playerMaxHealth, _playerHealth + 35f);
            }
            if (expandedWeaponSlots)
            {
                ShowArenaToast("Fourth weapon slot unlocked", 2.5f, ToastKind.Reward);
                SpawnRingWave(_playerPosition, 16f, 360f, 0.46f,
                    new Color(0.133f, 0.827f, 0.933f, 0.8f));
                BurstFx(_playerPosition, SourceDotColor("cyan"),
                    12, 220, 0.42f, 0.7f);
            }
            _telemetry.RecordUpgrade((float)_time, _level, option.TargetId, option.Kind.ToString(), BuildTelemetryProgress());
            _pistolRank = _upgradeProgress.WeaponRanks[0];
            _calibrationRank = SupportRank("calibration");
            RecalculatePlayerStats(false);
            // Browser applyUpgrade() explicitly restores the max-health delta
            // after recalculate() when Plating or Frame raises the cap.
            if (_playerMaxHealth > previousMaxHealth)
            {
                _playerHealth = Mathf.Min(
                    _playerMaxHealth,
                    _playerHealth + (_playerMaxHealth - previousMaxHealth));
            }
            _levelOptions = null;
            _levelUpActive = false;
            _levelUpPromptOpenedAt = -1f;
            _paused = false;
            _targetTimeScale = 1;
            // Browser applyUpgrade() plays the pickup cue for every
            // non-evolution choice after the upgrade is committed.
            if (option.Kind != UpgradeOptionKind.Evolution)
                _audio?.Play(ProceduralAudio.Cue.Pickup, 1f);
        }

        private void BeginEvolutionReveal(UpgradeOptionDefinition option)
        {
            if (option == null || option.Kind != UpgradeOptionKind.Evolution) return;
            _evolutionRevealPreviousName = option.TargetId;
            for (var index = 0; index < ContentCatalog.Weapons.Length; index++)
            {
                if (ContentCatalog.Weapons[index].Id != option.TargetId) continue;
                _evolutionRevealPreviousName = ContentCatalog.Weapons[index].Name;
                break;
            }
            _evolutionRevealName = option.Name;
            _evolutionRevealWeaponId = option.TargetId;
            _evolutionRevealAccent = ParseColor(option.Accent, new Color(0.35f, 0.9f, 1f, 1f));
            _evolutionRevealTimer = 2.6f;
        }

        private void RerollLevelOptions()
        {
            if (!_levelUpActive || _rerollsRemaining <= 0 || _upgradeProgress == null) return;
            var previous = _levelOptions == null
                ? string.Empty
                : string.Join("|", Array.ConvertAll(_levelOptions, option => option.Id));
            _rerollsRemaining--;
            var next = RollLevelOptions();
            for (var attempt = 0; attempt < 3 && next.Length > 0; attempt++)
            {
                var fingerprint = string.Join("|", Array.ConvertAll(next, option => option.Id));
                if (fingerprint != previous) break;
                next = RollLevelOptions();
            }
            _levelOptions = next;
            _levelUpPromptOpenedAt = Time.realtimeSinceStartup;
            _audio?.Play(ProceduralAudio.Cue.Ui, 0.95f);
            SetMenuNotice(_rerollsRemaining > 0 ? "Upgrade options rerolled." : "Upgrade options rerolled. No rerolls left.");
        }

        private int SupportRank(string id)
        {
            if (_upgradeProgress == null) return 0;
            for (var index = 0; index < ContentCatalog.Supports.Length; index++)
            {
                if (ContentCatalog.Supports[index].Id == id) return _upgradeProgress.SupportRanks[index];
            }

            return 0;
        }

        private int LateRank(string id)
        {
            if (_upgradeProgress == null) return 0;
            for (var index = 0; index < ContentCatalog.LateUpgrades.Length; index++)
            {
                if (ContentCatalog.LateUpgrades[index].Id == id) return _upgradeProgress.LateRanks[index];
            }

            return 0;
        }

        private void RecalculatePlayerStats(bool repairOnUpgrade)
        {
            var plating = SupportRank("plating");
            var frame = LateRank("frame");
            _playerMaxHealth = (float)ContentCatalog.Operative.MaxHealth + _workshopIntegrity * 5 + plating * 20 + frame * 8;
            _damageMultiplier = Mathf.Pow(1.12f, SupportRank("calibration")) *
                (1 + _workshopPower * 0.04f) * Mathf.Pow(1.05f, LateRank("output"));
            _cooldownMultiplier = Mathf.Pow(0.92f, SupportRank("cycling")) *
                Mathf.Pow(0.97f, LateRank("cooling")) *
                (1f - WorkshopRank("arsenal") * 0.03f);
            _moveSpeedMultiplier = Mathf.Pow(1.08f, SupportRank("mobility")) *
                (1 + _workshopMobility * 0.03f);
            _pickupRadius = (float)ContentCatalog.Operative.PickupRadius *
                Mathf.Pow(1.25f, SupportRank("collector"));
            _areaMultiplier = Mathf.Pow(1.12f, SupportRank("amplifier"));
            _critChance = Mathf.Clamp01(
                0.05f + SupportRank("optics") * 0.06f + WorkshopRank("precision") * 0.02f);
            // Browser recalculate() clamps an over-cap health value but does
            // not heal the player when Plating or Frame raises max health.
            _playerHealth = Mathf.Min(_playerHealth, _playerMaxHealth);
        }

        private static string SourceEnemySpriteId(
            string id,
            bool elite,
            string eliteVariantBaseId)
        {
            // Browser elite variants keep their base Enemy.type so their body
            // sprite stays Mortar/Exploder/Gunner/etc.; only the original
            // charging elite uses the generic Elite sprite.
            if (!string.IsNullOrEmpty(eliteVariantBaseId)) return eliteVariantBaseId;
            return elite ? "elite" : id;
        }

        private static string SourceEnemySpriteId(EnemyState enemy)
        {
            var variantBaseId = enemy.EliteKind.HasValue
                ? EliteRules.EliteVariantDef(enemy.EliteKind.Value).BaseId
                : null;
            return SourceEnemySpriteId(enemy.Id, enemy.Elite, variantBaseId);
        }

        private static float SourceEnemySpriteWorldSize(
            string id,
            bool elite,
            string eliteVariantBaseId,
            bool rosterTwo,
            float radius)
        {
            var spriteId = SourceEnemySpriteId(id, elite, eliteVariantBaseId);
            var canvasSize = rosterTwo && !elite
                ? ProceduralSpriteFactory.RosterTwoEnemyCanvasSize(id)
                : ProceduralSpriteFactory.EnemyCanvasSize(spriteId);
            var definitionRadius = elite && string.IsNullOrEmpty(eliteVariantBaseId)
                ? (float)ContentCatalog.Elite.Radius
                : (float)(FindEnemy(id)?.Radius ?? 1);
            return canvasSize * radius / Mathf.Max(1f, definitionRadius);
        }

        private static float SourceEnemySpriteWorldSize(EnemyState enemy)
        {
            var variantBaseId = enemy.EliteKind.HasValue
                ? EliteRules.EliteVariantDef(enemy.EliteKind.Value).BaseId
                : null;
            var rosterTwo = enemy.Roster == EnemyRoster.Two && !enemy.Elite;
            return SourceEnemySpriteWorldSize(
                enemy.Id,
                enemy.Elite,
                variantBaseId,
                rosterTwo,
                enemy.Radius);
        }

        private static float SourceBossSpriteWorldSize(string id, float radius)
        {
            var definitionRadius = (float)(FindBoss(id)?.Radius ?? 1);
            return ProceduralSpriteFactory.BossCanvasSize(id) * radius /
                Mathf.Max(1f, definitionRadius);
        }

        private static float SourceBladeSpriteWorldSize(bool hollow)
        {
            return ProceduralSpriteFactory.BladeCanvasSize(hollow);
        }

        private static float SourceMeteorShardWorldSize(float size, float progress)
        {
            return 24f * Mathf.Max(0f, size) *
                (0.4f + Mathf.Clamp01(progress) * 0.6f);
        }

        private static float SourceMeteorSpriteWorldSize(int variant, bool explosive)
        {
            return ProceduralSpriteFactory.MeteorCanvasSize(variant, explosive);
        }

        private static Color EnemyParticleColor(EnemyState enemy)
        {
            // Browser damage/death bursts use ENEMY_PARTICLE, not the actor
            // body definition color. Elite variants retain their base enemy id.
            switch (enemy.Id)
            {
                case "chaser": return SourceDotColor("pink");
                case "runner": return SourceDotColor("violet");
                case "dasher": return SourceDotColor("fuchsia");
                case "brute": return SourceDotColor("orange");
                case "gunner": return SourceDotColor("red");
                case "twinGunner": return SourceDotColor("orange");
                case "guard": return SourceDotColor("cyan");
                case "exploder": return SourceDotColor("yellow");
                case "technician": return SourceDotColor("emerald");
                case "mortar": return SourceDotColor("orange");
                case "splitter": return SourceDotColor("pink");
                case "bulwark": return SourceDotColor("blue");
                case "harvester": return SourceDotColor("lime");
                case "carrier": return SourceDotColor("yellow");
                case "elite": return SourceDotColor("yellow");
                default: return SourceDotColor("yellow");
            }
        }

        private static Color BossParticleColor(string bossId)
        {
            // Browser bossParticle(): herald violet, matriarch emerald, reaver
            // blue, and warden red. Boss body colors are a separate visual path.
            switch (bossId)
            {
                case "herald": return SourceDotColor("violet");
                case "matriarch": return SourceDotColor("emerald");
                case "reaver": return SourceDotColor("blue");
                default: return SourceDotColor("red");
            }
        }

        private Color EnemySpriteAccent(EnemyState enemy)
        {
            var spriteId = SourceEnemySpriteId(enemy);
            if (spriteId == "elite")
                return ParseColor(ContentCatalog.Elite.Color, Color.yellow);
            return ParseColor(FindEnemy(spriteId)?.Color, EnemyAccent(enemy));
        }

        private Color EnemyAccent(EnemyState enemy)
        {
            if (enemy.EliteKind.HasValue)
                return ParseColor(EliteRules.EliteVariantDef(enemy.EliteKind.Value).Accent, Color.magenta);
            if (enemy.Elite)
                return ParseColor(ContentCatalog.Elite.Color, Color.yellow);
            return ParseColor(FindEnemy(enemy.Id)?.Color, Color.magenta);
        }

        private static Color EvolutionAccent(string targetId)
        {
            switch (targetId)
            {
                case "scattergun": return SourceDotColor("orange");
                case "seeker": return SourceDotColor("lime");
                case "railgun": return SourceDotColor("violet");
                case "arc": return SourceDotColor("yellow");
                default: return SourceDotColor("cyan");
            }
        }

        private Color BossAccent(BossState boss)
        {
            return ParseColor(FindBoss(boss.Id)?.Color, Color.magenta);
        }

        private void SpawnFloater(
            Vector2 position,
            string text,
            Color color,
            float size,
            int targetKey = 0,
            int value = 0,
            bool critical = false)
        {
            if (_canvas == null || string.IsNullOrEmpty(text)) return;
            EnsureFloaterOrderEntries();
            if (targetKey > 0 && value > 0)
            {
                for (var order = 0; order < _floaterOrderCount; order++)
                {
                    var index = _floaterOrder[order];
                    var existing = _floaters[index];
                    if (!existing.Active || existing.TargetKey != targetKey || existing.Value <= 0 ||
                        existing.Life <= existing.MaxLife - 0.3f) continue;
                    existing.Value += value;
                    existing.Text = existing.Value.ToString();
                    existing.Position = (existing.Position + position) * 0.5f;
                    existing.Critical |= critical;
                    existing.Color = existing.Critical
                        ? new Color(0.969f, 0.443f, 0.443f, 1f)
                        : new Color(0.886f, 0.91f, 0.941f, 1f);
                    existing.FontSize = SourceFloaterFontSize(existing.Critical ? 17f : 12.5f);
                    existing.Life = Mathf.Max(existing.Life, 0.48f);
                    var mergedView = _floaterViews[index];
                    if (mergedView != null)
                    {
                        mergedView.text = existing.Text;
                        mergedView.fontSize = existing.FontSize;
                    }
                    _floaters[index] = existing;
                    return;
                }
            }

            var limit = Mathf.Max(8, Mathf.RoundToInt(MaxFloaters * _qualityPreset.FloaterScale));
            var active = 0;
            var slot = -1;
            for (var index = 0; index < _floaters.Length; index++)
            {
                if (_floaters[index].Active)
                {
                    active++;
                    continue;
                }
                if (slot < 0) slot = index;
            }
            if (active >= limit || slot < 0) return;

            var floater = new FloaterState
            {
                Active = true,
                Position = position + new Vector2(
                    ((float)_fxRng.Next() - 0.5f) * 14f,
                    SourceFloatingTextAnchorOffset),
                Life = 0.68f,
                MaxLife = 0.68f,
                TargetKey = targetKey,
                Value = Mathf.Max(0, value),
                Critical = critical,
                Color = color,
                FontSize = SourceFloaterFontSize(size),
                View = slot,
            };
            floater.Text = text;
            _floaters[slot] = floater;
            AppendFloaterOrder(slot);
            var view = _floaterViews[slot];
            if (view != null)
            {
                view.text = text;
                view.fontSize = floater.FontSize;
                view.color = color;
                view.enabled = true;
            }
        }

        private void SpawnDamageFloater(int targetKey, Vector2 position, float damage, bool critical)
        {
            // Browser damage numbers use Math.max(1, Math.round(damage));
            // Unity's RoundToInt uses midpoint-to-even at exact .5 values.
            var value = Mathf.Max(1, SourceRound(damage));
            SpawnFloater(
                position,
                value.ToString(),
                critical
                    ? new Color(0.969f, 0.443f, 0.443f, 1f)
                    : new Color(0.886f, 0.91f, 0.941f, 1f),
                critical ? 17f : 12.5f,
                targetKey,
                value,
                critical);
        }

        private static int SourceFloaterFontSize(float size)
        {
            return Mathf.Max(10, Mathf.RoundToInt(size * SourceFloatingTextScale));
        }

        private void SpawnDamageIndicator(Vector2 sourceDirection)
        {
            var direction = SourceNormalizedDirection(sourceDirection);
            var slot = -1;
            var oldestLife = float.MaxValue;
            for (var index = 0; index < _damageIndicators.Length; index++)
            {
                if (!_damageIndicators[index].Active)
                {
                    slot = index;
                    break;
                }
                if (_damageIndicators[index].Life < oldestLife)
                {
                    oldestLife = _damageIndicators[index].Life;
                    slot = index;
                }
            }
            if (slot < 0) return;
            if (_damageIndicators[slot].Active) RemoveDamageIndicatorOrder(slot);

            var indicator = new DamageIndicatorState
            {
                Active = true,
                Angle = Mathf.Atan2(-direction.y, -direction.x),
                Life = 0.85f,
                MaxLife = 0.85f,
                View = slot,
            };
            _damageIndicators[slot] = indicator;
            AppendDamageIndicatorOrder(slot);
            var view = _damageIndicatorViews[slot];
            if (view != null) view.enabled = true;
        }

        private void SpawnDeathGhost(EnemyState enemy, int sourceIndex)
        {
            if (_qualityPreset.DeathGhosts == false ||
                (_saveData?.settings != null && _saveData.settings.reducedMotion)) return;
            var slot = SelectDeathGhostSlot(_deathGhosts);
            if (slot < 0) return;

            var ghost = new DeathGhostState
            {
                Active = true,
                Position = enemy.Position,
                Radius = enemy.Radius,
                // Browser spawnDeathGhost uses sprites.enemy[enemy.type], not
                // the Roster II silhouette canvas used by the live actor.
                VisualSize = SourceEnemySpriteWorldSize(
                    enemy.Id,
                    enemy.Elite,
                    enemy.EliteKind.HasValue
                        ? EliteRules.EliteVariantDef(enemy.EliteKind.Value).BaseId
                        : null,
                    false,
                    enemy.Radius),
                Rotation = enemy.Rotation * Mathf.Rad2Deg,
                Life = 0.16f,
                MaxLife = 0.16f,
                Id = enemy.Id,
                Accent = EnemyAccent(enemy),
                Elite = enemy.Elite,
                EliteKind = enemy.EliteKind,
                View = slot,
            };
            _deathGhosts[slot] = ghost;
            AppendDeathGhostOrder(slot);
            var view = _deathGhostViews[slot];
            if (view != null)
            {
                view.sprite = ProceduralSpriteFactory.Enemy(
                    SourceEnemySpriteId(enemy),
                    EnemySpriteAccent(enemy),
                    false);
                view.transform.position = ghost.Position;
                view.transform.rotation = Quaternion.Euler(0, 0, ghost.Rotation);
                view.transform.localScale = Vector3.one * ghost.VisualSize;
                view.color = new Color(1f, 1f, 1f, 0.5f);
                view.enabled = true;
            }
        }

        private static int SelectDeathGhostSlot(DeathGhostState[] ghosts)
        {
            for (var index = 0; index < ghosts.Length; index++)
                if (!ghosts[index].Active) return index;
            return -1;
        }

        private void UpdateFloaters(float dt)
        {
            for (var index = 0; index < _floaters.Length; index++)
            {
                var floater = _floaters[index];
                if (!floater.Active) continue;
                floater.Life -= dt;
                floater.Position += Vector2.up * 46f * dt;
                if (floater.Life <= 0)
                {
                    floater.Active = false;
                    RemoveFloaterOrder(index);
                    Hide(_floaterViews[index]);
                }
                _floaters[index] = floater;
            }
        }

        private void UpdateDeathGhosts(float dt)
        {
            for (var index = 0; index < _deathGhosts.Length; index++)
            {
                var ghost = _deathGhosts[index];
                if (!ghost.Active) continue;
                ghost.Life -= dt;
                if (ghost.Life <= 0)
                {
                    ghost.Active = false;
                    RemoveDeathGhostOrder(index);
                    Hide(_deathGhostViews[index]);
                }
                _deathGhosts[index] = ghost;
            }
        }

        private void UpdateDamageIndicators(float dt)
        {
            for (var index = 0; index < _damageIndicators.Length; index++)
            {
                var indicator = _damageIndicators[index];
                if (!indicator.Active) continue;
                indicator.Life -= dt;
                if (indicator.Life <= 0)
                {
                    indicator.Active = false;
                    RemoveDamageIndicatorOrder(index);
                    Hide(_damageIndicatorViews[index]);
                }
                _damageIndicators[index] = indicator;
            }
        }

        private void RenderDeathGhosts()
        {
            EnsureDeathGhostOrderEntries();
            for (var index = 0; index < _deathGhosts.Length; index++)
            {
                var ghost = _deathGhosts[index];
                var view = _deathGhostViews[index];
                if (!ghost.Active) Hide(view);
            }
            for (var order = 0; order < _deathGhostOrderCount; order++)
            {
                var index = _deathGhostOrder[order];
                if (index < 0 || index >= _deathGhosts.Length) continue;
                var ghost = _deathGhosts[index];
                var view = _deathGhostViews[index];
                if (!ghost.Active || view == null) continue;
                var progress = Mathf.Clamp01(ghost.Life / Mathf.Max(0.001f, ghost.MaxLife));
                var size = ghost.VisualSize * (1f + (1f - progress) * 0.14f);
                view.rendererPriority = order;
                view.transform.position = ghost.Position;
                view.transform.rotation = Quaternion.Euler(0, 0, ghost.Rotation);
                view.transform.localScale = Vector3.one * size;
                view.color = new Color(1f, 1f, 1f, progress * 0.5f);
                view.enabled = true;
            }
        }

        private void RenderDamageIndicators()
        {
            if (_canvas == null) return;
            var canvasRect = _canvas.transform as RectTransform;
            if (canvasRect == null) return;
            var width = canvasRect.rect.width;
            var height = canvasRect.rect.height;
            var radius = Mathf.Min(width, height) * 0.5f - 48f;
            if (radius <= 0) return;
            EnsureDamageIndicatorOrderEntries();
            for (var index = 0; index < _damageIndicators.Length; index++)
            {
                if (!_damageIndicators[index].Active) Hide(_damageIndicatorViews[index]);
            }
            for (var order = 0; order < _damageIndicatorOrderCount; order++)
            {
                var index = _damageIndicatorOrder[order];
                if (index < 0 || index >= _damageIndicators.Length) continue;
                var indicator = _damageIndicators[index];
                var view = _damageIndicatorViews[index];
                if (!indicator.Active || view == null) continue;
                var progress = Mathf.Clamp01(indicator.Life / Mathf.Max(0.001f, indicator.MaxLife));
                view.transform.SetSiblingIndex(_damageIndicatorSiblingBase + order);
                view.rectTransform.anchoredPosition = new Vector2(
                    Mathf.Cos(indicator.Angle) * radius,
                    Mathf.Sin(indicator.Angle) * radius);
                view.rectTransform.rotation = Quaternion.Euler(0, 0, indicator.Angle * Mathf.Rad2Deg);
                view.color = new Color(0.937f, 0.267f, 0.286f, Mathf.Min(1f, progress * 1.7f) * 0.85f);
                view.enabled = true;
            }
        }

        private void RenderFloaters()
        {
            if (_canvas == null || _camera == null) return;
            var canvasRect = _canvas.transform as RectTransform;
            if (canvasRect == null) return;
            EnsureFloaterOrderEntries();
            for (var index = 0; index < _floaters.Length; index++)
            {
                if (!_floaters[index].Active) Hide(_floaterViews[index]);
            }
            for (var order = 0; order < _floaterOrderCount; order++)
            {
                var index = _floaterOrder[order];
                if (index < 0 || index >= _floaters.Length) continue;
                var floater = _floaters[index];
                var view = _floaterViews[index];
                if (!floater.Active || view == null) continue;
                view.transform.SetSiblingIndex(_floaterSiblingBase + order);
                var screen = _camera.WorldToScreenPoint(new Vector3(floater.Position.x, floater.Position.y, 0));
                if (screen.z <= 0 || !RectTransformUtility.ScreenPointToLocalPointInRectangle(
                        canvasRect,
                        screen,
                        null,
                        out var local))
                {
                    view.enabled = false;
                    continue;
                }
                var progress = Mathf.Clamp01(floater.Life / Mathf.Max(0.001f, floater.MaxLife));
                view.rectTransform.anchoredPosition = local;
                view.rectTransform.localScale = Vector3.one;
                view.text = floater.Text;
                view.fontSize = floater.FontSize;
                view.color = new Color(
                    floater.Color.r,
                    floater.Color.g,
                    floater.Color.b,
                    floater.Color.a * Mathf.Min(1f, progress * 2f));
                view.enabled = true;
            }
        }

        private void Render()
        {
            var playerVisible = _playerHealth > 0 && !_gameOver && !_mainMenuBrowsing;
            if (!playerVisible)
            {
                Hide(_playerAuraView);
                Hide(_playerView);
                Hide(_playerRingView);
            }
            if (playerVisible && _playerAuraView != null)
            {
                _playerAuraView.transform.position = _playerPosition;
                var auraRadius = 32f + Mathf.Sin(_ambientClock * 2.2f) * 4f;
                _playerAuraView.transform.localScale = Vector3.one * (auraRadius * 2f);
                var adrenalLit = _adrenalTimer > 0 && SupportRank("adrenal") > 0;
                _playerAuraView.sprite = ProceduralSpriteFactory.PlayerAura(adrenalLit);
                _playerAuraView.color = Color.white;
                _playerAuraView.enabled = true;
            }
            if (playerVisible && _playerView != null)
            {
                _playerView.transform.position = _playerPosition;
                var blink = _playerIframes > 0 && Mathf.Sin(_ambientClock * 34f) > 0;
                _playerView.color = new Color(1f, 1f, 1f, blink ? 0.35f : 1f);
                _playerView.enabled = true;
            }
            if (playerVisible && _playerRingView != null)
            {
                _playerRingView.transform.position = _playerPosition;
                _playerRingView.transform.rotation = Quaternion.Euler(
                    0,
                    0,
                    _ambientClock * PlayerRingRotationRate() * Mathf.Rad2Deg);
                _playerRingView.transform.localScale = Vector3.one * 62f;
                var blink = _playerIframes > 0 && Mathf.Sin(_ambientClock * 34f) > 0;
                _playerRingView.color = new Color(1f, 1f, 1f, blink ? 0.35f : 1f);
                _playerRingView.enabled = true;
            }

            // The browser draws its compact enemy array forward. Pooled Unity
            // slots are not that array after swap-removal, so keep the visual
            // refresh in logical source order and mirror that order inside the
            // shared body sorting slot with rendererPriority.
            for (var i = 0; i < _enemies.Length; i++)
            {
                Hide(_enemyHarvesterFullViews[i]);
                Hide(_enemyExploderWarningViews[i]);
                if (!_enemies[i].Active) Hide(_enemyViews[i]);
            }
            for (var order = 0; order < _enemyOrderCount; order++)
            {
                var i = _enemyOrder[order];
                if (i < 0 || i >= _enemies.Length || !_enemies[i].Active || _enemyViews[i] == null) continue;
                var enemy = _enemies[i];
                _enemyViews[i].rendererPriority = order;
                SetEnemyPresentationPriority(i, order);
                var rosterTwoVisual = enemy.Roster == EnemyRoster.Two && !enemy.Elite &&
                    (enemy.Id == "chaser" || enemy.Id == "gunner" || enemy.Id == "guard" || enemy.Id == "exploder");
                var harvesterFull = enemy.Id == "harvester" &&
                    enemy.StoredXp >= PickupRules.HarvesterXpLimits(_xpNeed).Individual;
                var flash = SourceEnemyVisualFlash(
                    enemy.Id,
                    enemy.Elite,
                    enemy.State,
                    enemy.HitTimer,
                    harvesterFull,
                    enemy.Seed,
                    _ambientClock);
                var spriteId = SourceEnemySpriteId(enemy);
                _enemyViews[i].sprite = rosterTwoVisual
                    ? ProceduralSpriteFactory.RosterTwoEnemy(enemy.Id, flash)
                    : ProceduralSpriteFactory.Enemy(
                        spriteId,
                        EnemySpriteAccent(enemy),
                        flash);
                _enemyViews[i].transform.position = enemy.Position;
                _enemyViews[i].transform.rotation = Quaternion.Euler(
                    0,
                    0,
                    enemy.Rotation * Mathf.Rad2Deg);
                var enemyVisualScale = SourceEnemyIntroScale(enemy.Age);
                if (enemy.Id == "exploder" && enemy.State == 1)
                {
                    var definition = FindEnemy("exploder");
                    var telegraph = enemy.EliteKind.HasValue &&
                        enemy.EliteKind.Value == EliteVariantId.Exploder
                        ? (float)EliteRules.EliteVariantStatsFor(EliteVariantId.Exploder).TelegraphSeconds
                        : (float)(definition?.TelegraphSeconds ?? 0.9) +
                            (enemy.Roster == EnemyRoster.Two ? 0.28f : 0);
                    enemyVisualScale *= SourceExploderArmedScale(
                        enemy.StateTimer,
                        telegraph,
                        _ambientClock);
                }
                _enemyViews[i].transform.localScale = Vector3.one *
                    (SourceEnemySpriteWorldSize(enemy) * enemyVisualScale);
                if (enemy.Id == "exploder" && enemy.State == 1)
                {
                    var definition = FindEnemy("exploder");
                    var eliteExploder = enemy.EliteKind.HasValue &&
                        enemy.EliteKind.Value == EliteVariantId.Exploder;
                    var telegraph = eliteExploder
                        ? (float)EliteRules.EliteVariantStatsFor(EliteVariantId.Exploder).TelegraphSeconds
                        : (float)(definition?.TelegraphSeconds ?? 0.9) +
                            (enemy.Roster == EnemyRoster.Two ? 0.28f : 0);
                    var warning = EnsureEnemyExploderWarningView(i);
                    warning.sprite = enemy.Roster == EnemyRoster.Two
                        ? ProceduralSpriteFactory.RosterTwoEnemy("exploder", true)
                        : ProceduralSpriteFactory.Enemy("exploder", EnemySpriteAccent(enemy), true);
                    warning.transform.position = enemy.Position;
                    warning.transform.rotation = _enemyViews[i].transform.rotation;
                    warning.transform.localScale = _enemyViews[i].transform.localScale;
                    warning.color = new Color(
                        1f,
                        1f,
                        1f,
                        SourceExploderWarningAlpha(
                            enemy.StateTimer,
                            telegraph,
                            eliteExploder,
                            _ambientClock));
                    warning.enabled = true;
                }
                if (harvesterFull)
                {
                    var overlay = EnsureEnemyHarvesterFullView(i);
                    overlay.sprite = ProceduralSpriteFactory.Enemy(
                        "harvester",
                        EnemySpriteAccent(enemy),
                        true);
                    overlay.transform.position = enemy.Position;
                    overlay.transform.rotation = _enemyViews[i].transform.rotation;
                    overlay.transform.localScale = _enemyViews[i].transform.localScale;
                    overlay.color = new Color(
                        1f,
                        1f,
                        1f,
                        SourceHarvesterFullOverlayAlpha(_ambientClock, enemy.Seed));
                    overlay.enabled = true;
                }
            }
            RenderEliteTelegraphs();
            RenderEnemyTelegraphs();
            RenderEnemyStatus();
            // Player bullets are also a browser compact array. Keep their
            // shared body sorting slot in source order after pooled reuse.
            EnsureBulletOrderEntries();
            for (var order = 0; order < _bulletOrderCount; order++)
            {
                var i = _bulletOrder[order];
                if (i < 0 || i >= _bullets.Length || !_bullets[i].Active || _bulletViews[i] == null)
                {
                    if (i >= 0 && i < _bullets.Length) Hide(_bulletViews[i]);
                    if (i >= 0 && i < _bullets.Length)
                    {
                        Hide(_railAfterimageFarViews[i]);
                        Hide(_railAfterimageNearViews[i]);
                    }
                    continue;
                }
                _bulletViews[i].rendererPriority = order;
                _bulletViews[i].transform.position = _bullets[i].Position;
                var visualScale = SourceBulletVisualScale(
                    ContentCatalog.Weapons[_bullets[i].WeaponIndex].Id,
                    _bullets[i].Radius,
                    _bullets[i].Rank);
                var projectileId = ContentCatalog.Weapons[_bullets[i].WeaponIndex].Id;
                var projectileFrame = ProceduralSpriteFactory.ProjectileFrame(
                    projectileId,
                    SourceProjectileFrameIndex(_bullets[i].Velocity));
                _bulletViews[i].sprite = projectileFrame;
                _bulletViews[i].transform.rotation = Quaternion.identity;
                var projectileFrameSize = SourceProjectileSpriteWorldSize(projectileId);
                _bulletViews[i].transform.localScale = Vector3.one * (projectileFrameSize * visualScale);
                var isRailgun = _bullets[i].WeaponIndex >= 0 &&
                    _bullets[i].WeaponIndex < ContentCatalog.Weapons.Length &&
                    ContentCatalog.Weapons[_bullets[i].WeaponIndex].Id == "railgun";
                if (isRailgun)
                {
                    var direction = SourceVisualDirection(_bullets[i].Velocity);
                    var scale = Vector3.one * (projectileFrameSize * visualScale);
                    var far = EnsureRailAfterimageView(i, false);
                    far.sprite = projectileFrame;
                    far.transform.position = _bullets[i].Position - direction * 34f;
                    far.transform.rotation = Quaternion.identity;
                    far.transform.localScale = scale;
                    far.color = new Color(1f, 1f, 1f, 0.1f);
                    far.enabled = true;
                    var near = EnsureRailAfterimageView(i, true);
                    near.sprite = projectileFrame;
                    near.transform.position = _bullets[i].Position - direction * 19f;
                    near.transform.rotation = Quaternion.identity;
                    near.transform.localScale = scale;
                    near.color = new Color(1f, 1f, 1f, 0.22f);
                    near.enabled = true;
                }
                else
                {
                    Hide(_railAfterimageFarViews[i]);
                    Hide(_railAfterimageNearViews[i]);
                }
                var contrast = _bulletContrastViews[i];
                if (contrast != null)
                {
                    var highContrast = _saveData?.settings != null && _saveData.settings.highContrast;
                    contrast.sprite = projectileFrame;
                    contrast.transform.position = _bullets[i].Position;
                    contrast.transform.rotation = Quaternion.identity;
                    contrast.transform.localScale = Vector3.one *
                        (projectileFrameSize * visualScale * 1.22f);
                    contrast.enabled = highContrast;
                }
            }
            // Hostile shots use the same forward draw order as their source
            // array; fixed Unity slots must not decide overlap order.
            EnsureHostileShotOrderEntries();
            for (var order = 0; order < _hostileShotOrderCount; order++)
            {
                var i = _hostileShotOrder[order];
                if (i < 0 || i >= _hostileShots.Length || !_hostileShots[i].Active || _hostileShotViews[i] == null)
                {
                    if (i >= 0 && i < _hostileShots.Length) Hide(_hostileShotViews[i]);
                    continue;
                }
                _hostileShotViews[i].rendererPriority = order;
                _hostileShotViews[i].transform.position = _hostileShots[i].Position;
                if (!_hostileShots[i].MeteorOwned && !_hostileShots[i].Curved)
                {
                    _hostileShotViews[i].sprite = ProceduralSpriteFactory.ProjectileFrame(
                        "gunner",
                        SourceProjectileFrameIndex(_hostileShots[i].Velocity));
                }
                _hostileShotViews[i].transform.rotation = Quaternion.identity;
                _hostileShotViews[i].transform.localScale = Vector3.one *
                    (_hostileShots[i].MeteorOwned
                        ? 18f
                        : SourceProjectileSpriteWorldSize(_hostileShots[i].Curved ? "curved" : "gunner"));
            }
            // Meteors are rendered from the browser's compact meteor array as
            // well, so keep body order stable when a slot is recycled.
            EnsureMeteorOrderEntries();
            for (var order = 0; order < _meteorOrderCount; order++)
            {
                var i = _meteorOrder[order];
                if (i < 0 || i >= _meteors.Length || !_meteors[i].Active)
                {
                    if (i >= 0 && i < _meteors.Length)
                    {
                        Hide(_meteorViews[i]);
                        Hide(_meteorHitViews[i]);
                        Hide(_meteorCoreViews[i]);
                        Hide(_meteorDangerArcViews[i]);
                        Hide(_meteorDangerRingViews[i]);
                        Hide(_meteorHealthArcViews[i]);
                    }
                    continue;
                }
                var meteorView = EnsureMeteorView(i);
                meteorView.rendererPriority = order;
                meteorView.sprite = ProceduralSpriteFactory.Meteor(_meteors[i].Variant, _meteors[i].Explosive);
                meteorView.transform.position = _meteors[i].Position;
                meteorView.transform.rotation = Quaternion.Euler(
                    0,
                    0,
                    _meteors[i].Rotation * Mathf.Rad2Deg);
                meteorView.transform.localScale = Vector3.one *
                    SourceMeteorSpriteWorldSize(_meteors[i].Variant, _meteors[i].Explosive);
                // The browser never tints the meteor body while armed; the
                // warning arcs and seeded core carry the fuse read instead.
                meteorView.color = Color.white;
                var hitView = EnsureMeteorHitView(i);
                hitView.sprite = meteorView.sprite;
                hitView.transform.position = _meteors[i].Position;
                hitView.transform.rotation = meteorView.transform.rotation;
                hitView.transform.localScale = meteorView.transform.localScale;
                hitView.color = new Color(1f, 1f, 1f, 0.3f);
                hitView.enabled = !_meteors[i].Explosive && _meteors[i].HitTimer > 0;
                Hide(_meteorHealthArcViews[i]);
                if (_meteorCoreViews[i] != null)
                {
                    _meteorCoreViews[i].transform.position = _meteors[i].Position;
                    _meteorCoreViews[i].transform.rotation = meteorView.transform.rotation;
                    _meteorCoreViews[i].enabled = _meteors[i].Explosive;
                }
                if (_meteors[i].FuseTimer > 0)
                {
                    var fuse = Mathf.Clamp01(1f - _meteors[i].FuseTimer / (float)MeteorRules.ExplosiveFlashSeconds);
                    var sweep = Mathf.PI * 2f * (0.35f + fuse * 0.65f);
                    var dangerArc = EnsureMeteorDangerArcView(i);
                    SetArcLine(
                        dangerArc,
                        _meteors[i].Position,
                        (float)MeteorRules.ExplosiveBlastRadius,
                        -Mathf.PI * 0.5f,
                        -Mathf.PI * 0.5f + sweep,
                        1.5f + fuse * 1.5f,
                        new Color(249f / 255f, 115f / 255f, 22f / 255f, 0.3f + fuse * 0.5f));
                    var dangerRing = EnsureMeteorDangerRingView(i);
                    SetArcLine(
                        dangerRing,
                        _meteors[i].Position,
                        (float)MeteorRules.ExplosiveBlastRadius - 6f,
                        0,
                        Mathf.PI * 2f,
                        1f,
                        new Color(253f / 255f, 230f / 255f, 138f / 255f, 0.18f + fuse * 0.2f));
                    var rate = 6f + fuse * 22f;
                    var beat = 0.5f + 0.5f * Mathf.Sin(_ambientClock * rate + _meteors[i].Seed);
                    var heat = Mathf.Min(0.95f, 0.4f + fuse * 0.5f + beat * 0.22f);
                    if (_meteorCoreViews[i] != null)
                    {
                        _meteorCoreViews[i].color = new Color(1f, 1f, 1f, heat);
                        _meteorCoreViews[i].transform.localScale = Vector3.one * (_meteors[i].VisibleRadius * (2.1f + fuse * 0.5f));
                    }
                }
                else
                {
                    Hide(_meteorDangerArcViews[i]);
                    Hide(_meteorDangerRingViews[i]);
                    if (_meteorCoreViews[i] != null)
                    {
                        var heat = 0.12f + (0.5f + 0.5f * Mathf.Sin(_ambientClock * 2.2f + _meteors[i].Seed)) * 0.1f;
                        _meteorCoreViews[i].color = new Color(1f, 1f, 1f, heat);
                        _meteorCoreViews[i].transform.localScale = Vector3.one * (_meteors[i].VisibleRadius * 1.7f);
                    }
                    if (_meteors[i].Health < _meteors[i].MaxHealth)
                    {
                        var healthRatio = Mathf.Clamp01(_meteors[i].Health / Mathf.Max(0.001f, _meteors[i].MaxHealth));
                        SetArcLine(
                            EnsureMeteorHealthArcView(i),
                            _meteors[i].Position,
                            _meteors[i].VisibleRadius + 5f,
                            -Mathf.PI * 0.5f,
                            -Mathf.PI * 0.5f + Mathf.PI * 2f * healthRatio,
                            2f,
                            new Color(0.886f, 0.51f, 0.247f, 0.45f));
                    }
                }
            }
            RenderSourceFxOrder();
            RenderImpactMarks();
            RenderBlastWaves();
            // Pickups are drawn in their compact forward order. Their slot
            // list already tracks the browser's swap-removal behavior.
            for (var order = 0; order < _pickupOrderCount; order++)
            {
                var i = _pickupOrder[order];
                if (i < 0 || i >= _pickups.Length || !_pickups[i].Active || _pickupViews[i] == null)
                {
                    if (i >= 0 && i < _pickups.Length) Hide(_pickupViews[i]);
                    continue;
                }
                _pickupViews[i].rendererPriority = order;
                var xpTier = -1;
                if (_pickups[i].Kind == PickupKind.Xp)
                {
                    xpTier = XpPickupTier(_pickups[i].Value);
                    _pickupViews[i].sprite = ProceduralSpriteFactory.Gem(xpTier);
                }
                _pickupViews[i].transform.position = _pickups[i].Position;
                var pickupKind = PickupKindName(_pickups[i].Kind);
                var pulse = SourcePickupPulseScale(
                    pickupKind,
                    _pickups[i].Age,
                    _qualityPreset.PickupPulse);
                _pickupViews[i].transform.rotation = Quaternion.Euler(
                    0,
                    0,
                    SourcePickupRotationRadians(pickupKind, _pickups[i].Age) * Mathf.Rad2Deg);
                var frameSize = pickupKind == "xp"
                    ? SourceXpPickupFrameSize(xpTier)
                    : SourceSpecialPickupFrameSize();
                _pickupViews[i].transform.localScale = Vector3.one * (frameSize * pulse);
            }
            RenderBossTelegraphs();
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var i = _bossOrder[bossOrder];
                var boss = _bosses[i];
                if ((!boss.Active && boss.DeathTimer <= 0) || _bossViews[i] == null) continue;
                _bossViews[i].sprite = ProceduralSpriteFactory.Boss(
                    boss.Id,
                    BossAccent(boss),
                    boss.HitTimer > 0);
                _bossViews[i].transform.position = boss.Position;
                var introProgress = boss.Active && boss.State == 4
                    ? BackOut(Mathf.Clamp01(1f - boss.StateTimer / 1.6f))
                    : 1f;
                var deathAlpha = boss.Active ? 1f : Mathf.Clamp01(boss.DeathTimer / 1.4f);
                _bossViews[i].color = new Color(1f, 1f, 1f, deathAlpha);
                _bossViews[i].transform.localScale = Vector3.one *
                    (SourceBossSpriteWorldSize(boss.Id, boss.Radius) * introProgress);
                _bossViews[i].transform.rotation = Quaternion.Euler(
                    0,
                    0,
                    SourceBossBodyRotationRadians(_ambientClock) * Mathf.Rad2Deg);
                _bossViews[i].enabled = true;
            }
            for (var i = 0; i < _arcEffects.Length; i++)
            {
                var effect = _arcEffects[i];
                if (!effect.Active || _arcViews[i] == null) continue;
                _arcViews[i].enabled = true;
                if (_arcCoreViews[i] != null) _arcCoreViews[i].enabled = true;
            }

            if (_camera != null)
            {
                var shake = CameraShakeOffset();
                _camera.transform.position = new Vector3(
                    _cameraFollowPosition.x + shake.x,
                    _cameraFollowPosition.y + shake.y,
                    -10);
            }

            RenderArena();
            RenderDeathGhosts();
            RenderDamageIndicators();
            RenderFloaters();
        }

        private void SetEnemyPresentationPriority(int index, int priority)
        {
            if (index < 0 || index >= _enemies.Length) return;
            SetRendererPriority(_enemyViews[index], priority);
            SetRendererPriority(_enemyHarvesterFullViews[index], priority);
            SetRendererPriority(_enemyExploderWarningViews[index], priority);
            SetRendererPriority(_eliteMarkViews[index], priority);
            SetRendererPriority(_eliteChargeLaneViews[index], priority);
            SetRendererPriority(_eliteChargeArrowViews[index], priority);
            SetRendererPriority(_eliteChargeFillRenderers[index], priority);
            SetRendererPriority(_eliteChargeArrowFillRenderers[index], priority);
            SetRendererPriority(_enemyTelegraphRingViews[index], priority);
            SetRendererPriority(_enemyTelegraphLineViews[index], priority);
            SetRendererPriority(_enemyTelegraphSecondaryLineViews[index], priority);
            SetRendererPriority(_enemyTelegraphTertiaryLineViews[index], priority);
            SetRendererPriority(_enemyHarvesterCapacityRingViews[index], priority);
            SetRendererPriority(_enemyTelegraphSiegeDashRenderers[index], priority);
            SetRendererPriority(_enemyTelegraphExploderFillViews[index], priority);
            SetRendererPriority(_enemyTelegraphMortarFillViews[index], priority);
            SetRendererPriority(_enemyTelegraphFillRenderers[index], priority);
            SetRendererPriority(_enemyTelegraphArrowFillRenderers[index], priority);
            SetRendererPriority(_enemyHealthArcViews[index], priority);
            SetRendererPriority(_enemyShieldArcViews[index], priority);
            SetRendererPriority(_enemyHealthBackgroundViews[index], priority);
            SetRendererPriority(_enemyHealthFillViews[index], priority);
            for (var segment = 0; segment < ExploderTelegraphSegmentCount; segment++)
                SetRendererPriority(
                    _enemyTelegraphExploderSegmentViews[index * ExploderTelegraphSegmentCount + segment],
                    priority);
            for (var segment = 0; segment < MortarTelegraphSegmentCount; segment++)
                SetRendererPriority(
                    _enemyTelegraphMortarSegmentViews[index * MortarTelegraphSegmentCount + segment],
                    priority);
        }

        private static void SetRendererPriority(Renderer renderer, int priority)
        {
            if (renderer != null) renderer.rendererPriority = priority;
        }

        private void AddCameraShake(float amount)
        {
            if (_saveData?.settings == null || _saveData.settings.reducedMotion) return;
            var scale = Mathf.Clamp01(_saveData.settings.shake);
            if (scale <= 0 || amount <= 0) return;
            _cameraTrauma = Mathf.Clamp01(_cameraTrauma + amount * scale);
        }

        private void TriggerFreeze(float seconds)
        {
            _freezeTimer = Mathf.Max(_freezeTimer, Mathf.Max(0, seconds));
        }

        private Vector2 CameraShakeOffset()
        {
            if (_cameraTrauma <= 0) return Vector2.zero;
            var magnitude = CameraShakeAmplitude(_cameraTrauma);
            return new Vector2(
                ((float)_fxRng.Next() * 2f - 1f) * magnitude,
                ((float)_fxRng.Next() * 2f - 1f) * magnitude);
        }

        private static float CameraShakeAmplitude(float trauma)
        {
            var clamped = Mathf.Clamp01(trauma);
            return clamped * clamped * 14f;
        }

        private void UpdateHud()
        {
            var hudVisible = ShouldShowHud();
            if (_canvas != null) _canvas.enabled = true;
            if (_hudGroup != null)
            {
                _hudGroup.alpha = Mathf.MoveTowards(
                    _hudGroup.alpha,
                    hudVisible ? 1f : 0f,
                    Time.unscaledDeltaTime / HudFadeSeconds);
                _hudGroup.interactable = hudVisible;
                _hudGroup.blocksRaycasts = hudVisible;
            }
            UpdateHudResponsiveLayout();
            UpdateDamageOverlays();
            UpdateArenaBanner();
            var hpFraction = _playerMaxHealth > 0
                ? Mathf.Clamp01(_playerHealth / _playerMaxHealth)
                : 0;
            _healthGhostFraction +=
                (hpFraction - _healthGhostFraction) *
                (1f - Mathf.Exp(-3.2f * Mathf.Max(0, Time.unscaledDeltaTime)));
            if (_healthGhostFraction < hpFraction) _healthGhostFraction = hpFraction;
            if (_xpBarFill != null)
                _xpBarFill.fillAmount = _xpNeed > 0 ? Mathf.Clamp01(_xp / _xpNeed) : 0;
            if (_healthBarFill != null) _healthBarFill.fillAmount = hpFraction;
            if (_healthBarGhost != null) _healthBarGhost.fillAmount = Mathf.Clamp01(_healthGhostFraction);
            if (_healthText != null)
                _healthText.text = $"INTEGRITY   {Mathf.CeilToInt(Mathf.Max(0, _playerHealth))}/{Mathf.CeilToInt(_playerMaxHealth)}";
            if (_healthLabelText != null) _healthLabelText.text = "INTEGRITY";
            if (_healthValueText != null)
                _healthValueText.text = $"{Mathf.CeilToInt(Mathf.Max(0, _playerHealth))}/{Mathf.CeilToInt(_playerMaxHealth)}";
            if (_timeText != null)
            {
                var seconds = Mathf.Max(0, Mathf.FloorToInt(_time));
                _timeText.text = $"{seconds / 60}:{seconds % 60:00}";
            }
            if (_levelText != null) _levelText.text = $"LV {_level}";
            if (_metricsText != null)
                _metricsText.text = $"K {_kills}   P {_partsEarned}   SCORE {CurrentScore():N0}";
            if (_metricValues[0] != null) _metricValues[0].text = _kills.ToString();
            if (_metricValues[1] != null) _metricValues[1].text = _partsEarned.ToString();
            if (_metricValues[2] != null) _metricValues[2].text = CurrentScore().ToString("N0");
            if (_pauseButton != null)
            {
                _pauseButton.gameObject.SetActive(hudVisible);
                _pauseButton.interactable =
                    !_paused && !_revivePending && !_levelUpActive && _menuPage == MenuPage.None;
            }
            if (_pauseButtonText != null) _pauseButtonText.text = "||";
            var overdriveActive = _overdriveTimer > 0 && !_gameOver;
            if (_boostPanel != null) _boostPanel.enabled = overdriveActive;
            if (_boostIcon != null) _boostIcon.enabled = overdriveActive;
            if (_boostText != null)
            {
                _boostText.enabled = overdriveActive;
                if (overdriveActive)
                    _boostText.text = "OVERCLOCK";
            }
            if (_boostSecondsText != null)
            {
                _boostSecondsText.enabled = overdriveActive;
                if (overdriveActive)
                    _boostSecondsText.text = $"{Mathf.CeilToInt(_overdriveTimer)}s";
            }
            if (_boostBar != null)
            {
                _boostBar.enabled = overdriveActive;
                _boostBar.fillAmount = Mathf.Clamp01(
                    _overdriveTimer / (float)PickupRules.OverdriveDurationSeconds);
            }
            if (_loadoutText != null && Time.unscaledTime >= _nextLoadoutHudRefresh)
            {
                _nextLoadoutHudRefresh = Time.unscaledTime + 0.25f;
                var loadout = BuildLoadoutHudText();
                if (loadout != _lastLoadoutHudText)
                {
                    _lastLoadoutHudText = loadout;
                    _loadoutText.text = loadout;
                    if (_supportStripText != null)
                    {
                        _supportStripText.text = BuildUpgradeStripHudText(false);
                        _supportStripText.enabled = false;
                    }
                    if (_lateStripText != null)
                    {
                        _lateStripText.text = BuildUpgradeStripHudText(true);
                        _lateStripText.enabled = false;
                    }
                    UpdateBuildChipHud();
                }
            }
            if (_hudText != null)
            {
                var phase = _gameOver
                    ? "GAME OVER — press R"
                    : _revivePending
                        ? "INTEGRITY ZERO — press Y to revive or N to end"
                    : _levelUpActive
                        ? "LEVEL UP — press 1, 2, or 3"
                        : _paused ? "PAUSED — press Esc" : "PLAYING";
                _hudText.text = $"{phase}\nTime {_time:0.0}s   Level {_level}   XP {_xp:0}/{_xpNeed}\n" +
                    $"Integrity {_playerHealth:0}/{_playerMaxHealth:0}   Kills {_kills}   Score {CurrentScore()}\n" +
                    $"Pistol rank {_pistolRank}/6   Calibration {_calibrationRank}/4\n" +
                    $"Arena {ArenaName(_arenaId)}   Cycle {ArenaCycleRules.At(ArenaIdName(_arenaId), _time).CycleId}";
            }

            if (_helpText != null)
            {
                // The browser keeps normal-run controls out of the HUD. The
                // Unity hint was useful during early bring-up, but it is an
                // extra visible element compared with GameUI.tsx. Keep the
                // text view only for the diagnostic level-up list.
                _helpText.enabled = _levelUpActive && _levelOptions != null;
                if (_helpText.enabled)
                {
                    var options = "LEVEL UP\n";
                    for (var index = 0; index < _levelOptions.Length; index++)
                    {
                        options += (index + 1) + ". " + _levelOptions[index].Name + " - " + _levelOptions[index].Description + "\n";
                    }
                    options += "Q. Reroll (" + _rerollsRemaining + " left)\n";
                    _helpText.text = options;
                }
            }

            var activeBossCount = ActiveBosses();
            var bossHealth = 0f;
            var bossMaxHealth = 0f;
            BossState firstBoss = default(BossState);
            var firstBossSet = false;
            EnsureBossOrderEntries();
            for (var bossOrder = 0; bossOrder < _bossOrderCount; bossOrder++)
            {
                var index = _bossOrder[bossOrder];
                var boss = _bosses[index];
                if (!boss.Active) continue;
                if (!firstBossSet)
                {
                    firstBoss = boss;
                    firstBossSet = true;
                }
                bossHealth += Mathf.Max(0, boss.Health);
                bossMaxHealth += Mathf.Max(0, boss.MaxHealth);
            }
            var bossFraction = bossMaxHealth > 0
                ? Mathf.Clamp01(bossHealth / bossMaxHealth)
                : 0;
            if (_bossText != null)
            {
                if (activeBossCount == 0)
                {
                    _bossText.text = "";
                    _bossText.enabled = false;
                    if (_bossNameText != null) _bossNameText.enabled = false;
                    if (_bossHealthText != null) _bossHealthText.enabled = false;
                }
                else
                {
                    var bossName = activeBossCount == 1
                        ? (FindBoss(firstBoss.Id)?.Name ?? firstBoss.Id).ToUpperInvariant()
                        : $"{activeBossCount} BOSSES";
                    _bossText.text = $"{bossName}    {Mathf.CeilToInt(bossHealth)}";
                    _bossText.enabled = false;
                    if (_bossNameText != null)
                    {
                        _bossNameText.text = bossName;
                        _bossNameText.enabled = true;
                    }
                    if (_bossHealthText != null)
                    {
                        _bossHealthText.text = Mathf.CeilToInt(bossHealth).ToString();
                        _bossHealthText.enabled = true;
                    }
                }
            }
            if (_bossBarBackground != null && _bossBarFill != null)
            {
                _bossBarBackground.enabled = activeBossCount > 0;
                _bossBarFill.enabled = activeBossCount > 0;
                if (activeBossCount > 0)
                {
                    const float barWidth = 440f;
                    const float barHeight = 9f;
                    var fillWidth = barWidth * bossFraction;
                    _bossBarFill.rectTransform.sizeDelta = new Vector2(fillWidth, barHeight);
                    _bossBarFill.rectTransform.anchoredPosition = new Vector2(-barWidth * 0.5f, -105f);
                }
            }
            UpdateToastViews();
            UpdateTouchHud();
        }

        private void UpdateArenaBanner()
        {
            if (_arenaBannerPanel == null || _arenaBannerTitle == null || _arenaBannerDetail == null)
                return;

            var visible = _arenaBannerRemaining > 0.001f &&
                _menuPage == MenuPage.None &&
                !_gameOver &&
                !_levelUpActive &&
                !_revivePending;
            _arenaBannerPanel.enabled = visible;
            _arenaBannerTitle.enabled = visible;
            _arenaBannerDetail.enabled = visible;
            if (!visible) return;

            // Match the browser's 0.35-second fade-in and ambient pulse.
            var fadeIn = Mathf.Clamp01(
                ((float)ArenaRules.WarningSeconds - _arenaBannerRemaining) / 0.35f);
            var pulse = 0.72f + 0.28f * Mathf.Sin(_ambientClock * 6f);
            var panelColor = _arenaBannerPanel.color;
            panelColor.a = 0.55f * fadeIn;
            _arenaBannerPanel.color = panelColor;
            var outlineColor = new Color(
                248f / 255f,
                113f / 255f,
                113f / 255f,
                0.55f * pulse * fadeIn);
            _arenaBannerOutline.effectColor = outlineColor;
            var titleColor = _arenaBannerTitle.color;
            titleColor.a = pulse * fadeIn;
            _arenaBannerTitle.color = titleColor;
            var detailColor = _arenaBannerDetail.color;
            detailColor.a = 0.85f * fadeIn;
            _arenaBannerDetail.color = detailColor;
            var seconds = Mathf.Max(1, Mathf.CeilToInt(_arenaBannerRemaining));
            _arenaBannerDetail.text = ArenaName(_arenaBannerIncoming) + " · " + seconds + "s";
        }

        private void UpdateHudResponsiveLayout()
        {
            if (_canvas == null) return;
            var viewportWidth = Screen.width;
            var viewportHeight = Screen.height;
            var safeArea = Screen.safeArea;
            var narrow = viewportWidth <= 720;
            if (_hudLayoutInitialized &&
                narrow == _hudNarrow &&
                viewportWidth == _hudLayoutWidth &&
                viewportHeight == _hudLayoutHeight &&
                safeArea == _hudLayoutSafeArea) return;
            _hudLayoutInitialized = true;
            _hudNarrow = narrow;
            _hudLayoutWidth = viewportWidth;
            _hudLayoutHeight = viewportHeight;
            _hudLayoutSafeArea = safeArea;
            var safeLeftInset = Mathf.Max(12f, safeArea.xMin);
            var safeRightInset = Mathf.Max(12f, viewportWidth - safeArea.xMax);
            var safeTopInset = Mathf.Max(0f, viewportHeight - safeArea.yMax);

            // The browser's narrow grid gives the integrity block the
            // remaining first-column width: viewport minus the 78px clock,
            // 44px pause button, two 8px gaps, and 12px outer margins. Keep
            // the source minimum of 120px instead of leaving the desktop
            // 240px panel stranded beside the clock.
            var healthWidth = narrow ? Mathf.Max(120f, Screen.width - 162f) : 240f;
            if (_healthPanel != null)
            {
                _healthPanel.rectTransform.sizeDelta = new Vector2(healthWidth, 43f);
                if (_healthBarBackground != null)
                    _healthBarBackground.rectTransform.sizeDelta = new Vector2(healthWidth - 20f, 10f);
                if (_healthBarGhost != null)
                    _healthBarGhost.rectTransform.sizeDelta = new Vector2(healthWidth - 20f, 10f);
                if (_healthBarFill != null)
                    _healthBarFill.rectTransform.sizeDelta = new Vector2(healthWidth - 20f, 10f);
                if (_healthText != null)
                    _healthText.rectTransform.sizeDelta = new Vector2(healthWidth - 20f, 18f);
                if (_healthLabelText != null)
                    _healthLabelText.rectTransform.sizeDelta = new Vector2(Mathf.Max(80f, healthWidth - 90f), 16f);
                if (_healthValueText != null)
                    _healthValueText.rectTransform.anchoredPosition = new Vector2(12f + healthWidth - 10f, -27f);
            }

            if (_clockPanel != null)
            {
                var clockWidth = narrow ? 78f : 94f;
                _clockPanel.rectTransform.sizeDelta = new Vector2(clockWidth, 52f);
                SetTopHudAnchor(_clockPanel.rectTransform, narrow, clockWidth, -13f);
                if (_timeText != null)
                {
                    _timeText.rectTransform.sizeDelta = new Vector2(clockWidth, 30f);
                    SetTopHudAnchor(_timeText.rectTransform, narrow, clockWidth, -19f);
                }
                if (_levelText != null)
                {
                    _levelText.rectTransform.sizeDelta = new Vector2(clockWidth, 16f);
                    SetTopHudAnchor(_levelText.rectTransform, narrow, clockWidth, -49f);
                }
            }

            var metricsVisible = !narrow;
            if (_metricsPanel != null) _metricsPanel.enabled = metricsVisible;
            for (var index = 0; index < _metricIcons.Length; index++)
            {
                if (_metricIcons[index] != null) _metricIcons[index].enabled = metricsVisible;
                if (_metricValues[index] != null) _metricValues[index].enabled = metricsVisible;
                if (index < _metricDividers.Length && _metricDividers[index] != null)
                    _metricDividers[index].enabled = metricsVisible;
            }

            for (var index = 0; index < _weaponChipBackgrounds.Length; index++)
            {
                var width = narrow ? 56f : 122f;
                if (_weaponChipBackgrounds[index] != null)
                {
                    _weaponChipBackgrounds[index].rectTransform.sizeDelta = new Vector2(width, 34f);
                    _weaponChipBackgrounds[index].rectTransform.anchoredPosition =
                        new Vector2(12f + index * (narrow ? 63f : 129f), 12f);
                }
            }
            ResizeOwnedChipViews(
                _supportChipBackgrounds,
                _supportChipRanks,
                narrow,
                narrow ? 60f : 174f,
                new Vector2(safeLeftInset, -OwnedUpgradeStripTop(false, safeTopInset)),
                false,
                viewportHeight);
            ResizeOwnedChipViews(
                _lateChipBackgrounds,
                _lateChipRanks,
                narrow,
                narrow ? 60f : 174f,
                new Vector2(-safeRightInset, -OwnedUpgradeStripTop(true, safeTopInset)),
                true,
                viewportHeight);
            SetChipLabelVisibility(_weaponChipNames, _weaponChipBackgrounds, !narrow);
            SetChipLabelVisibility(_supportChipNames, _supportChipBackgrounds, !narrow);
            SetChipLabelVisibility(_lateChipNames, _lateChipBackgrounds, !narrow);
        }

        private static void SetTopHudAnchor(RectTransform rect, bool narrow, float width, float y)
        {
            if (rect == null) return;
            var anchor = narrow ? new Vector2(1f, 1f) : new Vector2(0.5f, 1f);
            rect.anchorMin = anchor;
            rect.anchorMax = anchor;
            rect.pivot = narrow ? new Vector2(1f, 1f) : new Vector2(0.5f, 1f);
            rect.anchoredPosition = new Vector2(narrow ? -64f : -10f, y);
        }

        private static void ResizeOwnedChipViews(
            Image[] backgrounds,
            Text[] ranks,
            bool narrow,
            float width,
            Vector2 firstPosition,
            bool rightAligned,
            float viewportHeight)
        {
            var rows = OwnedUpgradeChipRows(viewportHeight);
            var visibleIndex = 0;
            for (var index = 0; index < backgrounds.Length; index++)
            {
                if (backgrounds[index] == null) continue;
                var chipWidth = width;
                if (narrow && backgrounds[index].enabled && ranks != null && index < ranks.Length && ranks[index] != null)
                {
                    chipWidth = BuildChipHudNarrowWidth(ranks[index].preferredWidth);
                    ConfigureOwnedUpgradeRankLayout(ranks[index], true, chipWidth - 35f);
                }
                else if (!narrow && ranks != null && index < ranks.Length && ranks[index] != null)
                {
                    ConfigureOwnedUpgradeRankLayout(ranks[index], false, 42f);
                }
                backgrounds[index].rectTransform.sizeDelta = new Vector2(chipWidth, 27f);
                var position = firstPosition;
                if (!backgrounds[index].enabled)
                {
                    backgrounds[index].rectTransform.anchoredPosition = position;
                    continue;
                }
                var column = visibleIndex / rows;
                var row = visibleIndex % rows;
                position.x += (rightAligned ? -1f : 1f) * column * (width + 5f);
                position.y -= row * 32f;
                backgrounds[index].rectTransform.anchoredPosition = position;
                visibleIndex++;
            }
        }

        private static int OwnedUpgradeChipRows(float viewportHeight)
        {
            var maxHeight = Mathf.Min(viewportHeight * 0.48f, 360f);
            return Mathf.Max(1, Mathf.FloorToInt((maxHeight + 5f) / 32f));
        }

        private static float OwnedUpgradeStripTop(bool late, float safeTopInset)
        {
            return Mathf.Max(late ? 76f : 72f, safeTopInset + (late ? 72f : 68f));
        }

        private static float BuildChipHudNarrowWidth(float rankPreferredWidth)
        {
            return 35f + Mathf.Max(13f, Mathf.Ceil(rankPreferredWidth));
        }

        private static void ConfigureOwnedUpgradeRankLayout(Text rank, bool narrow, float rankWidth)
        {
            if (rank == null) return;
            rank.rectTransform.anchoredPosition = new Vector2(narrow ? -6f : -8f, 0f);
            rank.rectTransform.sizeDelta = new Vector2(
                narrow ? Mathf.Max(13f, rankWidth) : 42f,
                rank.rectTransform.sizeDelta.y);
        }

        private static void SetChipLabelVisibility(Text[] labels, Image[] backgrounds, bool visible)
        {
            for (var index = 0; index < labels.Length; index++)
                if (labels[index] != null)
                    labels[index].enabled = visible && backgrounds[index] != null && backgrounds[index].enabled;
        }

        private string BuildLoadoutHudText()
        {
            if (_upgradeProgress == null) return string.Empty;

            var builder = new StringBuilder(320);
            builder.Append("LOADOUT  ");
            var wroteWeapon = false;
            for (var index = 0; index < Mathf.Min(ContentCatalog.Weapons.Length, _upgradeProgress.WeaponRanks.Length); index++)
            {
                var rank = _upgradeProgress.WeaponRanks[index];
                if (rank <= 0) continue;
                if (wroteWeapon) builder.Append("  ·  ");
                builder.Append(ContentCatalog.Weapons[index].Name)
                    .Append(' ')
                    .Append(rank)
                    .Append('/')
                    .Append(ContentCatalog.Weapons[index].Ranks.Length);
                if (index < _upgradeProgress.Evolved.Length && _upgradeProgress.Evolved[index]) builder.Append('+');
                wroteWeapon = true;
            }
            if (!wroteWeapon) builder.Append("none");

            builder.Append('\n').Append("SUP  ");
            var wroteSupport = false;
            for (var index = 0; index < Mathf.Min(ContentCatalog.Supports.Length, _upgradeProgress.SupportRanks.Length); index++)
            {
                var rank = _upgradeProgress.SupportRanks[index];
                if (rank <= 0) continue;
                if (wroteSupport) builder.Append("  ·  ");
                builder.Append(ContentCatalog.Supports[index].Name)
                    .Append(' ')
                    .Append(rank)
                    .Append('/')
                    .Append(ContentCatalog.Supports[index].MaxRank);
                wroteSupport = true;
            }
            if (!wroteSupport) builder.Append("none");

            builder.Append('\n').Append("LATE ");
            var wroteLate = false;
            for (var index = 0; index < Mathf.Min(ContentCatalog.LateUpgrades.Length, _upgradeProgress.LateRanks.Length); index++)
            {
                var rank = _upgradeProgress.LateRanks[index];
                if (rank <= 0) continue;
                if (wroteLate) builder.Append("  ·  ");
                builder.Append(ContentCatalog.LateUpgrades[index].Name)
                    .Append(' ')
                    .Append(rank)
                    .Append('/')
                    .Append(ContentCatalog.LateUpgrades[index].MaxRank);
                wroteLate = true;
            }
            if (!wroteLate) builder.Append("none");

            return builder.ToString();
        }

        private string BuildUpgradeStripHudText(bool late)
        {
            if (_upgradeProgress == null) return string.Empty;

            var builder = new StringBuilder(180);
            if (late)
            {
                for (var index = 0; index < Mathf.Min(ContentCatalog.LateUpgrades.Length, _upgradeProgress.LateRanks.Length); index++)
                {
                    var rank = _upgradeProgress.LateRanks[index];
                    if (rank <= 0) continue;
                    if (builder.Length > 0) builder.Append('\n');
                    builder.Append(ContentCatalog.LateUpgrades[index].Name)
                        .Append("  ")
                        .Append(rank)
                        .Append('/')
                        .Append(ContentCatalog.LateUpgrades[index].MaxRank);
                }
            }
            else
            {
                for (var index = 0; index < Mathf.Min(ContentCatalog.Supports.Length, _upgradeProgress.SupportRanks.Length); index++)
                {
                    var rank = _upgradeProgress.SupportRanks[index];
                    if (rank <= 0) continue;
                    if (builder.Length > 0) builder.Append('\n');
                    builder.Append(ContentCatalog.Supports[index].Name)
                        .Append("  ")
                        .Append(rank)
                        .Append('/')
                        .Append(ContentCatalog.Supports[index].MaxRank);
                }
            }

            return builder.ToString();
        }

        private void UpdateBuildChipHud()
        {
            for (var index = 0; index < _weaponChipBackgrounds.Length; index++)
            {
                var rank = _upgradeProgress != null && index < _upgradeProgress.WeaponRanks.Length
                    ? _upgradeProgress.WeaponRanks[index]
                    : 0;
                var evolved = _upgradeProgress != null && index < _upgradeProgress.Evolved.Length &&
                    _upgradeProgress.Evolved[index];
                var active = index < ContentCatalog.Weapons.Length && rank > 0;
                var weapon = active ? ContentCatalog.Weapons[index] : null;
                SetBuildChipView(
                    _weaponChipBackgrounds[index],
                    _weaponChipAccentBars[index],
                    _weaponChipIcons[index],
                    _weaponChipNames[index],
                    _weaponChipRanks[index],
                    active,
                    weapon == null ? string.Empty : weapon.Id,
                    active ? WeaponDisplayName(index, evolved) : string.Empty,
                    rank,
                    weapon == null ? 0 : weapon.Ranks.Length,
                    active ? ParseColor(WeaponDisplayAccent(index, evolved), new Color(0.4f, 0.9f, 1f, 1f)) : Color.white,
                    false,
                    evolved);
            }

            for (var index = 0; index < _supportChipBackgrounds.Length; index++)
            {
                var rank = _upgradeProgress != null && index < _upgradeProgress.SupportRanks.Length
                    ? _upgradeProgress.SupportRanks[index]
                    : 0;
                var active = index < ContentCatalog.Supports.Length && rank > 0;
                var support = active ? ContentCatalog.Supports[index] : null;
                SetBuildChipView(
                    _supportChipBackgrounds[index],
                    _supportChipAccentBars[index],
                    _supportChipIcons[index],
                    _supportChipNames[index],
                    _supportChipRanks[index],
                    active,
                    support == null ? string.Empty : support.Id,
                    support == null ? string.Empty : support.Name,
                    rank,
                    support == null ? 0 : support.MaxRank,
                    support == null ? Color.white : ParseColor(support.Accent, new Color(0.4f, 0.9f, 1f, 1f)),
                    true,
                    false);
            }

            for (var index = 0; index < _lateChipBackgrounds.Length; index++)
            {
                var rank = _upgradeProgress != null && index < _upgradeProgress.LateRanks.Length
                    ? _upgradeProgress.LateRanks[index]
                    : 0;
                var active = index < ContentCatalog.LateUpgrades.Length && rank > 0;
                var late = active ? ContentCatalog.LateUpgrades[index] : null;
                SetBuildChipView(
                    _lateChipBackgrounds[index],
                    _lateChipAccentBars[index],
                    _lateChipIcons[index],
                    _lateChipNames[index],
                    _lateChipRanks[index],
                    active,
                    late == null ? string.Empty : late.Id,
                    late == null ? string.Empty : late.Name,
                    rank,
                    late == null ? 0 : late.MaxRank,
                    late == null ? Color.white : ParseColor(late.Accent, new Color(0.4f, 0.9f, 1f, 1f)),
                    true,
                    false);
            }
            SetChipLabelVisibility(_weaponChipNames, _weaponChipBackgrounds, !_hudNarrow);
            SetChipLabelVisibility(_supportChipNames, _supportChipBackgrounds, !_hudNarrow);
            SetChipLabelVisibility(_lateChipNames, _lateChipBackgrounds, !_hudNarrow);
            ResizeOwnedChipViews(
                _supportChipBackgrounds,
                _supportChipRanks,
                _hudNarrow,
                _hudNarrow ? 60f : 174f,
                new Vector2(
                    Mathf.Max(12f, Screen.safeArea.xMin),
                    -OwnedUpgradeStripTop(
                        false,
                        Mathf.Max(0f, Screen.height - Screen.safeArea.yMax))),
                false,
                Screen.height);
            ResizeOwnedChipViews(
                _lateChipBackgrounds,
                _lateChipRanks,
                _hudNarrow,
                _hudNarrow ? 60f : 174f,
                new Vector2(
                    -Mathf.Max(12f, Screen.width - Screen.safeArea.xMax),
                    -OwnedUpgradeStripTop(
                        true,
                        Mathf.Max(0f, Screen.height - Screen.safeArea.yMax))),
                true,
                Screen.height);
        }

        private bool ShouldShowHud()
        {
            // React derives HUD visibility from the run phase. Main-menu
            // profile pages remain in the menu phase, even though Unity uses
            // the same runtime object to draw them; keep those pages free of
            // gameplay chrome. Pause/level-up are the only non-playing phases
            // that retain the HUD.
            return !_mainMenuBrowsing &&
                   !_gameOver &&
                   !_revivePending &&
                   (_menuPage == MenuPage.None || _paused || _levelUpActive || _levelUpTimer >= 0f);
        }

        private static void SetBuildChipView(
            Image background,
            Image accentBar,
            RawImage icon,
            Text name,
            Text rank,
            bool active,
            string id,
            string label,
            int currentRank,
            int maxRank,
            Color accent,
            bool showMaxRank,
            bool evolved)
        {
            if (background != null)
            {
                background.enabled = active;
                background.color = new Color(
                    0.02f,
                    0.035f,
                    0.063f,
                    BuildChipHudBackgroundAlpha(showMaxRank, evolved));
                var border = background.transform.Find("Chip Border")?.GetComponent<Image>();
                if (border != null)
                {
                    border.color = new Color(
                        accent.r,
                        accent.g,
                        accent.b,
                        evolved ? 0.70f : 0.35f);
                    border.enabled = BuildChipHudUsesFullBorder(active, showMaxRank);
                }
                var rankBackground = background.transform.Find("Rank Background")?.GetComponent<Image>();
                if (rankBackground != null)
                {
                    rankBackground.color = new Color(
                        accent.r,
                        accent.g,
                        accent.b,
                        evolved ? 1f : 0.13f);
                    rankBackground.enabled = active && !showMaxRank;
                }
            }
            if (accentBar != null)
            {
                accentBar.enabled = BuildChipHudUsesAccentBar(active, showMaxRank, evolved);
                accentBar.color = accent;
                accentBar.rectTransform.sizeDelta = new Vector2(
                    BuildChipHudAccentWidth(evolved),
                    Mathf.Max(11f, background == null ? 19f : background.rectTransform.sizeDelta.y - 8f));
            }
            if (icon != null)
            {
                icon.enabled = active;
                if (active)
                {
                    icon.texture = BuildChipIconTexture();
                    icon.uvRect = BuildChipIconUv(id);
                    icon.color = accent;
                    icon.rectTransform.sizeDelta = new Vector2(
                        BuildChipHudIconSize(showMaxRank),
                        BuildChipHudIconSize(showMaxRank));
                }
            }
            if (name != null)
            {
                name.enabled = active;
                if (active) name.text = label;
                name.color = BuildChipHudLabelColor(showMaxRank);
            }
            if (rank != null)
            {
                rank.enabled = active;
                if (active)
                    rank.text = showMaxRank ? $"{currentRank}/{maxRank}" : currentRank.ToString();
                rank.color = evolved ? Color.white : accent;
            }
        }

        private static bool BuildChipHudUsesFullBorder(bool active, bool showMaxRank)
        {
            return active && !showMaxRank;
        }

        private static bool BuildChipHudUsesAccentBar(bool active, bool showMaxRank, bool evolved)
        {
            return active && (showMaxRank || evolved);
        }

        private static float BuildChipHudBackgroundAlpha(bool showMaxRank, bool evolved)
        {
            if (showMaxRank) return 0.68f;
            return evolved ? 0.86f : 0.74f;
        }

        private static float BuildChipHudAccentWidth(bool evolved)
        {
            return evolved ? 3f : 2f;
        }

        private static float BuildChipHudIconSize(bool showMaxRank)
        {
            return showMaxRank ? 13f : 14f;
        }

        private static Color BuildChipHudLabelColor(bool showMaxRank)
        {
            return showMaxRank
                ? new Color(0.682f, 0.741f, 0.800f, 1f)
                : new Color(0.796f, 0.835f, 0.882f, 1f);
        }

        private void TogglePauseFromHud()
        {
            TogglePause();
        }

        private void TogglePause()
        {
            if (_revivePending || _gameOver || _levelUpActive || _menuPage != MenuPage.None) return;
            if (_paused)
            {
                _paused = false;
                RestartQualitySession();
                _audio?.Resume();
                // Browser togglePause() resumes the context and then plays the
                // gated UI cue; the pause cue is only for entering pause.
                _audio?.Play(ProceduralAudio.Cue.Ui, 1f);
            }
            else
            {
                _paused = true;
                _audio?.Play(ProceduralAudio.Cue.Pause, 0.86f);
            }
        }

        private void UpdateTouchHud()
        {
            if (_touchBaseImage == null || _touchKnobImage == null) return;
            var visible = _touchActive && !_paused && !_gameOver && !_levelUpActive && !_revivePending;
            if (!visible)
            {
                _touchBaseImage.enabled = false;
                _touchKnobImage.enabled = false;
                return;
            }

            var scale = Mathf.Clamp(_saveData?.settings?.touchSize ?? 1f, 0.75f, 1.35f);
            var radius = 64f * scale * 0.82f;
            var safeArea = Screen.safeArea;
            var safeX = Mathf.Clamp(_touchOrigin.x, safeArea.xMin + radius, safeArea.xMax - radius);
            var safeY = Mathf.Clamp(_touchOrigin.y, safeArea.yMin + radius, safeArea.yMax - radius);
            var basePosition = new Vector3(safeX, safeY, 0);
            var knobPosition = basePosition + new Vector3(
                _touchAxis.x * radius * 0.78f,
                _touchAxis.y * radius * 0.78f,
                0);
            _touchBaseImage.rectTransform.position = basePosition;
            _touchKnobImage.rectTransform.position = knobPosition;
            _touchBaseImage.rectTransform.sizeDelta = Vector2.one * (radius * 2f);
            _touchKnobImage.rectTransform.sizeDelta = Vector2.one * (radius * 0.84f);
            _touchBaseImage.enabled = true;
            _touchKnobImage.enabled = true;
        }

        private void UpdateDamageOverlays()
        {
            if (_redFlashOverlay == null || _cyanFlashOverlay == null || _amberFlashOverlay == null) return;
            var reducedMotion = _saveData?.settings != null && _saveData.settings.reducedMotion;
            var lowHealth = !_gameOver && _playerHealth > 0 && _playerHealth < _playerMaxHealth * 0.3f;
            var redAlpha = _redFlash * (reducedMotion ? 0.35f : 0.8f) +
                SourceLowHealthOverlayAlpha(lowHealth, _ambientClock);
            var cyanAlpha = reducedMotion ? 0 : _cyanFlash * 0.13f;
            var amberAlpha = _amberFlash * (reducedMotion ? 0.07f : 0.2f);
            SetFullscreenOverlay(_redFlashOverlay, Mathf.Clamp01(redAlpha));
            SetFullscreenOverlay(_cyanFlashOverlay, Mathf.Clamp01(cyanAlpha));
            SetFullscreenOverlay(_amberFlashOverlay, Mathf.Clamp01(amberAlpha));
        }

        private void CheckMilestones()
        {
            CheckKillMilestone();
            CheckScoreMilestone();
        }

        private void CheckKillMilestone()
        {
            var killCrossing = MilestoneRules.Crossed(
                MilestoneRules.KillMilestones,
                _killMilestoneIndex,
                _kills);
            _killMilestoneIndex = killCrossing.Index;
            if (killCrossing.Value.HasValue) ShowMilestoneToast("kills", killCrossing.Value.Value);
        }

        private void CheckScoreMilestone()
        {
            var scoreCrossing = MilestoneRules.Crossed(
                MilestoneRules.ScoreMilestones,
                _scoreMilestoneIndex,
                CurrentScore());
            _scoreMilestoneIndex = scoreCrossing.Index;
            if (scoreCrossing.Value.HasValue) ShowMilestoneToast("score", scoreCrossing.Value.Value);
        }

        private void RecordTelemetrySample(float frameDt)
        {
            _telemetry.RecordSample(new UnityTelemetrySample
            {
                timeSeconds = (float)_time,
                level = _level,
                hp = _playerHealth,
                maxHp = _playerMaxHealth,
                enemies = ActiveEnemies(),
                activeBosses = ActiveBosses(),
                projectiles = ActiveBullets() + ActiveHostileShots(),
                pickups = ActivePickups(),
                xpOnGround = Mathf.FloorToInt(XpOnGround()),
                xpHeldByHarvesters = XpHeldByHarvesters(),
                fps = TelemetryFpsForFrame(frameDt),
                frameMs = frameDt * 1000f,
                quality = TelemetryQualityValue(),
                hpMultiplier = EnemyHealthScaleAt((float)_time, _bossCycle, 1f),
                speedMultiplier = EnemySpeedScaleAt((float)_time, _bossCycle),
                damageMultiplier = EnemyDamageScaleAt((float)_time, _bossCycle),
                directorEvent = _nextDirectorEvent.Id,
                arenaId = ArenaIdName(_arenaId),
                arenaPhase = _arenaTransitionState.Phase.ToString(),
                activeEliteVariants = ActiveEliteVariantTotal(),
                meteors = ActiveMeteors(),
            });
        }

        private void ObserveTelemetryFrame(float frameDt)
        {
            if (_paused || _gameOver) return;
            _telemetry.ObserveFrame(
                ArenaIdName(_arenaId),
                TelemetryFpsForFrame(frameDt),
                frameDt * 1000f,
                ActiveEnemies(),
                ActiveBullets() + ActiveHostileShots(),
                ActivePickups());
        }

        private void ShowMilestoneToast(string kind, int value)
        {
            var major = MilestoneRules.IsMajor(kind, value);
            EnqueueToast($"{value:N0} {kind}", null, major ? 4f : 2.5f, ToastKind.Reward);
            _audio?.Play(major ? ProceduralAudio.Cue.MilestoneMajor : ProceduralAudio.Cue.Milestone);
            _telemetry.RecordMilestone((float)_time, kind, value);
            if (major) _cyanFlash = Mathf.Max(_cyanFlash, 0.48f);
            if (major) SpawnRingWave(_playerPosition, 18f, 470f, 0.62f, new Color(1f, 0.78f, 0.28f, 0.78f));
            BurstFx(
                _playerPosition,
                major ? SourceDotColor("yellow") : SourceDotColor("cyan"),
                major ? 14 : 7,
                major ? 260 : 170,
                major ? 0.5f : 0.32f,
                major ? 0.76f : 0.58f);
        }

        private void ShowArenaToast(string message, float seconds)
        {
            EnqueueToast(message, null, seconds, ToastKind.Info);
        }

        private void ShowArenaToast(string message, float seconds, ToastKind kind, string detail = null)
        {
            EnqueueToast(message, detail, seconds, kind);
        }

        private void EnqueueToast(string text, string detail, float seconds, ToastKind kind)
        {
            for (var index = 1; index < _toastStates.Length; index++)
                _toastStates[index - 1] = _toastStates[index];
            _toastStates[_toastStates.Length - 1] = new ToastState
            {
                Active = true,
                Text = (text ?? string.Empty).ToUpperInvariant(),
                Detail = string.IsNullOrEmpty(detail) ? null : detail.ToUpperInvariant(),
                Remaining = Mathf.Max(0.1f, seconds),
                Duration = Mathf.Max(0.1f, seconds),
                Kind = kind,
            };
        }

        private void UpdateToastTimers(float frameDt)
        {
            var write = 0;
            for (var read = 0; read < _toastStates.Length; read++)
            {
                var toast = _toastStates[read];
                if (!toast.Active) continue;
                toast.Remaining = Mathf.Max(0, toast.Remaining - frameDt);
                if (toast.Remaining <= 0) continue;
                _toastStates[write++] = toast;
            }
            while (write < _toastStates.Length)
                _toastStates[write++] = new ToastState();
        }

        private void UpdateToastViews()
        {
            var visible = _menuPage == MenuPage.None &&
                !_gameOver &&
                !_levelUpActive &&
                !_revivePending &&
                !_paused;
            var highContrast = _saveData?.settings != null && _saveData.settings.highContrast;
            for (var index = 0; index < _toastViews.Length; index++)
            {
                var view = _toastViews[index];
                if (view == null) continue;
                var toast = _toastStates[index];
                if (!visible || !toast.Active || toast.Remaining <= 0)
                {
                    view.text = string.Empty;
                    view.enabled = false;
                    view.rectTransform.localScale = Vector3.one;
                    continue;
                }

                var elapsed = Mathf.Max(0f, toast.Duration - toast.Remaining);
                var alpha = ToastAnimationAlphaAt(elapsed, toast.Duration);
                var color = highContrast ? Color.white : ToastColor(toast.Kind);
                color.a *= alpha;
                view.fontSize = ToastFontSize(Screen.width);
                var scale = ToastAnimationScaleAt(elapsed, toast.Duration);
                view.rectTransform.localScale = new Vector3(scale, scale, 1f);
                var scaleFactor = _canvas != null ? Mathf.Max(0.0001f, _canvas.scaleFactor) : 1f;
                var safeTopInset = Mathf.Max(0f, Screen.height - Screen.safeArea.yMax);
                var stackTop = ToastStackTop(Screen.height, safeTopInset) / scaleFactor;
                view.rectTransform.anchoredPosition = new Vector2(
                    0f,
                    -stackTop - index * ToastStackRowSpacing / scaleFactor +
                        ToastAnimationOffsetAt(elapsed, toast.Duration) / scaleFactor);
                view.color = color;
                if (_toastShadows[index] != null)
                {
                    _toastShadows[index].effectColor = highContrast
                        ? new Color(0f, 0f, 0f, 0.7f * alpha)
                        : new Color(color.r, color.g, color.b, 0.52f * alpha);
                }
                view.text = string.IsNullOrEmpty(toast.Detail)
                    ? toast.Text
                    : toast.Text + "\n<size=10>" + toast.Detail + "</size>";
                view.enabled = true;
            }
        }

        private void ClearToasts()
        {
            for (var index = 0; index < _toastStates.Length; index++)
            {
                _toastStates[index] = new ToastState();
                if (_toastViews[index] == null) continue;
                _toastViews[index].text = string.Empty;
                _toastViews[index].enabled = false;
            }
        }

        private static Color ToastColor(ToastKind kind)
        {
            switch (kind)
            {
                case ToastKind.Danger:
                    return new Color(0.984f, 0.443f, 0.522f, 1f);
                case ToastKind.Reward:
                    return new Color(0.431f, 0.906f, 0.702f, 1f);
                default:
                    return new Color(0.81f, 0.98f, 1f, 1f);
            }
        }

        private static int ToastQueueCapacity()
        {
            return MaxToasts;
        }

        private static float ToastStackTop(float viewportHeight, float safeTopInset)
        {
            return Mathf.Max(viewportHeight * ToastStackTopPercent, safeTopInset + ToastStackTopInset);
        }

        private static int ToastFontSize(float viewportWidth)
        {
            return Mathf.RoundToInt(Mathf.Clamp(viewportWidth * 0.03f, 17f, 24f));
        }

        private static float ToastAnimationAlphaAt(float elapsed, float duration)
        {
            if (duration <= 0f || elapsed <= 0f) return 0f;
            if (elapsed >= duration) return 0f;
            var progress = Mathf.Clamp01(elapsed / duration);
            if (progress < ToastIntroEnd)
            {
                return CubicBezierEase(progress / ToastIntroEnd, 0.22f, 1f, 0.36f, 1f);
            }
            if (progress < ToastOutroStart) return 1f;
            return 1f - CubicBezierEase(
                (progress - ToastOutroStart) / (1f - ToastOutroStart),
                0.22f,
                1f,
                0.36f,
                1f);
        }

        private static float ToastAnimationScaleAt(float elapsed, float duration)
        {
            if (duration <= 0f || elapsed <= 0f) return 0.9f;
            if (elapsed >= duration) return 0.98f;
            var progress = Mathf.Clamp01(elapsed / duration);
            if (progress < ToastIntroEnd)
            {
                return Mathf.Lerp(
                    0.9f,
                    1.04f,
                    CubicBezierEase(progress / ToastIntroEnd, 0.22f, 1f, 0.36f, 1f));
            }
            if (progress < ToastSettleEnd)
            {
                return Mathf.Lerp(
                    1.04f,
                    1f,
                    CubicBezierEase(
                        (progress - ToastIntroEnd) / (ToastSettleEnd - ToastIntroEnd),
                        0.22f,
                        1f,
                        0.36f,
                        1f));
            }
            if (progress < ToastOutroStart) return 1f;
            return Mathf.Lerp(
                1f,
                0.98f,
                CubicBezierEase(
                    (progress - ToastOutroStart) / (1f - ToastOutroStart),
                    0.22f,
                    1f,
                    0.36f,
                    1f));
        }

        private static float ToastAnimationOffsetAt(float elapsed, float duration)
        {
            if (duration <= 0f || elapsed <= 0f) return -14f;
            if (elapsed >= duration) return -8f;
            var progress = Mathf.Clamp01(elapsed / duration);
            if (progress < ToastIntroEnd)
            {
                return Mathf.Lerp(
                    -14f,
                    0f,
                    CubicBezierEase(progress / ToastIntroEnd, 0.22f, 1f, 0.36f, 1f));
            }
            if (progress < ToastOutroStart) return 0f;
            return Mathf.Lerp(
                0f,
                -8f,
                CubicBezierEase(
                    (progress - ToastOutroStart) / (1f - ToastOutroStart),
                    0.22f,
                    1f,
                    0.36f,
                    1f));
        }

        private void ToggleMenu()
        {
            if (_levelUpActive || _revivePending) return;
            if (_menuPage == MenuPage.Home) return;
            _audio?.Play(ProceduralAudio.Cue.Ui, 0.9f);
            if (_menuPage == MenuPage.None)
            {
                _menuPage = MenuPage.Main;
                _menuScroll = Vector2.zero;
                _paused = true;
            }
            else
            {
                CloseMenu();
            }
        }

        private void ToggleMute()
        {
            if (_audio == null) return;
            _audio.SetMuted(!_audio.Muted);
            _audio.Play(ProceduralAudio.Cue.Ui, _audio.Muted ? 0.86f : 1.02f);
            SetMenuNotice(_audio.Muted ? "Audio muted." : "Audio unmuted.");
        }

        private void CloseMenu()
        {
            CommitSettings();
            if (_mainMenuBrowsing)
            {
                _menuPage = MenuPage.Home;
                _menuScroll = Vector2.zero;
                _paused = true;
                return;
            }
            _menuPage = MenuPage.None;
            if (!_gameOver) _paused = false;
            if (!_gameOver) RestartQualitySession();
        }

        private bool CommitSettings()
        {
            if (!_settingsDirty) return true;
            if (_saveStore == null || _saveData == null)
            {
                SetMenuNotice("Settings could not be saved");
                return false;
            }

            try
            {
                _saveData = SaveStore.Sanitize(_saveData);
                _saveStore.Save(_saveData);
                _settingsDirty = false;
                return true;
            }
            catch (Exception exception)
            {
                Debug.LogWarning("VoidFall settings could not be saved: " + exception.Message);
                SetMenuNotice("Settings could not be saved");
                return false;
            }
        }

        private void ApplySettings()
        {
            var settings = _saveData?.settings;
            if (settings == null) return;
            var qualityMode = string.IsNullOrEmpty(settings.quality) ? "high" : settings.quality;
            if (_qualityController == null || _qualityModeApplied != qualityMode)
            {
                _qualityAuto = qualityMode == "auto";
                var startQuality = _qualityAuto
                    ? QualityRules.RecommendedInitialQuality(
                        Application.isMobilePlatform || Input.touchSupported,
                        Screen.width)
                    : QualityRules.FromName(qualityMode);
                _qualityController = new AdaptiveQualityController(startQuality);
                _qualityModeApplied = qualityMode;
                RestartQualitySession();
            }
            ApplyQualityPreset(_qualityController.CurrentPreset);
            // ProceduralAudio owns the browser-equivalent master/effects/music
            // gains; keep the global listener neutral so master is not applied
            // twice to every generated clip.
            AudioListener.volume = 1f;
            _audio?.SetVolumes(settings.masterVolume, settings.effectsVolume, settings.musicVolume);
            switch (qualityMode)
            {
                case "low":
                    QualitySettings.vSyncCount = 0;
                    Application.targetFrameRate = 45;
                    break;
                case "balanced":
                    QualitySettings.vSyncCount = 0;
                    Application.targetFrameRate = 60;
                    break;
                case "auto":
                    QualitySettings.vSyncCount = 1;
                    Application.targetFrameRate = -1;
                    break;
                default:
                    QualitySettings.vSyncCount = 1;
                    Application.targetFrameRate = 60;
                    break;
            }
        }

        private void ApplyQualityPreset(QualityPreset preset)
        {
            _qualityPreset = preset;
            ApplyRenderResolution();
            var particleLimit = SourceParticleLimit(preset.ParticleScale);
            if (_fx != null)
            {
                var main = _fx.main;
                main.maxParticles = particleLimit;
            }
            TrimCosmeticBudgets(particleLimit, preset.FloaterScale, preset.DeathGhosts);
        }

        private void TrimCosmeticBudgets(int particleLimit, float floaterScale, bool keepDeathGhosts)
        {
            // The browser drops the newest cosmetic entries immediately when a
            // lower quality tier takes effect. Unity keeps some of those views
            // outside its ParticleSystem, so trim the shared visual budget and
            // the pooled floater/ghost arrays explicitly as well.
            if (_fx != null)
            {
                var particleCount = _fx.GetParticles(_fxParticleScratch);
                if (particleCount > particleLimit)
                    _fx.SetParticles(_fxParticleScratch, particleLimit);
                TrimSourceParticleViews(_fx.particleCount);
            }

            while (ActiveFxVisualCount() > particleLimit)
            {
                var removed = false;
                for (var index = _ringWaves.Length - 1; index >= 0; index--)
                {
                    if (!_ringWaves[index].Active) continue;
                    var wave = _ringWaves[index];
                    wave.Active = false;
                    _ringWaves[index] = wave;
                    RemoveSourceFxOrder(SourceFxKind.RingWave, index);
                    Hide(_ringWaveViews[index]);
                    Hide(_ringWaveGlowViews[index]);
                    Hide(_ringWaveSpriteViews[index]);
                    removed = true;
                    break;
                }
                if (removed) continue;

                for (var index = _meteorShards.Length - 1; index >= 0; index--)
                {
                    if (!_meteorShards[index].Active) continue;
                    var shard = _meteorShards[index];
                    shard.Active = false;
                    _meteorShards[index] = shard;
                    RemoveSourceFxOrder(SourceFxKind.MeteorShard, index);
                    Hide(_meteorShardViews[index]);
                    removed = true;
                    break;
                }
                if (!removed) break;
            }

            var floaterLimit = Mathf.Max(8, Mathf.RoundToInt(MaxFloaters * floaterScale));
            var activeFloaters = 0;
            for (var index = 0; index < _floaters.Length; index++)
                if (_floaters[index].Active) activeFloaters++;
            for (var index = _floaters.Length - 1; index >= 0 && activeFloaters > floaterLimit; index--)
            {
                if (!_floaters[index].Active) continue;
                var floater = _floaters[index];
                floater.Active = false;
                _floaters[index] = floater;
                RemoveFloaterOrder(index);
                Hide(_floaterViews[index]);
                activeFloaters--;
            }

            if (!keepDeathGhosts)
            {
                for (var index = 0; index < _deathGhosts.Length; index++)
                {
                    if (!_deathGhosts[index].Active) continue;
                    var ghost = _deathGhosts[index];
                    ghost.Active = false;
                    _deathGhosts[index] = ghost;
                    RemoveDeathGhostOrder(index);
                    Hide(_deathGhostViews[index]);
                }
            }
        }

        private static int SourceParticleLimit(float particleScale)
        {
            return Mathf.Max(24, Mathf.RoundToInt(MaxSourceParticles * Mathf.Max(0, particleScale)));
        }

        private int ActiveFxVisualCount()
        {
            var count = _fx == null ? 0 : _fx.particleCount;
            for (var index = 0; index < _ringWaves.Length; index++)
                if (_ringWaves[index].Active) count++;
            for (var index = 0; index < _meteorShards.Length; index++)
                if (_meteorShards[index].Active) count++;
            return count;
        }

        private void TrimSourceParticleViews(int maximum)
        {
            var active = 0;
            for (var index = 0; index < _sourceParticles.Length; index++)
                if (_sourceParticles[index].Active) active++;
            for (var order = _sourceFxOrderCount - 1; order >= 0 && active > maximum; order--)
            {
                if ((SourceFxKind)_sourceFxOrderKind[order] != SourceFxKind.Particle) continue;
                var slot = _sourceFxOrderSlot[order];
                if (slot < 0 || slot >= _sourceParticles.Length || !_sourceParticles[slot].Active) continue;
                var particle = _sourceParticles[slot];
                particle.Active = false;
                _sourceParticles[slot] = particle;
                RemoveSourceFxOrder(SourceFxKind.Particle, slot);
                Hide(_sourceParticleViews[slot]);
                active--;
            }
        }

        private void ApplyRenderResolution()
        {
            if (_camera == null || Screen.width <= 0 || Screen.height <= 0) return;
            UpdateGameplayCameraViewport();
            var dpi = Mathf.Max(0, Screen.dpi);
            var dpiKey = Mathf.RoundToInt(dpi * 10f);
            var scale = QualityRules.EffectiveRenderScale(
                Screen.width,
                Screen.height,
                dpi,
                _qualityPreset);
            if (Screen.width == _renderResolutionWidth &&
                Screen.height == _renderResolutionHeight &&
                dpiKey == _renderResolutionDpi &&
                _renderScaleApplied >= 0 &&
                Mathf.Abs(_renderScaleApplied - scale) < 0.0005f &&
                _worldRenderTarget != null &&
                _worldRenderTargetWidth == Mathf.Max(1, Mathf.RoundToInt(Screen.width * scale)) &&
                _worldRenderTargetHeight == Mathf.Max(1, Mathf.RoundToInt(Screen.height * scale)) &&
                _camera.targetTexture == _worldRenderTarget &&
                _worldRenderView != null &&
                _worldRenderView.texture == _worldRenderTarget)
            {
                return;
            }

            var dpiChanged = dpiKey != _renderResolutionDpi;
            _qualityController?.BeginSettle();
            if (dpiChanged) RestartQualitySession();

            _camera.allowDynamicResolution = true;
            ScalableBufferManager.ResizeBuffers(scale, scale);
            EnsureWorldRenderTarget(scale);
            _renderResolutionWidth = Screen.width;
            _renderResolutionHeight = Screen.height;
            _renderResolutionDpi = dpiKey;
            _renderScaleApplied = scale;
        }

        private void EnsureWorldRenderTarget(float scale)
        {
            if (_camera == null || Screen.width <= 0 || Screen.height <= 0) return;
            if (UnityEngine.Rendering.GraphicsDeviceType.Null == SystemInfo.graphicsDeviceType ||
                !SystemInfo.supportsRenderTextures)
            {
                ReleaseWorldRenderTarget();
                return;
            }

            var targetWidth = Mathf.Max(1, Mathf.RoundToInt(Screen.width * scale));
            var targetHeight = Mathf.Max(1, Mathf.RoundToInt(Screen.height * scale));
            if (_worldRenderTarget != null &&
                _worldRenderTargetWidth == targetWidth &&
                _worldRenderTargetHeight == targetHeight &&
                _camera.targetTexture == _worldRenderTarget &&
                _worldRenderView != null &&
                _worldRenderView.texture == _worldRenderTarget)
            {
                return;
            }

            ReleaseWorldRenderTarget();
            _worldRenderTarget = new RenderTexture(
                targetWidth,
                targetHeight,
                24,
                RenderTextureFormat.ARGB32,
                RenderTextureReadWrite.sRGB)
            {
                name = "VoidFall Dynamic World Target",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
                useMipMap = false,
                autoGenerateMips = false
            };
            _worldRenderTarget.Create();
            _worldRenderTargetWidth = targetWidth;
            _worldRenderTargetHeight = targetHeight;
            _camera.targetTexture = _worldRenderTarget;
            _camera.aspect = targetWidth / (float)targetHeight;
            if (_worldRenderView != null)
            {
                _worldRenderView.texture = _worldRenderTarget;
                _worldRenderView.enabled = true;
            }
        }

        private void ReleaseWorldRenderTarget()
        {
            if (_camera != null && _camera.targetTexture == _worldRenderTarget)
                _camera.targetTexture = null;
            if (_worldRenderView != null && _worldRenderView.texture == _worldRenderTarget)
                _worldRenderView.texture = null;
            if (_worldRenderTarget == null) return;
            _worldRenderTarget.Release();
            Destroy(_worldRenderTarget);
            _worldRenderTarget = null;
            _worldRenderTargetWidth = 0;
            _worldRenderTargetHeight = 0;
        }

        private void SetMenuNotice(string message)
        {
            _menuNotice = message;
            _menuNoticeTimer = 3f;
        }

        private string ActiveOverlayAnimationKey()
        {
            if (_revivePending) return "revive";
            if (_levelUpActive) return null;
            if (_gameOver && _menuPage == MenuPage.None) return "gameover";
            if (_paused && _menuPage == MenuPage.None) return "pause";
            return null;
        }

        private void SyncOverlayAnimation()
        {
            var key = ActiveOverlayAnimationKey();
            if (string.Equals(key, _overlayAnimationKey, StringComparison.Ordinal)) return;
            _overlayAnimationKey = key;
            _overlayAnimationOpenedAt = string.IsNullOrEmpty(key) ? -1f : Time.realtimeSinceStartup;
        }

        private float CurrentOverlayFadeAlpha()
        {
            if (string.IsNullOrEmpty(_overlayAnimationKey)) return 1f;
            return OverlayFadeAlphaAt(Time.realtimeSinceStartup - _overlayAnimationOpenedAt);
        }

        private float CurrentOverlayCardAlpha()
        {
            if (string.IsNullOrEmpty(_overlayAnimationKey)) return 1f;
            return OverlayCardAlphaAt(Time.realtimeSinceStartup - _overlayAnimationOpenedAt);
        }

        private float CurrentOverlayCardOffset()
        {
            if (string.IsNullOrEmpty(_overlayAnimationKey)) return 0f;
            return OverlayCardRiseOffsetAt(Time.realtimeSinceStartup - _overlayAnimationOpenedAt);
        }

        private static float OverlayFadeAlphaAt(float elapsed)
        {
            if (elapsed <= 0f) return 0f;
            if (elapsed >= OverlayFadeSeconds) return 1f;
            var progress = Mathf.Clamp01(elapsed / OverlayFadeSeconds);
            return CubicBezierEase(progress, 0.25f, 0.1f, 0.25f, 1f);
        }

        private static float OverlayCardAlphaAt(float elapsed)
        {
            if (elapsed <= 0f) return 0f;
            if (elapsed >= OverlayCardRiseSeconds) return 1f;
            var progress = Mathf.Clamp01(elapsed / OverlayCardRiseSeconds);
            return CubicBezierEase(progress, 0.22f, 1f, 0.36f, 1f);
        }

        private static float OverlayCardRiseOffsetAt(float elapsed)
        {
            return OverlayCardRiseOffset * (1f - OverlayCardAlphaAt(elapsed));
        }

        private void SyncMainMenuAnimation()
        {
            if (_menuPage == MenuPage.Home)
            {
                if (_mainMenuAnimationOpenedAt < 0f)
                    _mainMenuAnimationOpenedAt = Time.realtimeSinceStartup;
                return;
            }
            _mainMenuAnimationOpenedAt = -1f;
        }

        private float CurrentMainMenuAlpha()
        {
            if (_mainMenuAnimationOpenedAt < 0f) return 1f;
            return MainMenuAlphaAt(Time.realtimeSinceStartup - _mainMenuAnimationOpenedAt);
        }

        private static float MainMenuAlphaAt(float elapsed)
        {
            if (elapsed <= 0f) return 0f;
            if (elapsed >= 0.30f) return 1f;
            return CubicBezierEase(elapsed / 0.30f, 0.25f, 0.1f, 0.25f, 1f);
        }

        private void OnGUI()
        {
            if (_menuSkin == null)
            {
                _menuSkin = CreateMenuSkin(GUI.skin);
            }
            if (_menuSkin != null)
            {
                GUI.skin = _menuSkin;
            }

            if (_menuPage == MenuPage.Home)
            {
                DrawHomeBackdrop();
            }

            DrawMuteControl();

            SyncOverlayAnimation();
            SyncMainMenuAnimation();

            if (_evolutionRevealTimer > 0 && _menuPage == MenuPage.None &&
                !_gameOver && !_levelUpActive && !_revivePending)
            {
                DrawEvolutionReveal();
            }

            if (_menuPage == MenuPage.Home)
            {
                DrawMainMenu();
                DrawDebugOverlay();
                return;
            }

            if (_revivePending)
            {
                DrawRevivePrompt();
                DrawDebugOverlay();
                return;
            }
            if (_levelUpActive)
            {
                DrawLevelUpPrompt();
                DrawDebugOverlay();
                return;
            }
            if (_gameOver && _menuPage == MenuPage.None)
            {
                DrawGameOverOverlay();
                DrawDebugOverlay();
                return;
            }
            if (_paused && _menuPage == MenuPage.None)
            {
                DrawPausePrompt();
                DrawDebugOverlay();
                return;
            }
            if (_menuPage == MenuPage.None)
            {
                DrawScreenWarnings();
                DrawDebugOverlay();
                return;
            }

            var oldColor = GUI.color;
            var safeArea = Screen.safeArea;
            var width = MenuPanelWidth(safeArea.width, _menuPage);
            var height = MenuPanelMaxHeight(safeArea.height);
            var x = safeArea.xMin + (safeArea.width - width) * 0.5f;
            var y = safeArea.yMin + (safeArea.height - height) * 0.5f;
            var menuAlpha = CurrentMainMenuAlpha();
            DrawOverlayCardBackdropBlur(new Rect(x, y, width, height), menuAlpha);
            DrawOverlayCardShadow(new Rect(x, y, width, height), menuAlpha);
            GUI.color = Color.white;
            GUI.Box(new Rect(x, y, width, height), GUIContent.none);
            var insetRect = MenuPanelInsetHighlightRect(x, y, width);
            GUI.color = new Color(1f, 1f, 1f, 0.05f);
            GUI.DrawTexture(
                insetRect,
                Texture2D.whiteTexture,
                ScaleMode.StretchToFill,
                true);
            var accentRect = MenuPanelAccentRect(x, y, width);
            GUI.color = new Color(0.133f, 0.827f, 0.933f, 0.16f);
            GUI.DrawTexture(
                new Rect(accentRect.x, accentRect.y, accentRect.width, 6f),
                Texture2D.whiteTexture,
                ScaleMode.StretchToFill,
                true);
            GUI.color = new Color(0.133f, 0.827f, 0.933f, 1f);
            GUI.DrawTexture(accentRect, Texture2D.whiteTexture, ScaleMode.StretchToFill, true);
            GUI.color = Color.white;

            var profilePage = ProfilePageHeaderVisible(_mainMenuBrowsing, _menuPage);
            var contentInset = profilePage ? 22f : 24f;
            var contentTopInset = profilePage ? 22f : 18f;
            GUILayout.BeginArea(new Rect(
                x + contentInset,
                y + contentTopInset,
                width - contentInset * 2f,
                height - contentTopInset - (profilePage ? 22f : 18f)));
            if (profilePage)
            {
                DrawProfilePageHeader();
            }
            else
            {
                GUILayout.Label("VOIDFALL // " + MenuPageName(), MenuTitleStyle());
                GUILayout.Label(
                    _mainMenuBrowsing
                        ? "Local profile. Changes are saved immediately."
                        : _gameOver
                        ? "Run ended. Press R or choose New run to launch again."
                        : "Run paused. Changes to the workshop apply on the next run.",
                    MenuBodyStyle());

                var compactMenu = width < 560f;
                var navigationHeight = compactMenu ? 36f : 30f;
                GUILayout.BeginHorizontal();
                if (_mainMenuBrowsing)
                {
                    if (DrawIconTextButton("Main menu", "arrow-left", navigationHeight)) _menuPage = MenuPage.Home;
                    if (DrawIconTextButton("Workshop", "wrench", navigationHeight, true)) _menuPage = MenuPage.Workshop;
                    if (!compactMenu)
                    {
                        if (DrawIconTextButton("Records", "trophy", navigationHeight, true)) _menuPage = MenuPage.Records;
                        if (DrawIconTextButton("Settings", "settings", navigationHeight, true)) _menuPage = MenuPage.Settings;
                    }
                }
                else
                {
                    if (DrawIconTextButton("Resume", "play", navigationHeight)) CloseMenu();
                    if (GUILayout.Button("Overview", GUILayout.Height(navigationHeight))) _menuPage = MenuPage.Main;
                    if (DrawIconTextButton("Workshop", "wrench", navigationHeight, true)) _menuPage = MenuPage.Workshop;
                    if (!compactMenu)
                    {
                        if (DrawIconTextButton("Records", "trophy", navigationHeight, true)) _menuPage = MenuPage.Records;
                        if (DrawIconTextButton("Settings", "settings", navigationHeight, true)) _menuPage = MenuPage.Settings;
                    }
                }
                GUILayout.EndHorizontal();
                if (compactMenu)
                {
                    GUILayout.BeginHorizontal();
                    if (DrawIconTextButton("Records", "trophy", navigationHeight, true)) _menuPage = MenuPage.Records;
                    if (DrawIconTextButton("Settings", "settings", navigationHeight, true)) _menuPage = MenuPage.Settings;
                    GUILayout.EndHorizontal();
                }
                if (!_mainMenuBrowsing)
                {
                    GUILayout.BeginHorizontal();
                    if (DrawIconTextButton("Restart", "rotate-ccw", navigationHeight)) StartRun();
                    if (DrawIconTextButton("Main menu", "house", navigationHeight)) EnterMainMenu();
                    GUILayout.EndHorizontal();
                }
            }

            if (_menuNoticeTimer > 0 && !string.IsNullOrEmpty(_menuNotice))
                GUILayout.Label(_menuNotice, MenuSectionStyle());

            _menuScroll = GUILayout.BeginScrollView(
                _menuScroll,
                GUIStyle.none,
                GUI.skin.verticalScrollbar,
                GUILayout.ExpandHeight(true));
            switch (_menuPage)
            {
                case MenuPage.Workshop:
                    DrawWorkshopMenu();
                    break;
                case MenuPage.Records:
                    DrawRecordsMenu();
                    break;
                case MenuPage.Settings:
                    DrawSettingsMenu();
                    break;
                default:
                    DrawOverviewMenu();
                    break;
            }
            GUILayout.EndScrollView();
            GUILayout.EndArea();
            GUI.color = oldColor;
            DrawDebugOverlay();
        }

        private static bool RusherWarningVisible(
            bool playing,
            bool directorWarned,
            bool directorActive,
            string eventId)
        {
            // The browser keeps the warning visible through the active rusher
            // stream, but only while the run is actually playing.
            return playing && directorWarned && eventId == "rushers";
        }

        private static bool PressureBorderVisible(
            bool playing,
            bool directorWarned,
            bool directorActive,
            string eventId)
        {
            if (!playing || !directorWarned) return false;
            return eventId == "swarm" || eventId == "encircle";
        }

        private static Texture2D RusherChevronTexture()
        {
            if (_rusherChevronTexture != null) return _rusherChevronTexture;

            const int width = 40;
            const int height = 20;
            _rusherChevronTexture = new Texture2D(width, height, TextureFormat.RGBA32, false)
            {
                name = "VoidFall Rusher Chevrons",
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
            };
            var pixels = new Color[width * height];
            var first = new[]
            {
                new Vector2(20f, 10f),
                new Vector2(6f, 1f),
                new Vector2(6f, 19f),
            };
            var second = new[]
            {
                new Vector2(33f, 10f),
                new Vector2(19f, 1f),
                new Vector2(19f, 19f),
            };
            for (var y = 0; y < height; y++)
            {
                for (var x = 0; x < width; x++)
                {
                    var point = new Vector2(x + 0.5f, y + 0.5f);
                    if (PointInTriangle(point, first) || PointInTriangle(point, second))
                        pixels[y * width + x] = Color.white;
                }
            }
            _rusherChevronTexture.SetPixels(pixels);
            _rusherChevronTexture.Apply(false, true);
            return _rusherChevronTexture;
        }

        private static bool PointInTriangle(Vector2 point, Vector2[] triangle)
        {
            var a = triangle[0];
            var b = triangle[1];
            var c = triangle[2];
            var ab = Cross(b - a, point - a);
            var bc = Cross(c - b, point - b);
            var ca = Cross(a - c, point - c);
            return (ab >= 0 && bc >= 0 && ca >= 0) ||
                (ab <= 0 && bc <= 0 && ca <= 0);
        }

        private static float Cross(Vector2 left, Vector2 right)
        {
            return left.x * right.y - left.y * right.x;
        }

        private void DrawScreenWarnings()
        {
            if (Event.current == null || Event.current.type != EventType.Repaint) return;
            var playing = _menuPage == MenuPage.None && !_paused && !_gameOver &&
                !_levelUpActive && !_revivePending;
            if (!playing) return;

            var eventId = _nextDirectorEvent.Id;
            var oldColor = GUI.color;
            var oldMatrix = GUI.matrix;
            var width = Screen.width;
            var height = Screen.height;

            if (RusherWarningVisible(playing, _directorWarned, _directorActive, eventId))
            {
                var pulse = (0.4f + 0.3f * Mathf.Sin(_ambientClock * 9f)) * 0.35f;
                GUI.color = new Color(0.984f, 0.443f, 0.545f, pulse);
                var texture = RusherChevronTexture();
                var edge = _nextDirectorEvent.SpawnEdge;
                for (var index = 0; index < 5; index++)
                {
                    var t = (index + 1f) / 6f;
                    var x = 0f;
                    var y = 0f;
                    var angle = 0f;
                    if (edge == 0)
                    {
                        x = width * t;
                        y = 26f;
                        angle = 90f;
                    }
                    else if (edge == 1)
                    {
                        x = width * t;
                        y = height - 26f;
                        angle = -90f;
                    }
                    else if (edge == 2)
                    {
                        x = 26f;
                        y = height * t;
                    }
                    else
                    {
                        x = width - 26f;
                        y = height * t;
                        angle = 180f;
                    }

                    var centre = new Vector2(x, y);
                    GUI.matrix = oldMatrix;
                    GUIUtility.RotateAroundPivot(angle, centre);
                    GUI.DrawTexture(new Rect(x - 20f, y - 10f, 40f, 20f), texture, ScaleMode.StretchToFill, true);
                }
            }

            if (PressureBorderVisible(playing, _directorWarned, _directorActive, eventId))
            {
                var pulse = 0.05f + 0.04f * Mathf.Sin(_ambientClock * 7f);
                GUI.matrix = oldMatrix;
                GUI.color = new Color(0.984f, 0.443f, 0.545f, pulse);
                GUI.DrawTexture(new Rect(0f, 0f, width, 3f), Texture2D.whiteTexture);
                GUI.DrawTexture(new Rect(0f, height - 3f, width, 3f), Texture2D.whiteTexture);
                GUI.DrawTexture(new Rect(0f, 0f, 3f, height), Texture2D.whiteTexture);
                GUI.DrawTexture(new Rect(width - 3f, 0f, 3f, height), Texture2D.whiteTexture);
            }

            GUI.matrix = oldMatrix;
            GUI.color = oldColor;
        }

        private void DrawDebugOverlay()
        {
            if (!_debugOverlay) return;

            if (_debugReadoutStyle == null)
            {
                _debugReadoutStyle = new GUIStyle(GUI.skin.label)
                {
                    font = BrowserBodyFont(),
                    fontSize = 10,
                    alignment = TextAnchor.MiddleLeft,
                    wordWrap = false,
                    padding = new RectOffset(0, 0, 0, 0),
                };
                _debugReadoutStyle.normal.textColor = new Color(0.525f, 0.937f, 0.611f, 1f);
            }
            if (_debugButtonStyle == null)
            {
                _debugButtonStyle = new GUIStyle(GUI.skin.button)
                {
                    font = BrowserBodyFont(),
                    fontSize = 10,
                    alignment = TextAnchor.MiddleCenter,
                    padding = new RectOffset(6, 6, 4, 4),
                };
                _debugButtonStyle.normal.textColor = new Color(0.733f, 0.969f, 0.816f, 1f);
            }

            var safeArea = Screen.safeArea;
            var width = 252f;
            var height = 252f;
            var x = Mathf.Max(12f, safeArea.xMin + 12f);
            var y = Mathf.Max(120f, safeArea.yMin + 110f);
            var oldColor = GUI.color;
            GUI.color = new Color(0.008f, 0.024f, 0.047f, 0.86f);
            GUI.Box(new Rect(x, y, width, height), GUIContent.none);
            GUI.color = Color.white;

            GUILayout.BeginArea(new Rect(x + 8f, y + 7f, width - 16f, height - 14f));
            var fps = Mathf.RoundToInt(1000f / Mathf.Max(0.1f, _debugFrameEmaMs));
            var cycle = ArenaCycleRules.At(ArenaIdName(_arenaId), _time);
            var lines = new[]
            {
                $"FPS {fps}  {_debugFrameEmaMs:0.0} ms",
                $"Enemies {ActiveEnemies()}/{MaxEnemies}  Bosses {ActiveBosses()}",
                $"Shots {ActiveBullets() + ActiveHostileShots()}",
                $"Particles {(_fx != null ? _fx.particleCount : 0)}",
                $"Pickups {ActivePickups()}",
                $"Quality {_qualityPreset.Detail:0}",
                $"Seed {_runSeed}",
                $"RNG {_rng.Draws}/{_fxRng.Draws}",
                $"Boss cycle {_bossSequence}",
                $"Arena {ArenaName(_arenaId)} · {cycle.CycleId}",
                $"Shift {_arenaTransitionState.Phase} in {Mathf.Max(0f, (float)(_arenaTransitionState.DueAt - _time)):0}s",
                $"Meteors {ActiveMeteors()}  Elites {ActiveEliteVariantTotal()}  R2 {ActiveRosterTwoTotal()}",
            };
            foreach (var line in lines) GUILayout.Label(line, _debugReadoutStyle, GUILayout.Height(14f));
            if (GUILayout.Button("Export run data  [F2]", _debugButtonStyle, GUILayout.Height(24f)))
                ExportTelemetrySnapshot(_gameOver ? "gameover" : "active");
            GUILayout.EndArea();
            GUI.color = oldColor;
        }

        private void DrawMuteControl()
        {
            var safeArea = Screen.safeArea;
            const float size = 44f;
            var rect = new Rect(
                safeArea.xMax - size - 14f,
                safeArea.yMax - size - 14f,
                size,
                size);
            if (_muteButtonStyle == null)
            {
                _muteButtonStyle = new GUIStyle(GUI.skin.button)
                {
                    font = BrowserDisplayFont(),
                    fontSize = 17,
                    alignment = TextAnchor.MiddleCenter,
                    padding = new RectOffset(0, 0, 0, 0),
                };
            }

            var muted = _audio != null && _audio.Muted;
            var oldColor = GUI.color;
            GUI.color = new Color(1f, 1f, 1f, 0.96f);
            var clicked = GUI.Button(rect, GUIContent.none, _muteButtonStyle);
            if (ControlIconTexture() != null)
            {
                DrawControlIcon(
                    new Rect(rect.x + 11f, rect.y + 11f, 22f, 22f),
                    muted ? "volume-x" : "volume-2",
                    new Color(0.8f, 0.94f, 0.98f, 1f));
            }
            else
            {
                GUI.Label(rect, muted ? "\u2715" : "\u266b", _muteButtonStyle);
            }
            if (clicked)
            {
                ToggleMute();
            }
            GUI.color = oldColor;
        }

        private void DrawEvolutionReveal()
        {
            var safeArea = Screen.safeArea;
            var elapsedSeconds = Mathf.Clamp(
                EvolutionRevealDuration() - _evolutionRevealTimer,
                0f,
                EvolutionRevealDuration());
            var alpha = EvolutionRevealOpacity(elapsedSeconds);
            var scale = EvolutionRevealScale(elapsedSeconds);
            var center = safeArea.center;
            var accent = new Color(
                _evolutionRevealAccent.r,
                _evolutionRevealAccent.g,
                _evolutionRevealAccent.b,
                alpha);
            var oldColor = GUI.color;

            if (_evolutionRevealKickerStyle == null)
            {
                _evolutionRevealKickerStyle = new GUIStyle(MenuBodyStyle())
                {
                    alignment = TextAnchor.MiddleCenter,
                    fontStyle = FontStyle.Bold,
                    fontSize = 12,
                };
                _evolutionRevealPreviousStyle = new GUIStyle(MenuBodyStyle())
                {
                    alignment = TextAnchor.MiddleCenter,
                    fontStyle = FontStyle.Bold,
                    fontSize = 13,
                };
                _evolutionRevealTitleStyle = new GUIStyle(MenuTitleStyle())
                {
                    alignment = TextAnchor.MiddleCenter,
                    fontSize = EvolutionRevealTitleFontSize(safeArea.width),
                    wordWrap = false,
                };
                _evolutionRevealTitleGlowStyle = new GUIStyle(_evolutionRevealTitleStyle)
                {
                    alignment = TextAnchor.MiddleCenter,
                    wordWrap = false,
                };
                _evolutionRevealTitleGlowStyle.normal.background = null;
                _evolutionRevealTitleGlowStyle.hover.background = null;
            }
            _evolutionRevealTitleStyle.fontSize = EvolutionRevealTitleFontSize(safeArea.width);
            _evolutionRevealTitleGlowStyle.fontSize = _evolutionRevealTitleStyle.fontSize;
            _evolutionRevealKickerStyle.normal.textColor = accent;
            _evolutionRevealPreviousStyle.normal.textColor = new Color(0.58f, 0.64f, 0.72f, alpha);
            _evolutionRevealTitleStyle.normal.textColor = new Color(0.97f, 0.98f, 1f, alpha);

            var markSize = 78f * scale;
            var markRect = new Rect(center.x - markSize * 0.5f, center.y - 116f * scale,
                markSize, markSize);
            var lineWidth = Mathf.Min(safeArea.width * 0.70f, 620f) * scale;
            var lineHeight = EvolutionRevealCrossLineLength(safeArea.width) * scale;
            GUI.color = new Color(1f, 1f, 1f, alpha * 0.7f);
            var crossLineTexture = EvolutionCrossLineTexture(_evolutionRevealAccent);
            GUI.DrawTexture(
                new Rect(center.x - lineWidth * 0.5f, center.y - 2f, lineWidth, 1f),
                crossLineTexture,
                ScaleMode.StretchToFill,
                true);
            var crossLineMatrix = GUI.matrix;
            GUIUtility.RotateAroundPivot(90f, center);
            GUI.DrawTexture(
                new Rect(center.x - lineHeight * 0.5f, center.y - 0.5f, lineHeight, 1f),
                crossLineTexture,
                ScaleMode.StretchToFill,
                true);
            GUI.matrix = crossLineMatrix;
            GUI.color = new Color(1f, 1f, 1f, alpha);
            // Browser `.evolution-mark` rotates as a badge; restore the IMGUI
            // matrix before drawing the centered text below it.
            var revealMatrix = GUI.matrix;
            GUIUtility.RotateAroundPivot(-8f, markRect.center);
            var haloSize = 150f * scale;
            GUI.DrawTexture(
                new Rect(markRect.center.x - haloSize * 0.5f, markRect.center.y - haloSize * 0.5f, haloSize, haloSize),
                EvolutionMarkGlowTexture(_evolutionRevealAccent),
                ScaleMode.StretchToFill,
                true);
            var ringSize = 94f * scale;
            GUI.DrawTexture(
                new Rect(markRect.center.x - ringSize * 0.5f, markRect.center.y - ringSize * 0.5f, ringSize, ringSize),
                EvolutionMarkRingTexture(_evolutionRevealAccent),
                ScaleMode.StretchToFill,
                true);
            GUI.Box(markRect, GUIContent.none, EvolutionMarkStyle(_evolutionRevealAccent));
            GUI.matrix = revealMatrix;
            GUI.color = accent;
            var iconTexture = BuildChipIconTexture();
            var iconSlot = BuildChipIconSlot(_evolutionRevealWeaponId);
            var iconMatrix = GUI.matrix;
            GUIUtility.RotateAroundPivot(8f, markRect.center);
            if (iconTexture != null && iconSlot >= 0)
            {
                var iconSize = 34f * scale;
                GUI.DrawTextureWithTexCoords(
                    new Rect(
                        center.x - iconSize * 0.5f,
                        markRect.center.y - iconSize * 0.5f,
                        iconSize,
                        iconSize),
                    iconTexture,
                    BuildChipIconUv(_evolutionRevealWeaponId),
                    true);
            }
            else
            {
                GUI.Label(markRect, "\u25c7", _evolutionRevealTitleStyle);
            }
            GUI.matrix = iconMatrix;

            var labelWidth = Mathf.Min(safeArea.width - 40f, 640f);
            var kickerRect = new Rect(
                center.x - labelWidth * 0.5f,
                center.y - 34f * scale,
                labelWidth,
                26f);
            var previousRect = new Rect(
                center.x - labelWidth * 0.5f,
                center.y + 4f * scale,
                labelWidth,
                28f);
            var titleRect = new Rect(
                center.x - labelWidth * 0.5f,
                center.y + 30f * scale,
                labelWidth,
                58f);
            DrawEvolutionTextBand(kickerRect, alpha);
            DrawEvolutionTextBand(previousRect, alpha);
            DrawEvolutionTextBand(titleRect, alpha);
            GUI.color = Color.white;
            var titleText = (_evolutionRevealName ?? string.Empty).ToUpperInvariant();
            var introBlur = EvolutionRevealIntroBlur(elapsedSeconds);
            if (introBlur > 0.01f)
            {
                DrawEvolutionBlurredLabel(
                    kickerRect,
                    "WEAPON EVOLVED",
                    _evolutionRevealKickerStyle,
                    introBlur);
                DrawEvolutionBlurredLabel(
                    previousRect,
                    (_evolutionRevealPreviousName ?? string.Empty).ToUpperInvariant(),
                    _evolutionRevealPreviousStyle,
                    introBlur);
                DrawEvolutionBlurredLabel(
                    titleRect,
                    titleText,
                    _evolutionRevealTitleStyle,
                    introBlur);
            }
            DrawEvolutionTitleGlow(titleRect, titleText, scale, alpha);
            GUI.Label(kickerRect, "WEAPON EVOLVED", _evolutionRevealKickerStyle);
            GUI.Label(
                previousRect,
                (_evolutionRevealPreviousName ?? string.Empty).ToUpperInvariant(),
                _evolutionRevealPreviousStyle);
            GUI.Label(titleRect, titleText, _evolutionRevealTitleStyle);
            GUI.color = oldColor;
        }

        private void DrawEvolutionBlurredLabel(
            Rect rect,
            string text,
            GUIStyle style,
            float blurRadius)
        {
            if (style == null || string.IsNullOrEmpty(text) || blurRadius <= 0f) return;
            var originalTextColor = style.normal.textColor;
            const int sampleCount = 12;
            for (var ring = 0; ring < 3; ring++)
            {
                var radius = blurRadius * (ring + 1f) / 3f;
                var sampleAlpha = originalTextColor.a *
                    (ring == 0 ? 0.018f : ring == 1 ? 0.012f : 0.006f);
                style.normal.textColor = new Color(
                    originalTextColor.r,
                    originalTextColor.g,
                    originalTextColor.b,
                    sampleAlpha);
                for (var sample = 0; sample < sampleCount; sample++)
                {
                    var angle = sample * Mathf.PI * 2f / sampleCount;
                    var offset = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
                    GUI.Label(
                        new Rect(rect.x + offset.x, rect.y + offset.y, rect.width, rect.height),
                        text,
                        style);
                }
            }
            style.normal.textColor = originalTextColor;
        }

        private void DrawEvolutionTitleGlow(Rect rect, string text, float scale, float alpha)
        {
            if (_evolutionRevealTitleGlowStyle == null || string.IsNullOrEmpty(text)) return;
            const int sampleCount = 8;
            var baseAlpha = EvolutionRevealTitleGlowAlpha(alpha);
            var radiusScale = Mathf.Max(0.01f, scale);
            for (var ring = 0; ring < 3; ring++)
            {
                var ringRadius = 26f * radiusScale * ((ring + 1f) / 3f);
                var sampleAlpha = baseAlpha * (ring == 0 ? 0.04f : ring == 1 ? 0.025f : 0.012f);
                _evolutionRevealTitleGlowStyle.normal.textColor = new Color(
                    _evolutionRevealAccent.r,
                    _evolutionRevealAccent.g,
                    _evolutionRevealAccent.b,
                    sampleAlpha);
                for (var sample = 0; sample < sampleCount; sample++)
                {
                    var angle = sample * Mathf.PI * 2f / sampleCount;
                    var offset = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * ringRadius;
                    GUI.Label(
                        new Rect(rect.x + offset.x, rect.y + offset.y, rect.width, rect.height),
                        text,
                        _evolutionRevealTitleGlowStyle);
                }
            }
        }

        private GUIStyle EvolutionMarkStyle(Color accent)
        {
            var key = ColorUtility.ToHtmlStringRGB(accent);
            if (_evolutionMarkStyleCache.TryGetValue(key, out var cached)) return cached;
            var style = new GUIStyle(GUI.skin.box)
            {
                padding = new RectOffset(0, 0, 0, 0),
                margin = new RectOffset(0, 0, 0, 0),
                border = new RectOffset(16, 16, 16, 16),
            };
            var fill = new Color(0.012f, 0.027f, 0.071f, 0.90f);
            var border = new Color(accent.r, accent.g, accent.b, 1f);
            var texture = RoundedGradientGuiTexture(
                fill,
                fill,
                border,
                78,
                78,
                16f,
                "VoidFall Evolution Mark " + key);
            SetGuiStyleState(style.normal, texture, Color.white);
            SetGuiStyleState(style.hover, texture, Color.white);
            _evolutionMarkStyleCache[key] = style;
            return style;
        }

        private static Texture2D EvolutionMarkRingTexture(Color accent)
        {
            var key = ColorUtility.ToHtmlStringRGB(accent);
            if (_evolutionMarkRingCache.TryGetValue(key, out var cached)) return cached;
            const int size = 94;
            const float halfShape = 39f;
            const float radius = 16f;
            const float ringWidth = 8f;
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "VoidFall Evolution Mark Ring " + key,
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
            };
            var pixels = new Color[size * size];
            var half = (size - 1) * 0.5f;
            for (var y = 0; y < size; y++)
            {
                for (var x = 0; x < size; x++)
                {
                    var distance = RoundedRectSignedDistance(
                        x - half,
                        y - half,
                        halfShape,
                        halfShape,
                        radius);
                    var edge = Mathf.Clamp01((ringWidth - distance) / 1.5f) *
                        Mathf.Clamp01((distance + 0.5f) / 1.5f);
                    pixels[y * size + x] = new Color(accent.r, accent.g, accent.b, 0.08f * edge);
                }
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            _evolutionMarkRingCache[key] = texture;
            return texture;
        }

        private static Texture2D EvolutionMarkGlowTexture(Color accent)
        {
            var key = ColorUtility.ToHtmlStringRGB(accent);
            if (_evolutionMarkGlowCache.TryGetValue(key, out var cached)) return cached;
            const int size = 150;
            const float halfShape = 39f;
            const float radius = 16f;
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "VoidFall Evolution Mark Glow " + key,
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
            };
            var pixels = new Color[size * size];
            var half = (size - 1) * 0.5f;
            for (var y = 0; y < size; y++)
            {
                for (var x = 0; x < size; x++)
                {
                    var distance = Mathf.Max(0f, RoundedRectSignedDistance(
                        x - half,
                        y - half,
                        halfShape,
                        halfShape,
                        radius));
                    pixels[y * size + x] = new Color(
                        accent.r,
                        accent.g,
                        accent.b,
                        EvolutionMarkGlowAlpha(distance));
                }
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            _evolutionMarkGlowCache[key] = texture;
            return texture;
        }

        private static Texture2D EvolutionCrossLineTexture(Color accent)
        {
            var key = ColorUtility.ToHtmlStringRGB(accent);
            if (_evolutionCrossLineCache.TryGetValue(key, out var cached)) return cached;
            const int width = 256;
            var texture = new Texture2D(width, 1, TextureFormat.RGBA32, false)
            {
                name = "VoidFall Evolution Cross Line " + key,
                hideFlags = HideFlags.HideAndDontSave,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
            };
            var pixels = new Color[width];
            for (var x = 0; x < width; x++)
            {
                var normalizedPosition = x / (float)(width - 1);
                pixels[x] = new Color(
                    accent.r,
                    accent.g,
                    accent.b,
                    EvolutionCrossLineAlpha(normalizedPosition));
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            _evolutionCrossLineCache[key] = texture;
            return texture;
        }

        private static float EvolutionCrossLineAlpha(float normalizedPosition)
        {
            var position = Mathf.Clamp01(normalizedPosition);
            return 1f - Mathf.Abs(position * 2f - 1f);
        }

        private static float RoundedRectSignedDistance(
            float x,
            float y,
            float halfWidth,
            float halfHeight,
            float radius)
        {
            var qx = Mathf.Abs(x) - (halfWidth - radius);
            var qy = Mathf.Abs(y) - (halfHeight - radius);
            var outsideX = Mathf.Max(qx, 0f);
            var outsideY = Mathf.Max(qy, 0f);
            return Mathf.Sqrt(outsideX * outsideX + outsideY * outsideY) +
                Mathf.Min(Mathf.Max(qx, qy), 0f) - radius;
        }

        private static float EvolutionMarkGlowAlpha(float distance)
        {
            const float peakAlpha = 0.32f;
            const float blurRadius = 13f;
            var safeDistance = Mathf.Max(0f, distance);
            return peakAlpha * Mathf.Exp(
                -(safeDistance * safeDistance) / (2f * blurRadius * blurRadius));
        }

        private static void DrawEvolutionTextBand(Rect rect, float alpha)
        {
            var band = new Rect(rect.x - 24f, rect.y, rect.width + 48f, rect.height);
            GUI.color = new Color(0.012f, 0.027f, 0.071f, 0.82f * Mathf.Clamp01(alpha));
            GUI.DrawTexture(band, Texture2D.whiteTexture);
        }

        private static float EvolutionRevealDuration()
        {
            return 2.6f;
        }

        private static float EvolutionRevealCrossLineLength(float viewportWidth)
        {
            return Mathf.Min(viewportWidth * 0.42f, 330f);
        }

        private static float EvolutionRevealScale(float elapsedSeconds)
        {
            var progress = Mathf.Clamp01(elapsedSeconds / EvolutionRevealDuration());
            const float baseScale = 0.7f;
            if (progress <= 0.13f)
            {
                var segment = CubicBezierEase(progress / 0.13f, 0.22f, 1f, 0.36f, 1f);
                return Mathf.LerpUnclamped(baseScale * 0.82f, baseScale * 1.04f, segment);
            }
            if (progress <= 0.22f)
            {
                var segment = CubicBezierEase((progress - 0.13f) / 0.09f, 0.22f, 1f, 0.36f, 1f);
                return Mathf.LerpUnclamped(baseScale * 1.04f, baseScale, segment);
            }
            if (progress <= 0.78f) return baseScale;
            var outro = CubicBezierEase((progress - 0.78f) / 0.22f, 0.22f, 1f, 0.36f, 1f);
            return Mathf.LerpUnclamped(baseScale, baseScale * 1.02f, outro);
        }

        private static float EvolutionRevealOpacity(float elapsedSeconds)
        {
            var progress = Mathf.Clamp01(elapsedSeconds / EvolutionRevealDuration());
            if (progress <= 0.13f)
                return CubicBezierEase(progress / 0.13f, 0.22f, 1f, 0.36f, 1f);
            if (progress <= 0.78f) return 1f;
            var outro = CubicBezierEase((progress - 0.78f) / 0.22f, 0.22f, 1f, 0.36f, 1f);
            return 1f - outro;
        }

        private static float EvolutionRevealTitleGlowAlpha(float alpha)
        {
            return Mathf.Clamp01(alpha) * 0.55f;
        }

        private static float EvolutionRevealIntroBlur(float elapsedSeconds)
        {
            if (elapsedSeconds <= 0f) return 8f;
            var progress = Mathf.Clamp01(elapsedSeconds / EvolutionRevealDuration());
            if (progress >= 0.13f) return 0f;
            var eased = CubicBezierEase(progress / 0.13f, 0.22f, 1f, 0.36f, 1f);
            return Mathf.LerpUnclamped(8f, 0f, eased);
        }

        private static int EvolutionRevealTitleFontSize(float viewportWidth)
        {
            return Mathf.Clamp(Mathf.RoundToInt(viewportWidth * 0.06f), 27, 52);
        }

