        private static float ResultBestPulse(float time)
        {
            const float period = 1.6f;
            return 0.5f - 0.5f * Mathf.Cos(time / period * Mathf.PI * 2f);
        }

        private static float ResultBestGlowRadius(float time)
        {
            return Mathf.Lerp(18f, 38f, ResultBestPulse(time));
        }

        private static float ResultBestGlowAlpha(float time)
        {
            return Mathf.Lerp(0.32f, 0.68f, ResultBestPulse(time));
        }

        private static int ResultBestGlowLayerCount()
        {
            return 6;
        }

        private static float ResultBestGlowLayerSpread(float radius, int layer)
        {
            return radius * (layer + 1f) / ResultBestGlowLayerCount();
        }

        private static float ResultBestGlowLayerAlphaFactor(int layer)
        {
            var t = Mathf.Clamp01(layer / Mathf.Max(1f, ResultBestGlowLayerCount() - 1f));
            return Mathf.Lerp(0.12f, 0.012f, t);
        }

        private static Texture2D BuildChipIconTexture()
        {
            if (_buildChipIconTexture != null) return _buildChipIconTexture;

            _buildChipIconTexture = Resources.Load<Texture2D>("VoidFall/BuildChipIconsRaster");
            if (_buildChipIconTexture != null) return _buildChipIconTexture;

            var sprite = Resources.Load<Sprite>("VoidFall/BuildChipIcons");
            if (sprite != null)
            {
                _buildChipIconTexture = sprite.texture;
                return _buildChipIconTexture;
            }

            _buildChipIconTexture = Resources.Load<Texture2D>("VoidFall/BuildChipIcons");
            return _buildChipIconTexture;
        }

        private static Rect BuildChipIconUv(string id)
        {
            var slot = BuildChipIconSlot(id);
            if (slot < 0) return new Rect(0f, 0f, 1f, 1f);

            var column = slot % 5;
            var row = slot / 5;
            return new Rect(
                column / 5f,
                1f - ((row + 1) / 3f),
                1f / 5f,
                1f / 3f);
        }

        private static int BuildChipIconSlot(string id)
        {
            // Atlas order mirrors BuildChipIcons.svg and the browser Lucide map.
            switch (id)
            {
                case "pistol": return 0; // Crosshair
                case "scattergun": return 1; // Aperture
                case "railgun": return 2; // Zap
                case "blades": return 3; // Orbit
                case "arc": return 4; // Sparkles
                case "seeker": return 5; // Rocket
                case "calibration": return 6; // Wrench
                case "cycling": return 7; // Gauge
                case "plating": return 8; // Shield
                case "mobility": return 9; // HeartPulse
                case "collector": return 10; // Magnet
                case "adrenal": return 11; // Flame
                case "amplifier": return 12; // Expand
                case "regenerator": return 13; // HeartPlus
                case "cooling": return 14; // CircleGauge
                case "output": return 0; // Crosshair
                case "frame": return 8; // Shield
                case "optics": return 0; // Crosshair
                case "overload": return 2; // Zap
                default: return -1;
            }
        }

        private static string BuildChipGlyph(string id)
        {
            // Last-resort fallback if the SVG resource cannot be imported.
            switch (id)
            {
                case "pistol": return "\u2316"; // Crosshair
                case "scattergun": return "\u25ce"; // Aperture
                case "railgun": return "\u26a1"; // Zap
                case "blades": return "\u25cc"; // Orbit
                case "arc": return "\u2726"; // Sparkles
                case "seeker": return "\u2191"; // Rocket
                case "calibration": return "\u2692"; // Wrench
                case "cycling": return "\u25c9"; // Gauge
                case "plating": return "\u25c7"; // Shield
                case "mobility": return "\u2665"; // HeartPulse
                case "collector": return "\u2328"; // Magnet
                case "optics": return "\u2316"; // Crosshair
                case "overload": return "\u26a1"; // Zap
                case "adrenal": return "\u2668"; // Flame
                case "amplifier": return "\u2194"; // Expand
                case "regenerator": return "\u2665"; // HeartPlus
                case "output": return "\u2316"; // Crosshair
                case "cooling": return "\u25c9"; // Gauge
                case "frame": return "\u25c7"; // Shield
                default: return "\u2022";
            }
        }

        private static string WeaponDisplayAccent(int weaponIndex, bool evolved)
        {
            if (weaponIndex < 0 || weaponIndex >= ContentCatalog.Weapons.Length)
                return "#67e8f9";
            var weapon = ContentCatalog.Weapons[weaponIndex];
            if (!evolved) return weapon.Accent;
            for (var index = 0; index < ContentCatalog.Evolutions.Length; index++)
            {
                var evolution = ContentCatalog.Evolutions[index];
                if (evolution.WeaponId == weapon.Id) return evolution.Accent;
            }
            return weapon.Accent;
        }

        private static string WeaponDisplayName(int weaponIndex, bool evolved)
        {
            if (weaponIndex < 0 || weaponIndex >= ContentCatalog.Weapons.Length)
                return string.Empty;
            var weapon = ContentCatalog.Weapons[weaponIndex];
            if (!evolved) return weapon.Name;
            for (var index = 0; index < ContentCatalog.Evolutions.Length; index++)
            {
                var evolution = ContentCatalog.Evolutions[index];
                if (evolution.WeaponId == weapon.Id) return evolution.Name;
            }
            return weapon.Name;
        }

        private void DrawResultMetric(string label, string value)
        {
            GUILayout.BeginVertical(
                RecordMetricBoxStyle(),
                GUILayout.MinWidth(105f),
                GUILayout.Height(BrowserMetricMinHeight()),
                GUILayout.ExpandWidth(true));
            GUILayout.FlexibleSpace();
            GUILayout.Label(label.ToUpperInvariant(), RecordMetricLabelStyle());
            GUILayout.Space(BrowserMetricContentGap());
            GUILayout.Label(value, RecordMetricValueStyle());
            GUILayout.FlexibleSpace();
            GUILayout.EndVertical();
        }

        private void DrawLevelUpPrompt()
        {
            var oldColor = GUI.color;
            var safeArea = Screen.safeArea;
            var width = LevelUpContentWidth(safeArea.width);
            var height = Mathf.Min(620f, safeArea.height - 32f);
            var x = safeArea.xMin + (safeArea.width - width) * 0.5f;
            var y = safeArea.yMin + (safeArea.height - height) * 0.5f;
            var smallViewport = LevelUpUsesShortLandscapeLayout(safeArea.width, safeArea.height);
            var contentInset = smallViewport ? 13f : 0f;
            var contentWidth = width - contentInset * 2f;
            GUI.color = new Color(0.008f, 0.020f, 0.059f, 0.59f);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.whiteTexture);
            GUI.color = Color.white;
            EnsureLevelUpPromptStyles();
            GUILayout.BeginArea(new Rect(x + contentInset, y, contentWidth, height));
            if (smallViewport)
                _levelUpScroll = GUILayout.BeginScrollView(_levelUpScroll, GUILayout.ExpandHeight(true));
            GUILayout.Space(smallViewport ? 13f : 8f);
            GUILayout.Label("LEVEL UP", _levelUpKickerStyle, GUILayout.Height(18f));
            GUILayout.Space(8f);
            GUILayout.Label("CHOOSE AN UPGRADE", _levelUpTitleStyle, GUILayout.Height(48f));
            GUILayout.Space(LevelUpHeaderGap());

            if (_levelOptions != null)
            {
                var columns = LevelUpGridColumns(safeArea.width, _levelOptions.Length);
                if (columns > 1)
                {
                    var gap = UpgradeCardGridGap();
                    var cardWidth = Mathf.Max(160f, (contentWidth - gap * (columns - 1)) / columns);
                    var cardHeight = Mathf.Clamp(height - 160f, 190f, UpgradeCardMinHeight(false));
                    GUILayout.BeginHorizontal();
                    for (var index = 0; index < _levelOptions.Length; index++)
                    {
                        var option = _levelOptions[index];
                        if (DrawUpgradeCard(option, index, cardHeight, cardWidth))
                        {
                            SelectLevelOption(index);
                            GUILayout.EndHorizontal();
                            if (smallViewport) GUILayout.EndScrollView();
                            GUILayout.EndArea();
                            GUI.color = oldColor;
                            return;
                        }
                        if (index < _levelOptions.Length - 1) GUILayout.Space(gap);
                    }
                    GUILayout.EndHorizontal();
                }
                else
                {
                    var optionHeight = Mathf.Clamp(
                        (height - 160f) / Mathf.Max(1, _levelOptions.Length),
                        smallViewport ? UpgradeCardSmallViewportMinHeight() : UpgradeCardMinHeight(true),
                        smallViewport ? 210f : 170f);
                    for (var index = 0; index < _levelOptions.Length; index++)
                    {
                        var option = _levelOptions[index];
                        if (DrawUpgradeCard(option, index, optionHeight, -1f))
                        {
                            SelectLevelOption(index);
                            if (smallViewport) GUILayout.EndScrollView();
                            GUILayout.EndArea();
                            GUI.color = oldColor;
                            return;
                        }
                        GUILayout.Space(6f);
                    }
                }
            }

            if (_rerollsRemaining > 0)
            {
                if (DrawRerollButton())
                    RerollLevelOptions();
            }
            else
            {
                GUILayout.Label("No rerolls left.", MenuBodyStyle());
            }
            if (smallViewport) GUILayout.EndScrollView();
            GUILayout.EndArea();
            GUI.color = oldColor;
        }

        private void EnsureLevelUpPromptStyles()
        {
            if (_levelUpKickerStyle == null)
            {
                _levelUpKickerStyle = new GUIStyle(MenuBodyStyle())
                {
                    alignment = TextAnchor.MiddleCenter,
                    font = BrowserDisplayFont(),
                    fontSize = LevelUpKickerFontSize(),
                    fontStyle = FontStyle.Bold,
                    wordWrap = false,
                };
                _levelUpKickerStyle.normal.textColor = new Color(0.431f, 0.906f, 0.608f, 1f);
            }
            if (_levelUpTitleStyle == null)
            {
                _levelUpTitleStyle = new GUIStyle(MenuTitleStyle())
                {
                    alignment = TextAnchor.MiddleCenter,
                    font = BrowserDisplayFont(),
                    fontStyle = FontStyle.Bold,
                    wordWrap = false,
                };
                _levelUpTitleStyle.normal.textColor = new Color(0.945f, 0.961f, 0.976f, 1f);
            }
            _levelUpTitleStyle.fontSize = LevelUpTitleFontSize(Screen.safeArea.width);
        }

        private static int LevelUpKickerFontSize()
        {
            // React computes the 11px source kicker through the 1.15 UI scale.
            return BrowserNearestFontSize(11f * 1.15f);
        }

        private static int BrowserNearestFontSize(float value)
        {
            // CSS keeps the half-pixel value; IMGUI needs an integer. Use
            // conventional half-up rounding instead of Unity's tie-to-even
            // Mathf.RoundToInt behavior.
            return Mathf.FloorToInt(value + 0.5f);
        }

        private static float LevelUpContentWidth(float viewportWidth)
        {
            return Mathf.Min(930f, viewportWidth * 0.96f);
        }

        private static float LevelUpHeaderGap()
        {
            return 24f;
        }

        private static int LevelUpTitleFontSize(float viewportWidth)
        {
            const float uiTextScale = 1.15f;
            if (viewportWidth <= 430f)
                return BrowserNearestFontSize(22f * uiTextScale);
            var preferred = viewportWidth * 0.05f * uiTextScale;
            return BrowserNearestFontSize(Mathf.Clamp(
                preferred,
                28f * uiTextScale,
                40f * uiTextScale));
        }

        private bool DrawRerollButton()
        {
            EnsureRerollStyles();
            GUILayout.Space(RerollRowMargin());
            var canReroll = _rerollsRemaining > 0;
            var oldEnabled = GUI.enabled;
            GUI.enabled = oldEnabled && canReroll;
            var rect = GUILayoutUtility.GetRect(
                GUIContent.none,
                GUI.skin.button,
                GUILayout.Height(RerollButtonHeight()),
                GUILayout.ExpandWidth(true));
            var clicked = GUI.Button(rect, GUIContent.none, _rerollButtonStyle);
            GUI.enabled = oldEnabled;

            var oldColor = GUI.color;
            var icon = RerollIconTexture();
            var tint = RerollActionTextColor(canReroll);
            var groupWidth = 190f;
            var groupX = rect.center.x - groupWidth * 0.5f;
            GUI.color = tint;
            if (icon != null)
            {
                GUI.DrawTexture(
                    new Rect(groupX + 4f, rect.y + (rect.height - 16f) * 0.5f, 16f, 16f),
                    icon,
                    ScaleMode.ScaleToFit,
                    true);
            }
            GUI.color = tint;
            GUI.Label(
                new Rect(groupX + 28f, rect.y + 1f, 122f, rect.height - 2f),
                canReroll ? $"Reroll ({_rerollsRemaining})" : "Reroll used",
                _rerollButtonLabelStyle);
            var keyRect = new Rect(
                groupX + groupWidth - RerollKeycapWidth() - 4f,
                rect.y + (rect.height - 22f) * 0.5f,
                RerollKeycapWidth(),
                22f);
            GUI.color = Color.white;
            GUI.Box(keyRect, GUIContent.none, _rerollKeycapStyle);
            GUI.color = new Color(0.58f, 0.64f, 0.72f, 1f);
            GUI.Label(keyRect, "Q", _rerollKeyStyle);
            GUI.color = oldColor;
            return clicked && canReroll;
        }

