        private float UpgradeCardEntranceProgressForRuntime(int index)
        {
            if (_levelUpPromptOpenedAt < 0f) return 1f;
            return UpgradeCardEntranceProgress(
                Time.realtimeSinceStartup - _levelUpPromptOpenedAt,
                index);
        }

        private static float UpgradeCardEntranceProgress(float elapsedSeconds, int index)
        {
            var delay = Mathf.Max(0, index) * UpgradeCardEntranceDelay();
            if (elapsedSeconds <= delay) return 0f;
            var local = elapsedSeconds - delay;
            if (local >= UpgradeCardEntranceDuration()) return 1f;
            var normalized = Mathf.Clamp01(local / UpgradeCardEntranceDuration());
            return CubicBezierEase(normalized, 0.22f, 1.4f, 0.36f, 1f);
        }

        private static float CubicBezierEase(
            float x,
            float x1,
            float y1,
            float x2,
            float y2)
        {
            var low = 0f;
            var high = 1f;
            for (var iteration = 0; iteration < 12; iteration++)
            {
                var t = (low + high) * 0.5f;
                if (CubicBezierCoordinate(t, x1, x2) < x)
                    low = t;
                else
                    high = t;
            }
            return CubicBezierCoordinate((low + high) * 0.5f, y1, y2);
        }

        private static float CubicBezierCoordinate(float t, float first, float second)
        {
            var inverse = 1f - t;
            return 3f * inverse * inverse * t * first +
                3f * inverse * t * t * second +
                t * t * t;
        }

        private static void ApplyUpgradeCardTransform(Rect rect, float entranceProgress)
        {
            if (Event.current == null || Event.current.type != EventType.Repaint) return;
            if (entranceProgress < 1f)
            {
                var scale = Mathf.LerpUnclamped(0.94f, 1f, entranceProgress);
                GUIUtility.ScaleAroundPivot(
                    new Vector2(scale, scale),
                    rect.center);
                GUI.matrix = Matrix4x4.TRS(
                        new Vector3(0f, (1f - entranceProgress) * 26f, 0f),
                        Quaternion.identity,
                        Vector3.one) * GUI.matrix;
                return;
            }

            if (UpgradeCardIsHovered(rect))
            {
                GUIUtility.ScaleAroundPivot(
                    new Vector2(UpgradeCardHoverScale(), UpgradeCardHoverScale()),
                    rect.center);
                GUI.matrix = Matrix4x4.TRS(
                        new Vector3(0f, -UpgradeCardHoverLift(), 0f),
                        Quaternion.identity,
                        Vector3.one) * GUI.matrix;
            }
        }

        private static Color WithAlpha(Color color, float opacity)
        {
            color.a *= Mathf.Clamp01(opacity);
            return color;
        }

        private static bool UpgradeCardIsHovered(Rect rect)
        {
            return Event.current != null &&
                   Event.current.type == EventType.Repaint &&
                   rect.Contains(Event.current.mousePosition);
        }

