        private static void DrawUpgradeRankPips(
            UpgradeOptionDefinition option,
            Rect cardRect,
            Color accent,
            bool centered = false,
            float opacity = 1f,
            float contentPadding = 20f)
        {
            if (option == null ||
                (option.Kind != UpgradeOptionKind.Weapon && option.Kind != UpgradeOptionKind.Support) ||
                option.MaxRank <= 0)
                return;

            var pipWidth = UpgradeRankPipWidth();
            var gap = 4f;
            var totalWidth = option.MaxRank * pipWidth + Mathf.Max(0, option.MaxRank - 1) * gap;
            var x = centered
                ? cardRect.center.x - totalWidth * 0.5f
                : (cardRect.x + contentPadding + 56f + 13f + cardRect.xMax - contentPadding) * 0.5f - totalWidth * 0.5f;
            var pipHeight = UpgradeRankPipHeight();
            var y = cardRect.yMax - contentPadding - pipHeight;
            var oldColor = GUI.color;
            for (var rank = 0; rank < option.MaxRank; rank++)
            {
                var filled = rank < option.CurrentRank;
                var next = rank == option.CurrentRank;
                var pipRect = new Rect(x + rank * (pipWidth + gap), y, pipWidth, pipHeight);
                if (next)
                {
                    var borderColor = WithAlpha(accent, opacity);
                    GUI.color = borderColor;
                    GUI.DrawTexture(new Rect(pipRect.x, pipRect.y, pipRect.width, 1f), Texture2D.whiteTexture);
                    GUI.DrawTexture(new Rect(pipRect.x, pipRect.yMax - 1f, pipRect.width, 1f), Texture2D.whiteTexture);
                    GUI.DrawTexture(new Rect(pipRect.x, pipRect.y, 1f, pipRect.height), Texture2D.whiteTexture);
                    GUI.DrawTexture(new Rect(pipRect.xMax - 1f, pipRect.y, 1f, pipRect.height), Texture2D.whiteTexture);
                }
                else
                {
                    GUI.color = WithAlpha(
                        filled ? accent : new Color(0.392f, 0.455f, 0.545f, 1f),
                        filled ? opacity : opacity * 0.28f);
                    GUI.DrawTexture(pipRect, Texture2D.whiteTexture);
                }
            }
            GUI.color = oldColor;
        }

        private static string UpgradeOptionIconId(UpgradeOptionDefinition option)
        {
            if (option == null) return "repair";
            switch (option.Kind)
            {
                case UpgradeOptionKind.Weapon:
                case UpgradeOptionKind.Support:
                case UpgradeOptionKind.Late:
                case UpgradeOptionKind.Evolution:
                    return option.TargetId ?? "repair";
                default:
                    return "repair";
            }
        }

        private static Texture2D UpgradeOptionIconTexture(string iconId)
        {
            if (iconId != "repair") return BuildChipIconTexture();
            if (_upgradeHeartIconTexture != null) return _upgradeHeartIconTexture;
            _upgradeHeartIconTexture = Resources.Load<Texture2D>("VoidFall/UpgradeHeartRaster");
            if (_upgradeHeartIconTexture != null) return _upgradeHeartIconTexture;
            var sprite = Resources.Load<Sprite>("VoidFall/UpgradeHeart");
            _upgradeHeartIconTexture = sprite != null
                ? sprite.texture
                : Resources.Load<Texture2D>("VoidFall/UpgradeHeart");
            return _upgradeHeartIconTexture;
        }

        private static Rect UpgradeOptionIconUv(string iconId)
        {
            return iconId == "repair" ? new Rect(0f, 0f, 1f, 1f) : BuildChipIconUv(iconId);
        }

        private static string UpgradeOptionLabel(UpgradeOptionDefinition option)
        {
            if (option == null) return string.Empty;
            switch (option.Kind)
            {
                case UpgradeOptionKind.Weapon:
                    return option.CurrentRank == 0
                        ? "New weapon"
                        : "Weapon " + option.CurrentRank + " \u2192 " + option.NextRank;
                case UpgradeOptionKind.Support:
                    return "Support " + option.CurrentRank + " \u2192 " + option.NextRank;
                case UpgradeOptionKind.Evolution:
                    return "Evolution ready";
                case UpgradeOptionKind.Late:
                    return "Long-run tune " + option.NextRank;
                default:
                    return "Immediate";
            }
        }

        private static string UpgradeOptionRankPips(UpgradeOptionDefinition option)
        {
            if (option == null ||
                (option.Kind != UpgradeOptionKind.Weapon && option.Kind != UpgradeOptionKind.Support) ||
                option.MaxRank <= 0)
            {
                return string.Empty;
            }

            var pips = string.Empty;
            for (var rank = 0; rank < option.MaxRank; rank++)
            {
                if (rank < option.CurrentRank) pips += " [#]";
                else if (rank == option.CurrentRank) pips += " [>]";
                else pips += " [ ]";
            }
            return "\nRanks" + pips;
        }

