        private bool DrawHomeMenuCard(string title, string detail, string iconId, float height)
        {
            var rect = GUILayoutUtility.GetRect(
                GUIContent.none,
                HomeCardButtonStyle(),
                GUILayout.Height(height),
                GUILayout.ExpandWidth(true));
            var hovered = Event.current != null && rect.Contains(Event.current.mousePosition);
            var oldMatrix = GUI.matrix;
            if (hovered && Event.current.type == EventType.Repaint)
            {
                GUI.matrix = Matrix4x4.Translate(
                        new Vector3(0f, -HomeMenuCardHoverLift(), 0f)) * GUI.matrix;
            }
            var clicked = GUI.Button(rect, GUIContent.none, HomeCardButtonStyle());
            var oldColor = GUI.color;
            DrawHomeIcon(
                new Rect(rect.x + 12f, rect.center.y - 9f, 18f, 18f),
                iconId,
                new Color(0.49f, 0.83f, 0.99f, 1f));
            GUI.color = WithAlpha(Color.white, oldColor.a);
            GUI.Label(
                new Rect(rect.x + 40f, rect.y + 6f, rect.width - 50f, 21f),
                title.ToUpperInvariant(),
                HomeCardTitleStyle());
            GUI.color = WithAlpha(Color.white, oldColor.a);
            GUI.Label(
                new Rect(rect.x + 40f, rect.y + 28f, rect.width - 50f, 18f),
                detail,
                HomeCardDetailStyle());
            GUI.color = oldColor;
            GUI.matrix = oldMatrix;
            return clicked;
        }

        private static int HomeMenuColumns(float width)
        {
            return width <= 720f ? 2 : 3;
        }

        private static bool HomeMenuUsesLandscapeLayout(float width, float height)
        {
            // React's max-height:560px landscape rule switches the menu back
            // to three columns and a compact, top-aligned stack.
            return width > height && height <= 560f;
        }

        private static int HomeMenuColumnsForLayout(float width, float height)
        {
            return HomeMenuUsesLandscapeLayout(width, height) ? 3 : HomeMenuColumns(width);
        }

        private static int HomeMenuTitleFontSize(float width, bool landscapeLayout)
        {
            const float uiTextScale = 1.15f;
            if (landscapeLayout) return Mathf.RoundToInt(38f * uiTextScale);
            return Mathf.RoundToInt(Mathf.Clamp(width * 0.15f, 46f, 68f) * uiTextScale);
        }

        private static float HomeTitleDriftOffset(float elapsed)
        {
            return -4f + Mathf.Cos(elapsed * Mathf.PI * 2f / 5f) * 4f;
        }

        private static float HomeTitleShimmerProgress(float elapsed, int glyphIndex, int glyphCount)
        {
            var normalizedIndex = glyphIndex / (float)Mathf.Max(1, glyphCount - 1);
            var progress = normalizedIndex + Mathf.Repeat(elapsed / 6f, 1f);
            return progress > 1f ? progress - 1f : progress;
        }

        private static float HomeStartBreathe(float elapsed)
        {
            return 0.5f - 0.5f * Mathf.Cos(elapsed * Mathf.PI * 2f / 2.4f);
        }

        private static float HomeMenuCardHoverLift()
        {
            return 3f;
        }

        private static int WorkshopMenuColumns(float width)
        {
            return width <= 720f ? 1 : 2;
        }

        private static int WorkshopPreviewRankColumns(int itemCount)
        {
            return Mathf.Min(5, Mathf.Max(1, itemCount));
        }

        private static void DrawHomeIcon(Rect rect, string iconId, Color color)
        {
            var texture = HomeIconTexture();
            var oldColor = GUI.color;
            GUI.color = WithAlpha(color, color.a * oldColor.a);
            if (texture != null && HomeIconSlot(iconId) >= 0)
                GUI.DrawTextureWithTexCoords(rect, texture, HomeIconUv(iconId), true);
            GUI.color = oldColor;
        }

        private static Texture2D HomeIconTexture()
        {
            if (_homeIconTexture != null) return _homeIconTexture;
            _homeIconTexture = Resources.Load<Texture2D>("VoidFall/HomeIconsRaster");
            if (_homeIconTexture != null) return _homeIconTexture;
            var sprite = Resources.Load<Sprite>("VoidFall/HomeIcons");
            _homeIconTexture = sprite != null
                ? sprite.texture
                : Resources.Load<Texture2D>("VoidFall/HomeIcons");
            return _homeIconTexture;
        }

        private static int HomeIconSlot(string iconId)
        {
            switch (iconId)
            {
                case "wrench": return 0;
                case "trophy": return 1;
                case "settings": return 2;
                case "coins": return 3;
                case "skull": return 4;
                default: return -1;
            }
        }

        private static Rect HomeIconUv(string iconId)
        {
            var slot = HomeIconSlot(iconId);
            if (slot < 0) return new Rect(0f, 0f, 1f, 1f);
            var column = slot % 3;
            var row = slot / 3;
            return new Rect(
                column / 3f,
                1f - ((row + 1) / 2f),
                1f / 3f,
                1f / 2f);
        }

        private bool DrawIconTextButton(
            string label,
            string iconId,
            float height,
            bool homeAtlas = false,
            bool prominent = false)
        {
            var rect = GUILayoutUtility.GetRect(
                GUIContent.none,
                GUI.skin.button,
                GUILayout.Height(height),
                GUILayout.ExpandWidth(true));
            var clicked = GUI.Button(rect, GUIContent.none, GUI.skin.button);
            var oldColor = GUI.color;
            var iconSize = prominent ? 21f : 16f;
            var iconX = rect.x + (prominent ? 16f : 12f);
            if (homeAtlas)
            {
                DrawHomeIcon(
                    new Rect(iconX, rect.center.y - iconSize * 0.5f, iconSize, iconSize),
                    iconId,
                    new Color(0.49f, 0.83f, 0.99f, 1f));
            }
            else
            {
                DrawControlIcon(
                    new Rect(iconX, rect.center.y - iconSize * 0.5f, iconSize, iconSize),
                    iconId,
                    new Color(0.8f, 0.94f, 0.98f, 1f));
            }
            GUI.color = WithAlpha(Color.white, oldColor.a);
            GUI.Label(
                new Rect(
                    rect.x + (prominent ? 48f : 38f),
                    rect.y + 4f,
                    Mathf.Max(20f, rect.width - (prominent ? 60f : 48f)),
                    Mathf.Max(18f, rect.height - 8f)),
                label,
                prominent ? MenuSectionStyle() : MenuBodyStyle());
            GUI.color = oldColor;
            return clicked;
        }

        private static void DrawControlIcon(Rect rect, string iconId, Color color)
        {
            var texture = ControlIconTexture();
            var oldColor = GUI.color;
            GUI.color = WithAlpha(color, color.a * oldColor.a);
            if (texture != null && ControlIconSlot(iconId) >= 0)
                GUI.DrawTextureWithTexCoords(rect, texture, ControlIconUv(iconId), true);
            GUI.color = oldColor;
