        private static int ControlIconSlot(string iconId)
        {
            switch (iconId)
            {
                case "arrow-left": return 0;
                case "play": return 1;
                case "pause": return 2;
                case "rotate-ccw": return 3;
                case "house": return 4;
                case "volume-2": return 5;
