            return 24f;
        }

        private static float SettingsToggleKnobSize()
        {
            return 18f;
        }

        private static float SettingsToggleKnobInset()
        {
            return 3f;
        }

        private static float SettingsToggleKnobOnOffset()
        {
            return 19f;
