        private static Font BrowserBodyFont()
        {
            if (_browserBodyFont != null) return _browserBodyFont;
            // Match the browser body stack on Windows, where Segoe UI is the
            // resolved fallback for the source's Segoe UI Variable family.
            // Keep LegacyRuntime.ttf as the portable fallback for platforms
            // without the Windows system font.
            _browserBodyFont = TryCreateSystemFont("Segoe UI") ??
                Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            return _browserBodyFont;
        }

        private static Font BrowserDisplayFont()
        {
            if (_browserDisplayFont != null) return _browserDisplayFont;
            // The browser uses Bahnschrift for display labels, headings, and
            // numeric emphasis. It is present on the Windows target used by
            // this project; other platforms fall back to the body font.
            _browserDisplayFont = TryCreateSystemFont("Bahnschrift") ?? BrowserBodyFont();
            return _browserDisplayFont;
        }

        private static Font TryCreateSystemFont(string family)
        {
            if (string.IsNullOrEmpty(family)) return null;
            try
            {
                return Font.CreateDynamicFontFromOSFont(family, 32);
            }
            catch (Exception)
            {
                return null;
            }
        }

        private void SetupCamera()
        {
            _camera = Camera.main;
            if (_camera == null)
            {
                var cameraObject = new GameObject("VoidFall Camera");
                _camera = cameraObject.AddComponent<Camera>();
                cameraObject.tag = "MainCamera";
            }
            _camera.orthographic = true;
            _camera.orthographicSize = WorldHalfHeight;
            UpdateGameplayCameraViewport();
            _camera.allowDynamicResolution = true;
            _camera.backgroundColor = new Color(0.015f, 0.025f, 0.07f, 1);
            if (_camera.GetComponent<AudioListener>() == null)
                _camera.gameObject.AddComponent<AudioListener>();
        }

        private void UpdateGameplayCameraViewport()
        {
            if (_camera == null || Screen.width <= 0 || Screen.height <= 0) return;
            var viewportHalf = GameplayViewportHalfExtent(Screen.width, Screen.height);
            _camera.orthographicSize = viewportHalf.y;
            _camera.aspect = viewportHalf.x / Mathf.Max(0.5f, viewportHalf.y);
        }

        private Vector2 GameplayViewportHalfExtent()
        {
            if (Screen.width > 0 && Screen.height > 0)
                return GameplayViewportHalfExtent(Screen.width, Screen.height);
            if (_camera != null && _camera.orthographic)
                return RenderViewportHalfExtent(_camera.orthographicSize, _camera.aspect);
            return new Vector2(WorldHalfWidth, WorldHalfHeight);
        }

        private static Vector2 GameplayViewportHalfExtent(float viewportWidth, float viewportHeight)
        {
            return new Vector2(
                Mathf.Max(1f, viewportWidth) * 0.5f,
                Mathf.Max(1f, viewportHeight) * 0.5f);
        }

        private void RebuildArenaPlatesForViewport(int viewportWidth, int viewportHeight, int detail)
        {
            viewportWidth = Mathf.Max(64, viewportWidth);
            viewportHeight = Mathf.Max(64, viewportHeight);
            detail = Mathf.Clamp(detail, 0, 2);
            if (_arenaPlateViewportWidth == viewportWidth &&
                _arenaPlateViewportHeight == viewportHeight &&
                _arenaPlateDetail == detail)
                return;

            var dimensions = ArenaPlateFactory.SkyBakeDimensions(
                viewportWidth,
                viewportHeight,
                detail);
            var rebuilt = new Sprite[_arenaPlateSprites.Length];
            var rebuiltDetails = new Sprite[_arenaPlateDetailSprites.Length];
            for (var index = 0; index < rebuilt.Length; index++)
            {
                rebuilt[index] = ArenaPlateFactory.CreateBase(
                    (ArenaId)index,
                    dimensions.x,
                    dimensions.y);
                rebuiltDetails[index] = ArenaPlateFactory.CreateBakedDetails(
                    (ArenaId)index,
                    dimensions.x,
                    dimensions.y);
            }

            for (var index = 0; index < _arenaPlateSprites.Length; index++)
            {
                if (_arenaPlateSprites[index] != null)
                {
                    var texture = _arenaPlateSprites[index].texture;
                    Destroy(_arenaPlateSprites[index]);
                    if (texture != null) Destroy(texture);
                }
                _arenaPlateSprites[index] = rebuilt[index];
                if (_arenaPlateDetailSprites[index] != null)
                {
                    var detailTexture = _arenaPlateDetailSprites[index].texture;
                    Destroy(_arenaPlateDetailSprites[index]);
                    if (detailTexture != null) Destroy(detailTexture);
                }
                _arenaPlateDetailSprites[index] = rebuiltDetails[index];
            }

            _arenaPlateViewportWidth = viewportWidth;
            _arenaPlateViewportHeight = viewportHeight;
            _arenaPlateDetail = detail;
            _arenaPlateBakeWidth = dimensions.x;
            _arenaPlateBakeHeight = dimensions.y;
            if (_backdropView != null)
            {
                _backdropView.sprite = _arenaPlateSprites[(int)_arenaId];
                _backdropView.transform.localScale = new Vector3(
                    GameplayViewportHalfExtent().x * 2f * ArenaSkyOverscan /
                        Mathf.Max(1, _arenaPlateBakeWidth),
                    GameplayViewportHalfExtent().y * 2f * ArenaSkyOverscan /
                        Mathf.Max(1, _arenaPlateBakeHeight),
                    1);
            }
            if (_arenaBakedDetailView != null)
            {
                _arenaBakedDetailView.sprite = _arenaPlateDetailSprites[(int)_arenaId];
                _arenaBakedDetailView.transform.localScale = new Vector3(
                    GameplayViewportHalfExtent().x * 2f * ArenaSkyOverscan /
                        Mathf.Max(1, _arenaPlateBakeWidth),
                    GameplayViewportHalfExtent().y * 2f * ArenaSkyOverscan /
                        Mathf.Max(1, _arenaPlateBakeHeight),
                    1);
            }
        }

        private void EnsureArenaPlateViewport()
        {
            RebuildArenaPlatesForViewport(
                Mathf.Max(64, Screen.width),
                Mathf.Max(64, Screen.height),
                _qualityPreset.Detail);
        }

        private void SetupBackdrop()
        {
            var backdrop = new GameObject("VoidFall Arena Backdrop");
            backdrop.transform.SetParent(_worldRoot, false);
            var renderer = backdrop.AddComponent<SpriteRenderer>();
            _backdropView = renderer;
            RebuildArenaPlatesForViewport(
                Mathf.Max(64, Screen.width),
                Mathf.Max(64, Screen.height),
                _qualityPreset.Detail);
            renderer.sprite = _arenaPlateSprites[(int)ArenaId.Void];
            renderer.color = Color.white;
            var viewportHalf = GameplayViewportHalfExtent();
            renderer.transform.localScale = new Vector3(
                viewportHalf.x * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeWidth),
                viewportHalf.y * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeHeight),
                1);
            // Keep every backdrop layer below the browser's grid pass. The
            // source draws the complete arena backdrop first, then the grid.
            renderer.sortingOrder = -110;
            _arenaBakedDetailView = CreateView(
                "Arena Baked Edge Details",
                _arenaPlateDetailSprites[(int)ArenaId.Void],
                -106);
            _arenaBakedDetailView.color = Color.white;
            _arenaBakedDetailView.transform.localScale = new Vector3(
                viewportHalf.x * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeWidth),
                viewportHalf.y * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeHeight),
                1);

            for (var index = 0; index < _arenaGrainSprites.Length; index++)
                _arenaGrainSprites[index] = ArenaPlateFactory.CreateGrainTile((ArenaId)index);

            var grainCameraObject = new GameObject("Arena Screen Grain Camera Canvas");
            grainCameraObject.transform.SetParent(_worldRoot, false);
            _arenaGrainCameraCanvas = grainCameraObject.AddComponent<Canvas>();
            _arenaGrainCameraCanvas.renderMode = RenderMode.ScreenSpaceCamera;
            _arenaGrainCameraCanvas.worldCamera = _camera;
            _arenaGrainCameraCanvas.planeDistance = 1f;
            _arenaGrainCameraCanvas.overrideSorting = true;
            _arenaGrainCameraCanvas.sortingOrder = -105;
            var grainCameraRect = grainCameraObject.GetComponent<RectTransform>();
            grainCameraRect.anchorMin = Vector2.zero;
            grainCameraRect.anchorMax = Vector2.one;
            grainCameraRect.pivot = new Vector2(0.5f, 0.5f);
            grainCameraRect.offsetMin = Vector2.zero;
            grainCameraRect.offsetMax = Vector2.zero;
            var grainCameraViewObject = new GameObject("Arena Screen Grain Camera View");
            grainCameraViewObject.transform.SetParent(grainCameraObject.transform, false);
            _arenaGrainCameraView = grainCameraViewObject.AddComponent<RawImage>();
            _arenaGrainCameraView.raycastTarget = false;
            _arenaGrainCameraView.rectTransform.anchorMin = Vector2.zero;
            _arenaGrainCameraView.rectTransform.anchorMax = Vector2.one;
            _arenaGrainCameraView.rectTransform.offsetMin = Vector2.zero;
            _arenaGrainCameraView.rectTransform.offsetMax = Vector2.zero;
            _arenaGrainCameraView.enabled = false;

            _arenaGridView = CreateMeshView("Arena Void Grid", -95, out _arenaGridRenderer);
            _arenaGridMesh = _arenaGridView.sharedMesh;
            _arenaGridMesh.MarkDynamic();
            // Keep the vertex colour at the browser's source alpha (the
            // parity test and source both use 0.065). Sprites/Default on this
            // linear mesh path renders that alpha too strongly, so attenuate
            // the material once instead of changing the source data.
            if (_arenaGridRenderer.material != null)
                _arenaGridRenderer.material.color = new Color(1f, 1f, 1f, 0.1f);
            _arenaGridRenderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            _arenaGridRenderer.receiveShadows = false;
            _arenaGridRenderer.enabled = false;

            for (var index = 0; index < MaxArenaMotes; index++)
            {
                var mote = CreateView(
                    "Arena Mote_" + index,
                    ProceduralSpriteFactory.ArenaDot(Color.white),
                    -97);
                mote.enabled = true;
                _arenaMoteViews[index] = mote;
            }
            for (var index = 0; index < MaxArenaStars; index++)
                _arenaStarViews[index] = CreateView(
                    "Arena Star_" + index,
                    ProceduralSpriteFactory.ArenaDot(Color.white),
                    -101);
            _arenaCurrentGlowView = CreateView(
                "Arena Current Glow",
                ProceduralSpriteFactory.ArenaCurrentGlow(),
                -96);

            for (var index = 0; index < MaxArenaRocks; index++)
            {
                var rock = CreateView("Arena Rock_" + index, ProceduralSpriteFactory.Rock(), -100);
                _arenaRockViews[index] = rock;
                _arenaRockPlaneViews[index] = CreateView(
                    "Arena Rock Plane_" + index,
                    ProceduralSpriteFactory.Circle(),
                    -99);
                _arenaRockRimViews[index] = CreateLineView("Arena Rock Rim_" + index, -98);
            }

            _arenaLandmarkBodyView = CreateView(
                "Arena Landmark Body",
                ProceduralSpriteFactory.Circle(),
                -108);
            for (var index = 0; index < MaxArenaStellarRimSegments; index++)
                _arenaStellarRimViews[index] = CreateLineView("Arena Stellar Rim_" + index, -107);
            for (var index = 0; index < MaxArenaLandmarkSegments; index++)
            {
                _arenaLandmarkViews[index] = CreateLineView("Arena Landmark Slab_" + index, -108);
                _arenaLandmarkRimViews[index] = CreateLineView("Arena Landmark Rim_" + index, -107);
                _arenaRingSlabFillViews[index] = CreateMeshView(
                    "Arena Landmark Slab Fill_" + index,
                    -108,
                    out _arenaRingSlabFillRenderers[index]);
                var vertices = new Vector3[ArenaRingSlabVertexCount];
                var colors = new Color[ArenaRingSlabVertexCount];
                var slabColor = new Color(0.227f, 0.216f, 0.259f, 0.9f);
                for (var vertex = 0; vertex < colors.Length; vertex++) colors[vertex] = slabColor;
                var triangles = new int[ArenaRingSlabSteps * 6];
                for (var step = 0; step < ArenaRingSlabSteps; step++)
                {
                    var triangle = step * 6;
                    var outer = step;
                    var nextOuter = step + 1;
                    var inner = ArenaRingSlabSteps + 1 + step;
                    var nextInner = inner + 1;
                    triangles[triangle] = outer;
                    triangles[triangle + 1] = nextOuter;
                    triangles[triangle + 2] = nextInner;
                    triangles[triangle + 3] = outer;
                    triangles[triangle + 4] = nextInner;
                    triangles[triangle + 5] = inner;
                }
                var mesh = _arenaRingSlabFillViews[index].sharedMesh;
                mesh.vertices = vertices;
                mesh.colors = colors;
                mesh.triangles = triangles;
                mesh.RecalculateBounds();
                _arenaRingSlabVertices[index] = vertices;
            }
            for (var index = 0; index < MaxArenaRingDebris; index++)
                _arenaRingDebrisViews[index] = CreateView(
                    "Arena Ring Debris_" + index,
                    ProceduralSpriteFactory.Rock(),
                    -108);
            for (var index = 0; index < MaxArenaOrbitViews; index++)
                _arenaOrbitViews[index] = CreateLineView("Arena Orbital Run_" + index, -104);
            for (var index = 0; index < MaxArenaOrbitFractures; index++)
                _arenaOrbitFractureViews[index] = CreateLineView("Arena Orbital Fracture_" + index, -104);

            _arenaFilamentPlateViews[0] = CreateView("Arena Red Near Filament Plate", null, -103);
            _arenaFilamentPlateViews[1] = CreateView("Arena White Near Filament Plate", null, -103);
            _arenaFilamentPlateViews[2] = CreateView("Arena Far Filament Plate", null, -109);

            for (var index = 0; index < _arenaNearFilamentOuterViews.Length; index++)
            {
                var far = index >= 4;
                var prefix = far ? "Arena Far Filament " : "Arena Near Filament ";
                var bandOrder = far ? -109 : -103;
                var strandOrder = far ? -109 : -102;
                _arenaNearFilamentOuterViews[index] = CreateMeshView(
                    prefix + "Band_" + index,
                    bandOrder,
                    out _arenaNearFilamentOuterRenderers[index]);
                ConfigureArenaFilamentMaterial(index);
                _arenaNearFilamentInnerViews[index] = CreateLineView(prefix + "Inner_" + index, strandOrder);
                _arenaNearFilamentInnerViews[index].widthCurve = CreateFilamentStrandWidthCurve();
                _arenaNearFilamentStrandViews[index] = CreateMeshView(
                    prefix + "Strand_" + index,
                    strandOrder,
                    out _arenaNearFilamentStrandRenderers[index]);
            }
            BuildArenaNearFilamentData();
        }

