        private void SetupHud()
        {
            var canvasObject = new GameObject("VoidFall HUD");
            canvasObject.transform.SetParent(transform, false);
            _canvas = canvasObject.AddComponent<Canvas>();
            _canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            _hudGroup = canvasObject.AddComponent<CanvasGroup>();
            _hudGroup.alpha = 0f;
            _hudGroup.interactable = false;
            _hudGroup.blocksRaycasts = false;
            var scaler = canvasObject.AddComponent<CanvasScaler>();
            // The browser HUD is authored in CSS pixels rather than in a
            // 1280x720 reference canvas. Constant pixels keep the desktop
            // 1600x900 capture aligned with the source panels and let the
            // explicit <=720 responsive layout own the narrow breakpoint.
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ConstantPixelSize;
            scaler.scaleFactor = 1f;
            canvasObject.AddComponent<GraphicRaycaster>();
            var eventSystem = EventSystem.current;
            if (eventSystem == null)
            {
                var eventSystemObject = new GameObject("VoidFall UI EventSystem");
                eventSystem = eventSystemObject.AddComponent<EventSystem>();
            }
            if (eventSystem.GetComponent<InputSystemUIInputModule>() == null)
                eventSystem.gameObject.AddComponent<InputSystemUIInputModule>();

            var worldRenderObject = new GameObject("VoidFall World Render Target");
            worldRenderObject.transform.SetParent(canvasObject.transform, false);
            _worldRenderView = worldRenderObject.AddComponent<RawImage>();
            _worldRenderView.raycastTarget = false;
            _worldRenderView.rectTransform.anchorMin = Vector2.zero;
            _worldRenderView.rectTransform.anchorMax = Vector2.one;
