        private MeshFilter CreateMeshView(string name, int sortingOrder, out MeshRenderer renderer)
        {
            var objectRoot = new GameObject(name);
            objectRoot.transform.SetParent(_worldRoot, false);
            var filter = objectRoot.AddComponent<MeshFilter>();
            var mesh = new Mesh { name = name + " Mesh" };
            mesh.MarkDynamic();
            filter.sharedMesh = mesh;
            renderer = objectRoot.AddComponent<MeshRenderer>();
            var shader = Shader.Find("Sprites/Default");
            if (shader != null)
            {
                renderer.material = new Material(shader);
                renderer.material.color = Color.white;
            }
            renderer.sortingOrder = sortingOrder;
            renderer.enabled = false;
            return filter;
        }

        private void ConfigureArenaFilamentMaterial(int slot)
        {
            if (slot < 0 || slot >= _arenaNearFilamentMaterials.Length) return;
            var renderer = _arenaNearFilamentOuterRenderers[slot];
            var shader = Shader.Find("VoidFall/FilamentGas");
            if (renderer == null || shader == null) return;

            var material = new Material(shader)
            {
                name = "VoidFall Filament Gas " + slot,
                hideFlags = HideFlags.HideAndDontSave,
            };
            material.SetFloat("_PassCount", ArenaNearFilamentPasses);
            renderer.sharedMaterial = material;
            _arenaNearFilamentMaterials[slot] = material;
        }

        private static AnimationCurve CreateFilamentStrandWidthCurve()
        {
            var curve = new AnimationCurve();
            curve.AddKey(0f, 0f);
            curve.AddKey(0.12f, 1f);
            curve.AddKey(0.88f, 1f);
            curve.AddKey(1f, 0f);
            return curve;
        }

        private LineRenderer CreateLineView(string name, int sortingOrder)
        {
            var objectRoot = new GameObject(name);
            objectRoot.transform.SetParent(_worldRoot, false);
            var line = objectRoot.AddComponent<LineRenderer>();
            line.useWorldSpace = true;
            var shader = Shader.Find("Sprites/Default");
            if (shader != null) line.material = new Material(shader);
            // CanvasRenderingContext2D defaults to butt caps and miter joins.
            // Explicit round paths opt in through ConfigureRoundLine.
            line.numCapVertices = 0;
            line.numCornerVertices = 0;
            line.sortingOrder = sortingOrder;
            line.enabled = false;
            return line;
        }

        private static void ConfigureRoundLine(LineRenderer line)
        {
            if (line == null) return;
            line.numCapVertices = 1;
            line.numCornerVertices = 1;
        }

