        private static float BackOut(float value)
        {
            const float c = 1.70158f;
            var u = value - 1f;
            return 1f + (c + 1f) * u * u * u + c * u * u;
        }

        private static Color ParseColor(string value, Color fallback)
        {
            return ColorUtility.TryParseHtmlString(value, out var color) ? color : fallback;
        }

        // Browser backdrop passes are screen-space. Camera trauma moves the
        // gameplay camera, but those passes only receive their source parallax
        // response; using the player position here would make every decorative
        // layer inherit the full camera shake.
        private Vector2 RenderCameraCentre()
        {
            return _camera == null
                ? _playerPosition
                : new Vector2(_camera.transform.position.x, _camera.transform.position.y);
        }

        private static Vector2 RenderViewportHalfExtent(float orthographicSize, float aspect)
        {
            var halfHeight = Mathf.Max(1f, orthographicSize);
            var halfWidth = halfHeight * Mathf.Max(0.1f, aspect);
            return new Vector2(halfWidth, halfHeight);
        }

        private Vector2 RenderViewportHalfExtent()
        {
            return _camera == null
                ? new Vector2(WorldHalfWidth, WorldHalfHeight)
                : RenderViewportHalfExtent(_camera.orthographicSize, _camera.aspect);
        }

        private void RenderArena()
        {
            if (_backdropView == null) return;
            EnsureArenaPlateViewport();
            var cameraCentre = RenderCameraCentre();
            var viewportHalf = RenderViewportHalfExtent();
            if (_arenaVignetteOverlay != null)
            {
                _arenaVignetteOverlay.sprite = ProceduralSpriteFactory.ArenaVignette(_arenaId);
                _arenaVignetteOverlay.color = Color.white;
                _arenaVignetteOverlay.enabled = true;
            }
            _backdropView.sprite = _arenaPlateSprites[(int)_arenaId];
            _backdropView.color = Color.white;
            var skyOffset = ArenaParallaxOffsetForViewport(
                cameraCentre,
                ArenaSkyParallax,
                ArenaSkyOverscan);
            _backdropView.transform.localScale = new Vector3(
                viewportHalf.x * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeWidth),
                viewportHalf.y * 2f * ArenaSkyOverscan / Mathf.Max(1, _arenaPlateBakeHeight),
                1);
            _backdropView.transform.position = new Vector3(
                cameraCentre.x - skyOffset.x,
                cameraCentre.y - skyOffset.y,
                0);
            if (_arenaBakedDetailView != null)
            {
                _arenaBakedDetailView.sprite = _arenaPlateDetailSprites[(int)_arenaId];
                _arenaBakedDetailView.color = Color.white;
                _arenaBakedDetailView.transform.localScale = _backdropView.transform.localScale;
                _arenaBakedDetailView.transform.position = _backdropView.transform.position;
                _arenaBakedDetailView.enabled = _arenaBakedDetailView.sprite != null;
            }

            if (_arenaGrainCameraCanvas != null && _arenaGrainCameraView != null)
            {
                var grainStrength = _arenaId == ArenaId.RedNebula
                    ? 0.2f
                    : _arenaId == ArenaId.WhiteSakura ? 0.24f : 0.16f;
                var grainTexture = _arenaGrainSprites[(int)_arenaId]?.texture;
                _arenaGrainCameraView.texture = grainTexture;
                _arenaGrainCameraView.uvRect = grainTexture == null
                    ? new Rect(0, 0, 1, 1)
                    : new Rect(
                        0,
                        0,
                        Screen.width / (float)Mathf.Max(1, grainTexture.width),
                        Screen.height / (float)Mathf.Max(1, grainTexture.height));
                _arenaGrainCameraView.color = new Color(1f, 1f, 1f, grainStrength);
                _arenaGrainCameraView.enabled =
                    !_visualCaptureNoGrain && grainTexture != null;
            }

            RenderArenaGrid();

            var reducedMotion = _saveData?.settings != null && _saveData.settings.reducedMotion;
            var cycle = ArenaCycleRules.At(ArenaIdName(_arenaId), _time);
            var cycleVisual = ArenaCycleVisual(cycle.CycleId, (float)cycle.Progress);
            if (!_arenaMoteSeedsReady ||
                _arenaMoteSeedArena != _arenaId ||
                _arenaMoteSeedDetail != _qualityPreset.Detail ||
                _arenaMoteSeedReducedMotion != reducedMotion)
            {
                ConfigureArenaMoteSeeds(reducedMotion);
            }
            if (!_arenaFarFilamentSeedsReady || _arenaFarFilamentSeedArena != _arenaId)
                ConfigureArenaFarFilaments();
            // The browser passes sprites.dot.orange as emberSprite for every
            // non-petal arena. It is not retinted from the arena palette.
            var moteColor = ParseColor("#fb923c", Color.white);
            var petal = _arenaId == ArenaId.WhiteSakura;
            var visibleMotes = Mathf.Clamp(
                SourceRound(_arenaMoteSeedCount * Mathf.Min(1.2f, cycleVisual.Density)),
                0,
                _arenaMoteViews.Length);
            var moteSprite = petal
                ? ProceduralSpriteFactory.Petal()
                : ProceduralSpriteFactory.ArenaDot(moteColor);
            RenderArenaStars();
            for (var index = 0; index < _arenaMoteViews.Length; index++)
            {
                var view = _arenaMoteViews[index];
                if (view == null) continue;
                if (index >= visibleMotes)
                {
                    view.enabled = false;
                    continue;
                }
                var seed = _arenaMoteSeeds[index];
                var depth = _arenaMoteDepths[index];
                var parallax = _arenaMoteParallax[index];
                var rate = _arenaMoteRates[index];
                var phase = seed.w;
                var wobble = Mathf.Sin(_arenaDecorClock * rate * 0.6f + phase) *
                    (petal ? 26f : 14f) * (0.4f + cycleVisual.Current);
                var cross = Mathf.Cos(ArenaMoteAngle(_arenaId));
                var crossY = Mathf.Sin(ArenaMoteAngle(_arenaId));
                var screenWidth = viewportHalf.x * 2f;
                var screenHeight = viewportHalf.y * 2f;
                var moteX = ArenaDecorScreenCoordinate(
                    seed.x + _arenaDecorDrift.x * rate - crossY * wobble,
                    cameraCentre.x,
                    viewportHalf.x,
                    parallax);
                var moteY = ArenaDecorScreenCoordinate(
                    seed.y + _arenaDecorDrift.y * rate + cross * wobble,
                    cameraCentre.y,
                    viewportHalf.y,
                    parallax);
                if (moteX < -30f || moteX > screenWidth + 30f ||
                    moteY < -30f || moteY > screenHeight + 30f)
                {
                    view.enabled = false;
                    continue;
                }
                var edge = Mathf.Min(1f, new Vector2(
                    (moteX - viewportHalf.x) / Mathf.Max(1f, viewportHalf.x),
                    (moteY - viewportHalf.y) / Mathf.Max(1f, viewportHalf.y)).magnitude);
                if (edge < 0.42f && (index % 5) / 5f < cycleVisual.EdgeBias)
                {
                    view.enabled = false;
                    continue;
                }

                view.sprite = moteSprite;
                var position = cameraCentre + new Vector2(
                    moteX - viewportHalf.x,
                    viewportHalf.y - moteY);
                view.transform.position = position;
                var size = _arenaMoteSizes[index] * (depth == 2 ? 1.35f : 1f);
                if (petal)
                {
                    var rotation = seed.z + _arenaDecorClock * _arenaMoteSpins[index];
                    var squash = 0.55f + 0.45f * Mathf.Abs(Mathf.Cos(rotation * 0.7f));
                    view.transform.localScale = new Vector3(
                        size / Mathf.Max(0.01f, view.sprite.bounds.size.x),
                        size * squash / Mathf.Max(0.01f, view.sprite.bounds.size.y),
                        1f);
                    view.transform.rotation = Quaternion.Euler(0, 0, rotation * Mathf.Rad2Deg);
                }
                else
                {
                    view.transform.localScale = new Vector3(
                        size / Mathf.Max(0.01f, view.sprite.bounds.size.x),
                        size / Mathf.Max(0.01f, view.sprite.bounds.size.y),
                        1f);
                    view.transform.rotation = Quaternion.identity;
                }
                var depthAlpha = depth == 2 ? 0.5f : depth == 1 ? 0.38f : 0.24f;
                var alpha = Mathf.Min(0.62f, depthAlpha * (petal ? 1f : 0.8f + cycleVisual.Current * 0.5f));
                view.color = new Color(1f, 1f, 1f, alpha);
                view.enabled = true;
            }

            RenderArenaCurrentGlow(cycleVisual, reducedMotion);

            EnsureArenaFilamentViewport();
            RenderArenaFarFilaments();
            RenderArenaNearFilaments();
            RenderArenaRocks();
            RenderArenaLandmark();
            UpdateTransitionOverlay();
        }

        private void ConfigureArenaMoteSeeds(bool reducedMotion)
        {
            var detail = _qualityPreset.Detail;
            var moteScale = detail >= 2 ? 1f : detail == 1 ? 0.55f : 0.28f;
            var sourceBudget = _arenaId == ArenaId.WhiteSakura ? 80 : 70;
            _arenaMoteSeedCount = Mathf.Min(
                MaxArenaMotes,
                SourceRound(sourceBudget * moteScale * (reducedMotion ? 0.45f : 1f)));
            var petal = _arenaId == ArenaId.WhiteSakura;
            var stream = _runSeed ^ 0x5bf03635u ^ (uint)ArenaRockNoiseSeed(_arenaId);
            for (var index = 0; index < _arenaMoteSeedCount; index++)
            {
                var roll = ArenaDecorStreamNext(ref stream);
                var depth = roll < 0.5f ? 0 : roll < 0.88f ? 1 : 2;
                var x = ArenaDecorStreamNext(ref stream) * ArenaDecorField;
                var y = ArenaDecorStreamNext(ref stream) * ArenaDecorField;
                var baseSize = petal
                    ? depth == 2 ? 15f : depth == 1 ? 10f : 6.5f
                    : depth == 2 ? 5.5f : depth == 1 ? 3.6f : 2.4f;
                var size = baseSize * (petal
                    ? 0.75f + ArenaDecorStreamNext(ref stream) * 0.5f
                    : 0.7f + ArenaDecorStreamNext(ref stream) * 0.6f);
                var rotation = ArenaDecorStreamNext(ref stream) * Mathf.PI * 2f;
                var spin = (ArenaDecorStreamNext(ref stream) - 0.5f) * (petal ? 1.1f : 0.3f);
                var rate = 0.55f + ArenaDecorStreamNext(ref stream) * 0.9f;
                var phase = ArenaDecorStreamNext(ref stream) * Mathf.PI * 2f;
                _arenaMoteSeeds[index] = new Vector4(x, y, rotation, phase);
                _arenaMoteSizes[index] = size;
                _arenaMoteSpins[index] = spin;
                _arenaMoteRates[index] = rate;
                _arenaMoteParallax[index] = depth == 2 ? 0.72f : depth == 1 ? 0.45f : 0.26f;
                _arenaMoteDepths[index] = depth;
            }
            for (var index = _arenaMoteSeedCount; index < MaxArenaMotes; index++)
            {
                _arenaMoteSeeds[index] = Vector4.zero;
                _arenaMoteSizes[index] = 0;
                _arenaMoteSpins[index] = 0;
                _arenaMoteRates[index] = 0;
                _arenaMoteParallax[index] = 0;
                _arenaMoteDepths[index] = 0;
            }
            _arenaMoteSeedArena = _arenaId;
            _arenaMoteSeedDetail = detail;
            _arenaMoteSeedReducedMotion = reducedMotion;
            _arenaMoteSeedsReady = true;
        }

        private static float WrapArenaMote(float value, float span, float margin)
        {
            var wrapped = value % span;
            if (wrapped < 0) wrapped += span;
            return wrapped - margin;
        }

        private static float ArenaDecorScreenCoordinate(
            float fieldCoordinate,
            float cameraCentre,
            float halfExtent,
            float parallax)
        {
            return ArenaWrappedScreenCoordinate(
                fieldCoordinate,
                ArenaDecorField,
                cameraCentre,
                halfExtent,
                parallax);
        }

        private static float ArenaWrappedScreenCoordinate(
            float fieldCoordinate,
            float span,
            float cameraCentre,
            float halfExtent,
            float parallax)
        {
            // Browser decorative drawing receives camera top-left coordinates:
            // cam = cameraCentre - viewportHalfExtent. Preserve that mapping
            // before converting the screen coordinate back to Unity world space.
            var margin = (span - halfExtent * 2f) * 0.5f;
            var cameraTopLeft = cameraCentre - halfExtent;
            return WrapArenaMote(
                fieldCoordinate - cameraTopLeft * parallax,
                span,
                margin);
        }

        private void RenderArenaGrid()
        {
            if (_arenaGridRenderer == null || _arenaGridMesh == null) return;
            if (_visualCaptureNoGrid)
            {
                _arenaGridRenderer.enabled = false;
                return;
            }

            var visible = _arenaId == ArenaId.Void;
            _arenaGridRenderer.enabled = visible;
            if (!visible) return;

            var cameraCentre = _camera == null
                ? new Vector3(_playerPosition.x, _playerPosition.y, 0)
                : _camera.transform.position;
            var worldHeight = _camera == null
                ? WorldHalfHeight * 2f
                : Mathf.Max(1f, _camera.orthographicSize * 2f);
            var worldWidth = _camera == null
                ? WorldHalfWidth * 2f
                : Mathf.Max(1f, worldHeight * Mathf.Max(0.1f, _camera.aspect));
            var halfWidth = worldWidth * 0.5f;
            var halfHeight = worldHeight * 0.5f;
            var left = cameraCentre.x - halfWidth;
            var right = cameraCentre.x + halfWidth;
            var bottom = cameraCentre.y - halfHeight;
            var top = cameraCentre.y + halfHeight;
            var firstX = Mathf.Floor(left / ArenaGridSpacing) * ArenaGridSpacing;
            var firstY = Mathf.Floor(bottom / ArenaGridSpacing) * ArenaGridSpacing;
            var verticalCount = Mathf.Max(
                1,
                Mathf.CeilToInt((right + ArenaGridSpacing - firstX) / ArenaGridSpacing));
            var horizontalCount = Mathf.Max(
                1,
                Mathf.CeilToInt((top + ArenaGridSpacing - firstY) / ArenaGridSpacing));

            if (Mathf.Approximately(_arenaGridFirstX, firstX) &&
                Mathf.Approximately(_arenaGridFirstY, firstY) &&
                Mathf.Approximately(_arenaGridWidth, worldWidth) &&
                Mathf.Approximately(_arenaGridHeight, worldHeight) &&
                _arenaGridVerticalCount == verticalCount &&
                _arenaGridHorizontalCount == horizontalCount)
                return;

            var lineCount = verticalCount + horizontalCount;
            var vertices = new Vector3[lineCount * 2];
            var colors = new Color[lineCount * 2];
            var indices = new int[lineCount * 2];
            var gridColor = new Color(117f / 255f, 133f / 255f, 160f / 255f, 0.065f);
            var vertex = 0;
            for (var line = 0; line < verticalCount; line++)
            {
                var x = firstX + line * ArenaGridSpacing;
                vertices[vertex] = new Vector3(x, bottom, 0);
                vertices[vertex + 1] = new Vector3(x, top, 0);
                colors[vertex] = gridColor;
                colors[vertex + 1] = gridColor;
                indices[vertex] = vertex;
                indices[vertex + 1] = vertex + 1;
                vertex += 2;
            }
            for (var line = 0; line < horizontalCount; line++)
            {
                var y = firstY + line * ArenaGridSpacing;
                vertices[vertex] = new Vector3(left, y, 0);
                vertices[vertex + 1] = new Vector3(right, y, 0);
                colors[vertex] = gridColor;
                colors[vertex + 1] = gridColor;
                indices[vertex] = vertex;
                indices[vertex + 1] = vertex + 1;
                vertex += 2;
            }

            _arenaGridMesh.Clear();
            _arenaGridMesh.vertices = vertices;
            _arenaGridMesh.colors = colors;
            _arenaGridMesh.SetIndices(indices, MeshTopology.Lines, 0);
            _arenaGridMesh.RecalculateBounds();
            _arenaGridFirstX = firstX;
            _arenaGridFirstY = firstY;
            _arenaGridWidth = worldWidth;
            _arenaGridHeight = worldHeight;
            _arenaGridVerticalCount = verticalCount;
            _arenaGridHorizontalCount = horizontalCount;
        }

        private void RenderArenaStars()
        {
            var cameraCentre = RenderCameraCentre();
            var sourceCount = _arenaId == ArenaId.RedNebula
                ? 26
                : _arenaId == ArenaId.Void ? 42 : 0;
            // The browser hides the star pass at quality 0; quality 1 keeps
            // the reduced 60% population and quality 2 keeps the full count.
            var qualityScale = _qualityPreset.Detail <= 0
                ? 0f
                : _qualityPreset.Detail > 1 ? 1f : 0.6f;
            var visible = Mathf.Clamp(
                Mathf.RoundToInt(sourceCount * qualityScale),
                0,
                _arenaStarViews.Length);
            var starColor = ArenaStarColor(_arenaId);
            var starSprite = ProceduralSpriteFactory.ArenaDot(starColor);
            const float starSpan = 2200f;
            var viewportHalf = RenderViewportHalfExtent();
            for (var index = 0; index < _arenaStarViews.Length; index++)
            {
                var view = _arenaStarViews[index];
                if (view == null) continue;
                if (index >= visible)
                {
                    view.enabled = false;
                    continue;
                }

                var x = ArenaWrappedScreenCoordinate(
                    index * 613.7f,
                    starSpan,
                    cameraCentre.x,
                    viewportHalf.x,
                    0.1f);
                var y = ArenaWrappedScreenCoordinate(
                    index * 419.3f,
                    starSpan,
                    cameraCentre.y,
                    viewportHalf.y,
                    0.1f);
                var twinkle = 0.4f + 0.35f * Mathf.Sin(
                    _arenaDecorClock * (0.6f + (index % 5) * 0.22f) + index);
                var size = 1.6f + (index % 3) * 0.9f;
                view.sprite = starSprite;
                view.transform.position = cameraCentre + new Vector2(
                    x - viewportHalf.x,
                    viewportHalf.y - y);
                view.transform.localScale = Vector3.one * (size / Mathf.Max(0.01f, view.sprite.bounds.size.x));
                view.color = new Color(1f, 1f, 1f, twinkle * 0.55f);
                view.enabled = true;
            }
        }

        private static Color ArenaStarColor(ArenaId arena)
        {
            // The browser passes sprites.dot.white as starSprite for every
            // arena; the arena palette does not retint this source sprite.
            return ParseColor("#e2e8f0", Color.white);
        }

        private void RenderArenaCurrentGlow(ArenaCycleVisualState cycle, bool reducedMotion)
        {
            if (_arenaCurrentGlowView == null) return;
            // Source drawMotes gates this localized current glow on
            // `frame.quality > 0`, not on the broader particle scale.
            if (cycle.Current <= 0.6f || reducedMotion || _qualityPreset.Detail <= 0)
            {
                _arenaCurrentGlowView.enabled = false;
                return;
            }

            var travel = Mathf.Repeat(_arenaDecorClock * 0.18f, 1f);
            var viewportHalf = RenderViewportHalfExtent();
            var x = -viewportHalf.x + (0.12f + travel * 0.82f) * viewportHalf.x * 2f;
            var y = -viewportHalf.y +
                (0.24f + Mathf.Sin(travel * 4.1f) * 0.2f + 0.2f) * viewportHalf.y * 2f;
            var reach = Mathf.Min(viewportHalf.x * 2f, viewportHalf.y * 2f) * 0.16f;
            var tint = ArenaCloudTint(_arenaId);
            _arenaCurrentGlowView.transform.position = RenderCameraCentre() + new Vector2(x, y);
            _arenaCurrentGlowView.transform.localScale = Vector3.one *
                (reach * 2f / Mathf.Max(0.01f, _arenaCurrentGlowView.sprite.bounds.size.x));
            _arenaCurrentGlowView.color = new Color(tint.r, tint.g, tint.b, 0.14f * cycle.Current);
            _arenaCurrentGlowView.enabled = true;
        }

        private static Color ArenaCloudTint(ArenaId arena)
        {
            switch (arena)
            {
                case ArenaId.RedNebula: return ParseColor("#b04a34", Color.white);
                case ArenaId.WhiteSakura: return ParseColor("#545660", Color.white);
                default: return ParseColor("#54689e", Color.white);
            }
        }

        private void ConfigureArenaRockSeeds()
        {
            var detail = _qualityPreset.Detail;
            var reducedMotion = _saveData?.settings != null && _saveData.settings.reducedMotion;
            if (!_arenaMoteSeedsReady ||
                _arenaMoteSeedArena != _arenaId ||
                _arenaMoteSeedDetail != detail ||
                _arenaMoteSeedReducedMotion != reducedMotion)
            {
                ConfigureArenaMoteSeeds(reducedMotion);
            }
            var rockScale = detail >= 2 ? 1f : detail == 1 ? 0.75f : 0.5f;
            var sourceFarCount = _arenaId == ArenaId.RedNebula ? 4 :
                _arenaId == ArenaId.WhiteSakura ? 3 : 0;
            var sourceMidCount = _arenaId == ArenaId.RedNebula ? 6 :
                _arenaId == ArenaId.WhiteSakura ? 5 : 0;
            _arenaRockFarCount = sourceFarCount > 0
                ? Mathf.Max(1, SourceRound(sourceFarCount * rockScale))
                : 0;
            _arenaRockTotalCount = _arenaRockFarCount +
                SourceRound(sourceMidCount * rockScale);

            var stream = _runSeed ^ 0x5bf03635u ^ (uint)ArenaRockNoiseSeed(_arenaId);
            // React's createArenaDecor keeps one stream alive: all mote
            // records are consumed before makeRocks starts reading it. Unity
            // used to restart here, which was deterministic but not source
            // parity. Each mote consumes eight values in ConfigureArenaMoteSeeds.
            for (var mote = 0; mote < _arenaMoteSeedCount; mote++)
            {
                for (var value = 0; value < 8; value++) ArenaDecorStreamNext(ref stream);
            }
            for (var index = 0; index < _arenaRockTotalCount; index++)
            {
                // This is the same seven-value record as createArenaDecor's
                // makeRocks: x, y, size roll, rotation, spin, shape, tone.
                _arenaRockSeeds[index] = new Vector4(
                    ArenaDecorStreamNext(ref stream),
                    ArenaDecorStreamNext(ref stream),
                    ArenaDecorStreamNext(ref stream),
                    ArenaDecorStreamNext(ref stream));
                _arenaRockSpins[index] = (ArenaDecorStreamNext(ref stream) - 0.5f) * 0.045f;
                _arenaRockShapes[index] = Mathf.FloorToInt(ArenaDecorStreamNext(ref stream) * 6f);
                _arenaRockTones[index] = ArenaDecorStreamNext(ref stream);
            }
            for (var index = _arenaRockTotalCount; index < MaxArenaRocks; index++)
            {
                _arenaRockSeeds[index] = Vector4.zero;
                _arenaRockSpins[index] = 0;
                _arenaRockShapes[index] = 0;
                _arenaRockTones[index] = 0;
            }
            _arenaRockSeedArena = _arenaId;
            _arenaRockSeedDetail = detail;
            _arenaRockSeedReducedMotion = reducedMotion;
            _arenaRockSeedsReady = true;
        }

        private static int ArenaRockNoiseSeed(ArenaId arena)
        {
            switch (arena)
            {
                case ArenaId.RedNebula: return 0x7c1f;
                case ArenaId.WhiteSakura: return 0x2ad9;
                default: return 0x51a3;
            }
        }

        // JavaScript Math.round is floor(value + 0.5) for these non-negative
        // decorative budgets; Mathf.RoundToInt uses midpoint-to-even instead.
        private static int SourceRound(float value)
        {
            return Mathf.FloorToInt(value + 0.5f);
        }

        private static int TelemetryFpsForFrame(float frameSeconds)
        {
            return frameSeconds > 0.0001f
                ? SourceRound(1000f / frameSeconds)
                : 0;
        }

        private static float ArenaDecorStreamNext(ref uint state)
        {
            state += 0x6d2b79f5u;
            var value = state;
            value = (value ^ (value >> 15)) * (value | 1u);
            value ^= value + ((value ^ (value >> 7)) * (value | 61u));
            return (value ^ (value >> 14)) / 4294967296f;
        }

        private void RenderArenaRocks()
        {
            var cameraCentre = RenderCameraCentre();
            var reducedMotion = _saveData?.settings != null && _saveData.settings.reducedMotion;
            if (!_arenaRockSeedsReady || _arenaRockSeedArena != _arenaId ||
                _arenaRockSeedDetail != _qualityPreset.Detail ||
                _arenaRockSeedReducedMotion != reducedMotion)
                ConfigureArenaRockSeeds();

            var visible = _arenaRockTotalCount;
            var pale = _arenaId == ArenaId.WhiteSakura;
            // Keep the browser ArenaVisualSpec palette as the authority. The
            // previous hand-tuned floats were close, but not the exact source
            // sRGB tokens and drifted on the low-contrast White Sakura layer.
            var farBody = ParseColor(pale ? "#94919a" : "#0d0709", Color.white);
            var midBody = ParseColor(pale ? "#6d6a77" : "#160b0d", Color.white);
            var farRim = ParseColor(pale ? "#f3ede4" : "#8a3a22", Color.white);
            var midRim = ParseColor(pale ? "#e8e0d6" : "#7a3520", Color.white);
            var farAlpha = pale ? 0.42f : 0.94f;
            var midAlpha = pale ? 0.46f : 0.7f;
            var lightAngle = ArenaLightAngle(_arenaId);
            var rimPulse = 1f + _arenaFlash * 0.5f;
            for (var index = 0; index < _arenaRockViews.Length; index++)
            {
                var view = _arenaRockViews[index];
                var plane = _arenaRockPlaneViews[index];
                var rim = _arenaRockRimViews[index];
                if (view == null) continue;
                if (index >= visible)
                {
                    view.enabled = false;
                    Hide(plane);
                    Hide(rim);
                    continue;
                }

                var seed = _arenaRockSeeds[index];
                var far = index < _arenaRockFarCount;
                var parallax = far
                    ? (pale ? 0.15f : 0.14f)
                    : (pale ? 0.31f : 0.3f);
                var sourceX = seed.x * ArenaDecorField;
                var sourceY = seed.y * ArenaDecorField;
                var viewportHalf = RenderViewportHalfExtent();
                var screenX = ArenaDecorScreenCoordinate(
                    sourceX,
                    cameraCentre.x,
                    viewportHalf.x,
                    parallax);
                var screenY = ArenaDecorScreenCoordinate(
                    sourceY,
                    cameraCentre.y,
                    viewportHalf.y,
                    parallax);
                view.transform.position = cameraCentre + new Vector2(
                    screenX - viewportHalf.x,
                    viewportHalf.y - screenY);
                var diameter = far
                    ? Mathf.Lerp(110f, pale ? 175f : 180f, seed.z)
                    : Mathf.Lerp(pale ? 30f : 34f, pale ? 56f : 62f, seed.z);
                view.sprite = ProceduralSpriteFactory.ArenaRock(_arenaRockShapes[index]);
                view.transform.localScale = Vector3.one * diameter;
                var rockAngle = seed.w * 360f +
                    _arenaRockSpins[index] * _arenaDecorClock * Mathf.Rad2Deg;
                view.transform.rotation = Quaternion.Euler(0, 0, rockAngle);
                var layerAlpha = far ? farAlpha : midAlpha;
                var body = far ? farBody : midBody;
                view.color = new Color(body.r, body.g, body.b, layerAlpha);
                view.enabled = true;

                var rimBase = far ? farRim : midRim;
                if (plane != null)
                {
                    var planeRadius = diameter * 0.5f;
                    plane.transform.position = view.transform.position +
                        view.transform.rotation * new Vector3(-planeRadius * 0.18f, planeRadius * 0.12f, 0);
                    plane.transform.rotation = Quaternion.Euler(
                        0, 0, rockAngle + _arenaRockTones[index] * 360f);
                    var circleWidth = Mathf.Max(0.01f, plane.sprite.bounds.size.x);
                    var circleHeight = Mathf.Max(0.01f, plane.sprite.bounds.size.y);
                    plane.transform.localScale = new Vector3(
                        planeRadius * 0.92f / circleWidth,
                        planeRadius * 0.68f / circleHeight,
                        1);
                    plane.color = new Color(rimBase.r, rimBase.g, rimBase.b, layerAlpha * 0.1f);
                    plane.enabled = true;
                }

                if (rim == null) continue;
                var radius = diameter * 0.5f;
                rim.positionCount = 16;
                for (var point = 0; point < rim.positionCount; point++)
                {
                    var t = point / (float)(rim.positionCount - 1);
                    var angle = lightAngle - 0.62f + t * 1.24f;
                    rim.SetPosition(
                        point,
                        view.transform.position + new Vector3(
                            Mathf.Cos(angle) * radius * 0.9f,
                            Mathf.Sin(angle) * radius * 0.9f,
                            0));
                }
                var rimColor = new Color(
                    rimBase.r,
                    rimBase.g,
                    rimBase.b,
                    Mathf.Min(1f, layerAlpha * 0.22f * rimPulse));
                rim.startColor = rimColor;
                rim.endColor = rimColor;
                rim.startWidth = Mathf.Max(1f, radius * 0.03f);
                rim.endWidth = rim.startWidth;
                rim.enabled = true;
            }
        }

        private void RenderArenaFarFilaments()
        {
            var cameraCentre = RenderCameraCentre();
            var layerCentre = cameraCentre - ArenaParallaxOffsetForViewport(
                cameraCentre,
                ArenaSkyParallax,
                ArenaSkyOverscan);

            var plateView = _arenaFilamentPlateViews[2];
            if (plateView != null)
            {
                plateView.transform.position = layerCentre;
                plateView.color = Color.white;
                plateView.enabled = _arenaFarFilamentCount > 0;
                HideArenaFilamentCompatibilityViews(4, 4);
                return;
            }

            for (var index = 0; index < 4; index++)
            {
                var slot = 4 + index;
                var outer = _arenaNearFilamentOuterViews[slot];
                var outerRenderer = _arenaNearFilamentOuterRenderers[slot];
                var inner = _arenaNearFilamentInnerViews[slot];
                var strand = _arenaNearFilamentStrandViews[slot];
                var strandRenderer = _arenaNearFilamentStrandRenderers[slot];
                if (outer == null || outerRenderer == null || inner == null || strand == null || strandRenderer == null ||
                    index >= _arenaFarFilamentCount)
                {
                    Hide(outerRenderer);
                    Hide(inner);
                    Hide(strandRenderer);
                    continue;
                }

                var points = _arenaNearFilamentPoints[slot];
                var mesh = outer.sharedMesh;
                var bandColors = _arenaNearFilamentBandColors[slot];
                if (points == null || mesh == null || bandColors == null)
                {
                    Hide(outerRenderer);
                    Hide(inner);
                    Hide(strandRenderer);
                    continue;
                }

                outer.transform.position = layerCentre;
                var baseColor = _arenaNearFilamentColors[slot];
                var peak = Mathf.Clamp01(_arenaNearFilamentAlphas[slot]);
                var filamentMaterial = _arenaNearFilamentMaterials[slot];
                var useNotchMask = filamentMaterial != null && _arenaNearFilamentNotchMasks[slot] != null;
                if (useNotchMask)
                {
                    filamentMaterial.SetFloat("_Peak", peak);
                    filamentMaterial.SetFloat("_PassCount", ArenaNearFilamentPasses);
                }
                for (var pass = 0; pass < ArenaNearFilamentPasses; pass++)
                {
                    for (var point = 0; point < points.Length; point++)
                    {
                        var half = _arenaNearFilamentPointWidths[slot][point] *
                            (1.6f - pass * 0.13f) * 0.5f;
                        var leftNotchFactor = Mathf.Clamp01(NearFilamentNotchFactor(
                            point,
                            half,
                            _arenaNearFilamentPointWidths[slot][point],
                            _arenaNearFilamentNotches[slot],
                            _arenaNearFilamentNotchHeights[slot],
                            _arenaNearFilamentPointSpacings[slot]));
                        var rightNotchFactor = Mathf.Clamp01(NearFilamentNotchFactor(
                            point,
                            -half,
                            _arenaNearFilamentPointWidths[slot][point],
                            _arenaNearFilamentNotches[slot],
                            _arenaNearFilamentNotchHeights[slot],
                            _arenaNearFilamentPointSpacings[slot]));
                        var vertex = (pass * points.Length + point) * 2;
                        bandColors[vertex] = new Color(
                            baseColor.r,
                            baseColor.g,
                            baseColor.b,
                            useNotchMask
                                ? 1f
                                : NearFilamentPassAlpha(peak, leftNotchFactor, ArenaNearFilamentPasses));
                        bandColors[vertex + 1] = new Color(
                            baseColor.r,
                            baseColor.g,
                            baseColor.b,
                            useNotchMask
                                ? 1f
                                : NearFilamentPassAlpha(peak, rightNotchFactor, ArenaNearFilamentPasses));
                    }
                }
                mesh.colors = bandColors;
                outerRenderer.enabled = true;

                var strandFrom = Mathf.Clamp(_arenaNearFilamentStrandFrom[slot], 0, points.Length - 1);
                var strandTo = Mathf.Clamp(_arenaNearFilamentStrandTo[slot], strandFrom, points.Length);
                var strandCount = strandTo - strandFrom;
                var strandMesh = strand.sharedMesh;
                var strandColors = _arenaNearFilamentStrandColors[slot];
                if (strandCount < 4 || strandMesh == null || strandColors == null)
                {
                    Hide(inner);
                    Hide(strandRenderer);
                    continue;
                }

                strand.transform.position = layerCentre;
                var strandPerPass = 1f - Mathf.Pow(
                    1f - Mathf.Clamp01(_arenaNearFilamentAlphas[slot] * 0.6f),
                    1f / ArenaNearStrandPasses);
                for (var vertex = 0; vertex < strandColors.Length; vertex++)
                {
                    strandColors[vertex] = new Color(
                        _arenaNearFilamentCoreColors[slot].r,
                        _arenaNearFilamentCoreColors[slot].g,
                        _arenaNearFilamentCoreColors[slot].b,
                        strandPerPass);
                }
                strandMesh.colors = strandColors;
                strandRenderer.enabled = true;
                Hide(inner);
            }
        }

        private void RenderArenaNearFilaments()
        {
            // Browser buildArenaLayers omits the near filament canvas at
            // quality 0; keep only the baked sky/far layer on Low.
            var activeStart = _arenaId == ArenaId.RedNebula ? 0 : _arenaId == ArenaId.WhiteSakura ? 2 : -1;
            var plateGroup = activeStart == 0 ? 0 : activeStart == 2 ? 1 : -1;
            if (_qualityPreset.Detail <= 0)
            {
                HideArenaFilamentCompatibilityViews(0, 4);
                for (var index = 0; index < 2; index++) Hide(_arenaFilamentPlateViews[index]);
                return;
            }
            var plateView = plateGroup >= 0 ? _arenaFilamentPlateViews[plateGroup] : null;
            if (plateView != null)
            {
                var plateCycle = ArenaCycleRules.At(ArenaIdName(_arenaId), _time);
                var plateCycleVisual = ArenaCycleVisual(plateCycle.CycleId, (float)plateCycle.Progress);
                var plateAlphaScale = 0.4f + plateCycleVisual.Definition * 0.6f;
                var plateCameraCentre = RenderCameraCentre();
                plateView.transform.position = plateCameraCentre - ArenaParallaxOffsetForViewport(
                    plateCameraCentre,
                    ArenaNearParallax,
                    ArenaNearOverscan);
                plateView.color = new Color(1f, 1f, 1f, Mathf.Clamp01(plateAlphaScale));
                plateView.enabled = plateGroup >= 0;
                for (var index = 0; index < 2; index++)
                {
                    var other = _arenaFilamentPlateViews[index];
                    if (other != null && other != plateView) other.enabled = false;
                }
                HideArenaFilamentCompatibilityViews(0, 4);
                return;
            }

            var cycle = ArenaCycleRules.At(ArenaIdName(_arenaId), _time);
            var cycleVisual = ArenaCycleVisual(cycle.CycleId, (float)cycle.Progress);
            var alphaScale = 0.4f + cycleVisual.Definition * 0.6f;
            var cameraCentre = RenderCameraCentre();
            var layerCentre = cameraCentre - ArenaParallaxOffsetForViewport(
                cameraCentre,
                ArenaNearParallax,
                ArenaNearOverscan);

            for (var index = 0; index < 4; index++)
            {
                var outer = _arenaNearFilamentOuterViews[index];
                var outerRenderer = _arenaNearFilamentOuterRenderers[index];
                var inner = _arenaNearFilamentInnerViews[index];
                var strand = _arenaNearFilamentStrandViews[index];
                var strandRenderer = _arenaNearFilamentStrandRenderers[index];
                if (outer == null || outerRenderer == null || inner == null || strand == null || strandRenderer == null ||
                    activeStart < 0 || index < activeStart || index >= activeStart + 2)
                {
                    Hide(outerRenderer);
                    Hide(inner);
                    Hide(strandRenderer);
                    continue;
                }

                var points = _arenaNearFilamentPoints[index];
                var mesh = outer.sharedMesh;
                var bandColors = _arenaNearFilamentBandColors[index];
                if (points == null || mesh == null || bandColors == null)
                {
                    Hide(outerRenderer);
                    Hide(inner);
                    continue;
                }

                outer.transform.position = layerCentre;
                var baseColor = _arenaNearFilamentColors[index];
                var peak = Mathf.Clamp01(_arenaNearFilamentAlphas[index] * alphaScale * 0.95f);
                var filamentMaterial = _arenaNearFilamentMaterials[index];
                var useNotchMask = filamentMaterial != null && _arenaNearFilamentNotchMasks[index] != null;
                if (useNotchMask)
                {
                    filamentMaterial.SetFloat("_Peak", peak);
                    filamentMaterial.SetFloat("_PassCount", ArenaNearFilamentPasses);
                }
                for (var pass = 0; pass < ArenaNearFilamentPasses; pass++)
                {
                    for (var point = 0; point < points.Length; point++)
                    {
                        var half = _arenaNearFilamentPointWidths[index][point] *
                            (1.6f - pass * 0.13f) * 0.5f;
                        var leftNotchFactor = Mathf.Clamp01(NearFilamentNotchFactor(
                            point,
                            half,
                            _arenaNearFilamentPointWidths[index][point],
                            _arenaNearFilamentNotches[index],
                            _arenaNearFilamentNotchHeights[index],
                            _arenaNearFilamentPointSpacings[index]));
                        var rightNotchFactor = Mathf.Clamp01(NearFilamentNotchFactor(
                            point,
                            -half,
                            _arenaNearFilamentPointWidths[index][point],
                            _arenaNearFilamentNotches[index],
                            _arenaNearFilamentNotchHeights[index],
                            _arenaNearFilamentPointSpacings[index]));
                        var vertex = (pass * points.Length + point) * 2;
                        bandColors[vertex] = new Color(
                            baseColor.r,
                            baseColor.g,
                            baseColor.b,
                            useNotchMask
                                ? 1f
                                : NearFilamentPassAlpha(peak, leftNotchFactor, ArenaNearFilamentPasses));
                        bandColors[vertex + 1] = new Color(
                            baseColor.r,
                            baseColor.g,
                            baseColor.b,
                            useNotchMask
                                ? 1f
                                : NearFilamentPassAlpha(peak, rightNotchFactor, ArenaNearFilamentPasses));
                    }
                }
                mesh.colors = bandColors;
                outerRenderer.enabled = true;

                var strandFrom = Mathf.Clamp(_arenaNearFilamentStrandFrom[index], 0, points.Length - 1);
                var strandTo = Mathf.Clamp(_arenaNearFilamentStrandTo[index], strandFrom, points.Length);
                var strandCount = strandTo - strandFrom;
                var strandMesh = strand.sharedMesh;
                var strandColors = _arenaNearFilamentStrandColors[index];
                if (strandCount < 4 || strandMesh == null || strandColors == null)
                {
                    Hide(inner);
                    Hide(strandRenderer);
                    continue;
                }

                strand.transform.position = layerCentre;
                var strandPeak = Mathf.Clamp01(_arenaNearFilamentAlphas[index] * alphaScale * 0.6f);
                var strandPerPass = 1f - Mathf.Pow(
                    1f - strandPeak,
                    1f / ArenaNearStrandPasses);
                for (var vertex = 0; vertex < strandColors.Length; vertex++)
                {
                    strandColors[vertex] = new Color(
                        _arenaNearFilamentCoreColors[index].r,
                        _arenaNearFilamentCoreColors[index].g,
                        _arenaNearFilamentCoreColors[index].b,
                        strandPerPass);
                }
                strandMesh.colors = strandColors;
                strandRenderer.enabled = true;
                Hide(inner);
            }
        }

        private void HideArenaFilamentCompatibilityViews(int startSlot, int count)
        {
            var endSlot = Mathf.Min(startSlot + Mathf.Max(0, count), _arenaNearFilamentOuterRenderers.Length);
            for (var slot = Mathf.Max(0, startSlot); slot < endSlot; slot++)
            {
                Hide(_arenaNearFilamentOuterRenderers[slot]);
                Hide(_arenaNearFilamentInnerViews[slot]);
                Hide(_arenaNearFilamentStrandRenderers[slot]);
            }
        }

        private void BuildArenaNearFilamentData()
        {
            BuildArenaFilament(0, 0, -0.44f, 0.085f, ArenaNearOverscan, 0x7c1f + 991, 0.34f, ParseColor("#ad4028", Color.white), ParseColor("#d98750", Color.white));
            BuildArenaFilament(1, 1, -0.44f, 0.085f, ArenaNearOverscan, 0x7c1f + 991, 0.34f, ParseColor("#7d341a", Color.white), ParseColor("#d98750", Color.white));
            BuildArenaFilament(2, 0, 0.66f, 0.06f, ArenaNearOverscan, 0x2ad9 + 991, 0.32f, ParseColor("#e3b9cd", Color.white), ParseColor("#f6dfe9", Color.white));
            BuildArenaFilament(3, 1, 0.66f, 0.06f, ArenaNearOverscan, 0x2ad9 + 991, 0.32f, ParseColor("#f0cbdd", Color.white), ParseColor("#f6dfe9", Color.white));
            var viewportHalf = RenderViewportHalfExtent();
            BuildArenaFilamentGroupNotchMask(
                0,
                0,
                2,
                viewportHalf.x * 2f * ArenaNearOverscan,
                viewportHalf.y * 2f * ArenaNearOverscan);
            BuildArenaFilamentGroupNotchMask(
                1,
                2,
                2,
                viewportHalf.x * 2f * ArenaNearOverscan,
                viewportHalf.y * 2f * ArenaNearOverscan);
            BuildArenaFilamentPlate(
                0,
                0,
                2,
                viewportHalf.x * 2f * ArenaNearOverscan,
                viewportHalf.y * 2f * ArenaNearOverscan,
                _arenaNearFilamentCoreColors[0],
                0.95f);
            BuildArenaFilamentPlate(
                1,
                2,
                2,
                viewportHalf.x * 2f * ArenaNearOverscan,
                viewportHalf.y * 2f * ArenaNearOverscan,
                _arenaNearFilamentCoreColors[2],
                0.95f);
            _arenaFilamentViewportWidth = viewportHalf.x * 2f;
            _arenaFilamentViewportHeight = viewportHalf.y * 2f;
        }

        private void EnsureArenaFilamentViewport()
        {
            var viewportHalf = RenderViewportHalfExtent();
            var width = viewportHalf.x * 2f;
            var height = viewportHalf.y * 2f;
            if (Mathf.Approximately(_arenaFilamentViewportWidth, width) &&
                Mathf.Approximately(_arenaFilamentViewportHeight, height))
                return;

            BuildArenaNearFilamentData();
            ConfigureArenaFarFilaments();
        }

        private void ConfigureArenaFarFilaments()
        {
            var isRed = _arenaId == ArenaId.RedNebula;
            var isWhite = _arenaId == ArenaId.WhiteSakura;
            var count = isRed ? 4 : isWhite ? 3 : 0;
            var angle = isRed ? -0.62f : 0.5f;
            var widthFraction = isRed ? 0.17f : 0.13f;
            var seed = isRed ? 0x7c1f : 0x2ad9;
            var alpha = isRed ? 0.5f : 0.3f;
            var breakTint = isWhite ? ParseColor("#efe6ea", Color.white) : ParseColor("#c9713f", Color.white);
            var colors = isRed
                ? new[] { ParseColor("#7f1d2e", Color.white), ParseColor("#98301f", Color.white), ParseColor("#5b1a2c", Color.white), ParseColor("#6d2233", Color.white) }
                : new[] { ParseColor("#c4c3c6", Color.white), ParseColor("#cbc8c6", Color.white), ParseColor("#bdbcc2", Color.white) };

            for (var index = 0; index < 4; index++)
            {
                var slot = 4 + index;
                if (index < count)
                {
                    BuildArenaFilament(
                        slot,
                        index,
                        angle,
                        widthFraction,
                        ArenaSkyOverscan,
                        seed,
                        alpha,
                        colors[index],
                        breakTint);
                }
                else
                {
                    _arenaNearFilamentPoints[slot] = null;
                    Hide(_arenaNearFilamentOuterRenderers[slot]);
                    Hide(_arenaNearFilamentStrandRenderers[slot]);
                }
            }

            var viewportHalf = RenderViewportHalfExtent();
            BuildArenaFilamentGroupNotchMask(
                2,
                4,
                4,
                viewportHalf.x * 2f * ArenaSkyOverscan,
                viewportHalf.y * 2f * ArenaSkyOverscan);
            BuildArenaFilamentPlate(
                2,
                4,
                count,
                viewportHalf.x * 2f * ArenaSkyOverscan,
                viewportHalf.y * 2f * ArenaSkyOverscan,
                count > 0 ? _arenaNearFilamentCoreColors[4] : Color.clear,
                1f);
            _arenaFarFilamentCount = count;
            _arenaFarFilamentSeedArena = _arenaId;
            _arenaFarFilamentSeedsReady = true;
        }

        private void BuildArenaFilament(
            int slot,
            int sourceIndex,
            float angle,
            float widthFraction,
            float overscan,
            int seed,
            float alpha,
            Color color,
            Color coreColor)
        {
            var viewportHalf = RenderViewportHalfExtent();
            var width = viewportHalf.x * 2f * overscan;
            var height = viewportHalf.y * 2f * overscan;
            var shorter = Mathf.Min(width, height);
            var stream = unchecked((uint)(seed + sourceIndex * 7919));
            var actualAngle = angle + (NearStreamNext(ref stream) - 0.5f) * 1.15f;
            var across = (0.1f + NearStreamNext(ref stream) * 0.86f) * height;
            var span = Mathf.Sqrt(width * width + height * height) * 1.35f;
            var cosine = Mathf.Cos(actualAngle);
            var sine = Mathf.Sin(actualAngle);
            var originX = width * 0.5f - cosine * span * 0.5f;
            var originY = across - sine * span * 0.5f;
            var baseWidth = widthFraction * shorter * (0.62f + NearStreamNext(ref stream) * 0.85f);
            var points = new Vector2[37];
            var pointWidths = new float[points.Length];
            for (var step = 0; step < points.Length; step++)
            {
                var t = step / (float)(points.Length - 1);
                var along = t * span;
                var noiseSeed = unchecked(seed + sourceIndex * 104729);
                var wander = (NearFbm(t * 1.9f, sourceIndex * 3.3f, noiseSeed, 3) - 0.5f) * baseWidth * 3.4f +
                    (NearValueNoise(t * 6.1f, sourceIndex * 5.1f, noiseSeed + 33) - 0.5f) * baseWidth * 0.8f;
                var taper = Mathf.Sin(Mathf.Clamp01(t) * Mathf.PI);
                var breathe = 0.45f + 0.55f * NearFbm(t * 3.4f + 11f, sourceIndex * 2.7f, noiseSeed + 77, 2);
                pointWidths[step] = Mathf.Max(1f, baseWidth * breathe * (0.35f + taper * 0.75f));
                points[step] = new Vector2(
                    originX + cosine * along - sine * wander,
                    originY + sine * along + cosine * wander);
            }
            _arenaNearFilamentPoints[slot] = points;
            _arenaNearFilamentPointWidths[slot] = pointWidths;
            _arenaNearFilamentPointSpacings[slot] = span / (points.Length - 1);
            _arenaNearFilamentWidths[slot] = baseWidth;
            _arenaNearFilamentColors[slot] = color;
            _arenaNearFilamentCoreColors[slot] = coreColor;
            _arenaNearFilamentAlphas[slot] = alpha;

            var notchStream = unchecked((uint)(seed + sourceIndex * 5381));
            var notches = new Vector4[7];
            var notchHeights = new float[notches.Length];
            for (var notch = 0; notch < notches.Length; notch++)
            {
                var at = 1 + Mathf.FloorToInt(NearStreamNext(ref notchStream) * (points.Length - 2));
                var pointWidth = pointWidths[at];
                var reach = pointWidth * (0.5f + NearStreamNext(ref notchStream) * 0.9f);
                var cut = 0.22f + NearStreamNext(ref notchStream) * 0.34f;
                var lateral = (NearStreamNext(ref notchStream) - 0.5f) * pointWidth * 1.1f;
                var notchHeight = pointWidth * (0.14f + NearStreamNext(ref notchStream) * 0.26f);
                notches[notch] = new Vector4(at, reach, cut, lateral);
                notchHeights[notch] = notchHeight;
            }
            _arenaNearFilamentNotches[slot] = notches;
            _arenaNearFilamentNotchHeights[slot] = notchHeights;

            var strandFrom = 2 + Mathf.FloorToInt(NearStreamNext(ref notchStream) * (points.Length * 0.32f));
            var strandTo = Mathf.Min(
                points.Length - 2,
                strandFrom + SourceRound(points.Length * (0.28f + NearStreamNext(ref notchStream) * 0.3f)));
            _arenaNearFilamentStrandFrom[slot] = strandFrom;
            _arenaNearFilamentStrandTo[slot] = strandTo;
            _arenaNearFilamentStrandShifts[slot] = NearStreamNext(ref notchStream) < 0.5f ? -0.2f : 0.2f;
            BuildArenaNearFilamentBand(slot, width, height);
        }

        private void BuildArenaFilamentPlate(
            int group,
            int startSlot,
            int slotCount,
            float width,
            float height,
            Color breakTint,
            float peakMultiplier)
        {
            if (group < 0 || group >= _arenaFilamentPlateViews.Length) return;
            FilamentTextureDimensions(width, height, out var pixelWidth, out var pixelHeight);
            var endSlot = Mathf.Min(
                startSlot + Mathf.Max(0, slotCount),
                _arenaNearFilamentPoints.Length);
            var hasFilament = false;
            var plate = new FilamentRasterPlate(width, height, pixelWidth, pixelHeight);
            var halfLayer = new Vector2(width * 0.5f, height * 0.5f);
            for (var slot = Mathf.Max(0, startSlot); slot < endSlot; slot++)
            {
                var points = _arenaNearFilamentPoints[slot];
                var pointWidths = _arenaNearFilamentPointWidths[slot];
                var notches = _arenaNearFilamentNotches[slot];
                var notchHeights = _arenaNearFilamentNotchHeights[slot];
                if (points == null || pointWidths == null || notches == null) continue;
                hasFilament = true;

                var localPoints = new Vector2[points.Length];
                for (var point = 0; point < points.Length; point++)
                    localPoints[point] = points[point] - halfLayer;

                var peak = Mathf.Clamp01(_arenaNearFilamentAlphas[slot] * peakMultiplier);
                var perPass = 1f - Mathf.Pow(
                    1f - peak,
                    1f / ArenaNearFilamentPasses);
                for (var pass = 0; pass < ArenaNearFilamentPasses; pass++)
                {
                    plate.FillBand(
                        localPoints,
                        pointWidths,
                        1.6f - pass * 0.13f,
                        0f,
                        _arenaNearFilamentColors[slot],
                        perPass);
                }

                for (var notch = 0; notch < notches.Length; notch++)
                {
                    var data = notches[notch];
                    var pointIndex = Mathf.Clamp(
                        Mathf.RoundToInt(data.x),
                        0,
                        points.Length - 1);
                    var normal = NearFilamentNormal(points, pointIndex);
                    var rotation = Mathf.Atan2(-normal.x, normal.y);
                    var reach = Mathf.Max(0.75f, data.y);
                    var notchHeight = notchHeights != null && notch < notchHeights.Length
                        ? Mathf.Max(0.5f, notchHeights[notch])
                        : Mathf.Max(0.5f, pointWidths[pointIndex] * 0.24f);
                    var centre = localPoints[pointIndex] + normal * data.w;
                    plate.EraseEllipse(
                        centre,
                        reach,
                        notchHeight,
                        rotation,
                        Mathf.Clamp01(data.z));
                }

                var strandFrom = Mathf.Clamp(
                    _arenaNearFilamentStrandFrom[slot],
                    0,
                    points.Length - 1);
                var strandTo = Mathf.Clamp(
                    _arenaNearFilamentStrandTo[slot],
                    strandFrom,
                    points.Length);
                var strandCount = strandTo - strandFrom;
                if (strandCount <= 3) continue;

                var strandPoints = new Vector2[strandCount];
                var strandWidths = new float[strandCount];
                var strandShift = _arenaNearFilamentStrandShifts[slot];
                for (var localPoint = 0; localPoint < strandCount; localPoint++)
                {
                    var point = strandFrom + localPoint;
                    strandPoints[localPoint] = localPoints[point];
                    strandWidths[localPoint] = pointWidths[point] * Mathf.Sin(
                        ((localPoint + 0.5f) / strandCount) * Mathf.PI);
                }

                var strandPasses = ArenaNearStrandPasses;
                var strandAlpha = 1f - Mathf.Pow(
                    1f - Mathf.Clamp01(peak * 0.6f),
                    1f / strandPasses);
                for (var pass = 0; pass < strandPasses; pass++)
                {
                    plate.FillBand(
                        strandPoints,
                        strandWidths,
                        0.86f - pass * 0.094f,
                        strandShift,
                        breakTint,
                        strandAlpha);
                }
            }

            var view = _arenaFilamentPlateViews[group];
            if (!hasFilament)
            {
                ReplaceArenaFilamentPlate(group, null, null, width, height, pixelWidth, pixelHeight);
                if (view != null) view.enabled = false;
                return;
            }

            var texture = plate.ToTexture("VoidFall Filament Plate " + group);
            var sprite = Sprite.Create(
                texture,
                new Rect(0, 0, pixelWidth, pixelHeight),
                new Vector2(0.5f, 0.5f),
                1f);
            sprite.name = "VoidFall Filament Plate Sprite " + group;
            ReplaceArenaFilamentPlate(group, sprite, texture, width, height, pixelWidth, pixelHeight);
            if (view != null)
            {
                view.color = Color.white;
                view.enabled = false;
            }
        }

        private void ReplaceArenaFilamentPlate(
            int group,
            Sprite sprite,
            Texture2D texture,
            float width,
            float height,
            int pixelWidth,
            int pixelHeight)
        {
            if (_arenaFilamentPlateSprites[group] != null)
                Destroy(_arenaFilamentPlateSprites[group]);
            if (_arenaFilamentPlateTextures[group] != null)
                Destroy(_arenaFilamentPlateTextures[group]);
            _arenaFilamentPlateSprites[group] = sprite;
            _arenaFilamentPlateTextures[group] = texture;
            var view = _arenaFilamentPlateViews[group];
            if (view == null) return;
            view.sprite = sprite;
            view.transform.localScale = new Vector3(
                width / Mathf.Max(1, pixelWidth),
                height / Mathf.Max(1, pixelHeight),
                1f);
        }

        private static void FilamentTextureDimensions(
            float width,
            float height,
            out int pixelWidth,
            out int pixelHeight)
        {
            var longest = Mathf.Max(width, height);
            var scale = ArenaFilamentMaskMaxDimension / Mathf.Max(1f, longest);
            pixelWidth = Mathf.Max(
                ArenaFilamentMaskMinDimension,
                Mathf.RoundToInt(width * scale));
            pixelHeight = Mathf.Max(
                ArenaFilamentMaskMinDimension,
                Mathf.RoundToInt(height * scale));
        }

        private void BuildArenaFilamentGroupNotchMask(
            int group,
            int startSlot,
            int slotCount,
            float width,
            float height)
        {
            FilamentTextureDimensions(width, height, out var maskWidth, out var maskHeight);
            var factors = new float[maskWidth * maskHeight];
            for (var pixel = 0; pixel < factors.Length; pixel++) factors[pixel] = 1f;

            var hasFilament = false;
            var halfLayer = new Vector2(width * 0.5f, height * 0.5f);
            var endSlot = Mathf.Min(startSlot + Mathf.Max(0, slotCount), _arenaNearFilamentPoints.Length);
            for (var slot = Mathf.Max(0, startSlot); slot < endSlot; slot++)
            {
                var points = _arenaNearFilamentPoints[slot];
                var notches = _arenaNearFilamentNotches[slot];
                var notchHeights = _arenaNearFilamentNotchHeights[slot];
                if (points == null || notches == null || notches.Length == 0) continue;
                hasFilament = true;
                for (var notch = 0; notch < notches.Length; notch++)
                {
                    var data = notches[notch];
                    var pointIndex = Mathf.Clamp(Mathf.RoundToInt(data.x), 0, points.Length - 1);
                    var normal = NearFilamentNormal(points, pointIndex);
                    var tangent = new Vector2(normal.y, -normal.x);
                    if (tangent.sqrMagnitude < 0.000001f)
                    {
                        // centrelineNormal() returns zero for a zero-length source
                        // segment; Canvas atan2(-0, 0) still leaves the major axis
                        // horizontal in that degenerate case.
                        normal = Vector2.up;
                        tangent = Vector2.right;
                    }
                    else
                    {
                        tangent.Normalize();
                        normal.Normalize();
                    }

                    var centre = points[pointIndex] - halfLayer + normal * data.w;
                    var reach = Mathf.Max(0.75f, data.y);
                    var notchHeight = notchHeights != null && notch < notchHeights.Length
                        ? Mathf.Max(0.5f, notchHeights[notch])
                        : Mathf.Max(0.5f, _arenaNearFilamentPointWidths[slot][pointIndex] * 0.24f);
                    var extent = Mathf.Sqrt(reach * reach + notchHeight * notchHeight) + 1f;
                    var minX = Mathf.Max(
                        0,
                        Mathf.FloorToInt(((centre.x - extent) / width + 0.5f) * maskWidth) - 1);
                    var maxX = Mathf.Min(
                        maskWidth - 1,
                        Mathf.CeilToInt(((centre.x + extent) / width + 0.5f) * maskWidth) + 1);
                    var minY = Mathf.Max(
                        0,
                        Mathf.FloorToInt(((centre.y - extent) / height + 0.5f) * maskHeight) - 1);
                    var maxY = Mathf.Min(
                        maskHeight - 1,
                        Mathf.CeilToInt(((centre.y + extent) / height + 0.5f) * maskHeight) + 1);
                    var cut = Mathf.Clamp01(data.z);
                    for (var y = minY; y <= maxY; y++)
                    {
                        for (var x = minX; x <= maxX; x++)
                        {
                            var coverage = 0f;
                            for (var sampleY = 0; sampleY < 4; sampleY++)
                            {
                                var localY = ((y + (sampleY + 0.5f) * 0.25f) / maskHeight) * height - height * 0.5f;
                                for (var sampleX = 0; sampleX < 4; sampleX++)
                                {
                                    var localX = ((x + (sampleX + 0.5f) * 0.25f) / maskWidth) * width - width * 0.5f;
                                    var delta = new Vector2(localX, localY) - centre;
                                    var along = Vector2.Dot(delta, tangent) / reach;
                                    var lateral = Vector2.Dot(delta, normal) / notchHeight;
                                    if (along * along + lateral * lateral < 1f)
                                        coverage += 0.0625f;
                                }
                            }

                            if (coverage > 0f)
                            {
                                var pixel = y * maskWidth + x;
                                // Every notch from every filament in the layer
                                // cuts the same isolated plate, matching the
                                // browser's destination-out order at overlaps.
                                factors[pixel] *= 1f - cut * coverage;
                            }
                        }
                    }
                }
            }

            var pixels = new Color32[factors.Length];
            for (var pixel = 0; pixel < factors.Length; pixel++)
            {
                var alpha = (byte)Mathf.RoundToInt(Mathf.Clamp01(factors[pixel]) * 255f);
                pixels[pixel] = new Color32(255, 255, 255, alpha);
            }

            if (_arenaFilamentGroupNotchMasks[group] != null)
                Destroy(_arenaFilamentGroupNotchMasks[group]);
            if (!hasFilament)
            {
                _arenaFilamentGroupNotchMasks[group] = null;
                for (var slot = Mathf.Max(0, startSlot); slot < endSlot; slot++)
                {
                    _arenaNearFilamentNotchMasks[slot] = null;
                    var material = _arenaNearFilamentMaterials[slot];
                    if (material != null) material.SetTexture("_MaskTex", null);
                }
                return;
            }

            var mask = new Texture2D(maskWidth, maskHeight, TextureFormat.RGBA32, false)
            {
                name = "VoidFall Filament Group Notch Mask " + group,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
            };
            mask.SetPixels32(pixels);
            mask.Apply(false, true);
            _arenaFilamentGroupNotchMasks[group] = mask;
            for (var slot = Mathf.Max(0, startSlot); slot < endSlot; slot++)
            {
                _arenaNearFilamentNotchMasks[slot] = mask;
                var material = _arenaNearFilamentMaterials[slot];
                if (material != null) material.SetTexture("_MaskTex", mask);
            }
        }

        private void BuildArenaNearFilamentBand(int slot, float width, float height)
        {
            var points = _arenaNearFilamentPoints[slot];
            var filter = _arenaNearFilamentOuterViews[slot];
            if (points == null || filter == null || filter.sharedMesh == null) return;

            var halfLayer = new Vector2(width * 0.5f, height * 0.5f);
            var vertices = new Vector3[points.Length * 2 * ArenaNearFilamentPasses];
            var uvs = new Vector2[vertices.Length];
            var colors = new Color[vertices.Length];
            var triangles = new int[(points.Length - 1) * 6 * ArenaNearFilamentPasses];
            for (var pass = 0; pass < ArenaNearFilamentPasses; pass++)
            {
                var spread = 1.6f - pass * 0.13f;
                for (var point = 0; point < points.Length; point++)
                {
                    var normal = NearFilamentNormal(points, point);
                    var half = _arenaNearFilamentPointWidths[slot][point] * spread * 0.5f;
                    var centre = points[point] - halfLayer;
                    var vertex = (pass * points.Length + point) * 2;
                    vertices[vertex] = new Vector3(centre.x + normal.x * half, centre.y + normal.y * half, 0);
                    vertices[vertex + 1] = new Vector3(centre.x - normal.x * half, centre.y - normal.y * half, 0);
                    uvs[vertex] = FilamentMaskUv(vertices[vertex], width, height);
                    uvs[vertex + 1] = FilamentMaskUv(vertices[vertex + 1], width, height);
                    colors[vertex] = Color.white;
                    colors[vertex + 1] = Color.white;
                    if (point >= points.Length - 1) continue;
                    var triangle = (pass * (points.Length - 1) + point) * 6;
                    triangles[triangle] = vertex;
                    triangles[triangle + 1] = vertex + 2;
                    triangles[triangle + 2] = vertex + 1;
                    triangles[triangle + 3] = vertex + 1;
                    triangles[triangle + 4] = vertex + 2;
                    triangles[triangle + 5] = vertex + 3;
                }
            }

            var mesh = filter.sharedMesh;
            mesh.Clear();
            mesh.vertices = vertices;
            mesh.uv = uvs;
            mesh.colors = colors;
            mesh.triangles = triangles;
            mesh.RecalculateBounds();
            _arenaNearFilamentBandVertices[slot] = vertices;
            _arenaNearFilamentBandColors[slot] = colors;
            BuildArenaNearFilamentStrand(slot, width, height);
        }

        private static Vector2 FilamentMaskUv(Vector3 localPosition, float width, float height)
        {
            return new Vector2(
                localPosition.x / Mathf.Max(1f, width) + 0.5f,
                localPosition.y / Mathf.Max(1f, height) + 0.5f);
        }

        private void BuildArenaNearFilamentStrand(int slot, float width, float height)
        {
            var points = _arenaNearFilamentPoints[slot];
            var filter = _arenaNearFilamentStrandViews[slot];
            if (points == null || filter == null || filter.sharedMesh == null) return;

            var strandFrom = Mathf.Clamp(_arenaNearFilamentStrandFrom[slot], 0, points.Length - 1);
            var strandTo = Mathf.Clamp(_arenaNearFilamentStrandTo[slot], strandFrom, points.Length);
            var strandCount = strandTo - strandFrom;
            if (strandCount < 4) return;

            var halfLayer = new Vector2(width * 0.5f, height * 0.5f);
            var vertices = new Vector3[strandCount * 2 * ArenaNearStrandPasses];
            var colors = new Color[vertices.Length];
            var triangles = new int[(strandCount - 1) * 6 * ArenaNearStrandPasses];
            var shift = _arenaNearFilamentStrandShifts[slot];
            for (var pass = 0; pass < ArenaNearStrandPasses; pass++)
            {
                var spread = 0.86f - pass * 0.094f;
                for (var localPoint = 0; localPoint < strandCount; localPoint++)
                {
                    var point = strandFrom + localPoint;
                    var normal = NearFilamentNormal(points, point);
                    var taper = Mathf.Sin(((localPoint + 0.5f) / strandCount) * Mathf.PI);
                    var half = _arenaNearFilamentPointWidths[slot][point] * taper * spread * 0.5f;
                    var centre = points[point] - halfLayer + normal * (_arenaNearFilamentPointWidths[slot][point] * shift);
                    var vertex = (pass * strandCount + localPoint) * 2;
                    vertices[vertex] = new Vector3(centre.x + normal.x * half, centre.y + normal.y * half, 0);
                    vertices[vertex + 1] = new Vector3(centre.x - normal.x * half, centre.y - normal.y * half, 0);
                    colors[vertex] = Color.white;
                    colors[vertex + 1] = Color.white;
                    if (localPoint >= strandCount - 1) continue;
                    var triangle = (pass * (strandCount - 1) + localPoint) * 6;
                    triangles[triangle] = vertex;
                    triangles[triangle + 1] = vertex + 2;
                    triangles[triangle + 2] = vertex + 1;
                    triangles[triangle + 3] = vertex + 1;
                    triangles[triangle + 4] = vertex + 2;
                    triangles[triangle + 5] = vertex + 3;
                }
            }

            var mesh = filter.sharedMesh;
            mesh.Clear();
            mesh.vertices = vertices;
            mesh.colors = colors;
            mesh.triangles = triangles;
            mesh.RecalculateBounds();
            _arenaNearFilamentStrandVertices[slot] = vertices;
            _arenaNearFilamentStrandColors[slot] = colors;
        }

        private static Vector2 NearFilamentNormal(Vector2[] points, int index)
        {
            var previous = points[Mathf.Max(0, index - 1)];
            var next = points[Mathf.Min(points.Length - 1, index + 1)];
            var normal = new Vector2(-(next.y - previous.y), next.x - previous.x);
            // Browser centrelineNormal() uses Math.hypot(...) || 1: exact
            // zero returns a zero normal, while every non-zero segment,
            // including a tiny one, is normalized.
            var length = normal.magnitude;
            return normal / (length > 0f ? length : 1f);
        }

        private static float NearFilamentNotchFactor(
            int pointIndex,
            float lateral,
            float pointWidth,
            Vector4[] notches,
            float[] notchHeights,
            float pointSpacing)
        {
            if (notches == null || notches.Length == 0) return 1f;
            var factor = 1f;
            var spacing = Mathf.Max(1f, pointSpacing);
            for (var notch = 0; notch < notches.Length; notch++)
            {
                var data = notches[notch];
                var height = notchHeights != null && notch < notchHeights.Length
                    ? Mathf.Max(0.5f, notchHeights[notch])
                    : Mathf.Max(0.5f, pointWidth * 0.24f);
                // Source paintFilaments() erases a rotated ellipse from the
                // isolated gas plate. Evaluate that ellipse in centreline
                // distance/lateral space instead of using independent linear
                // profiles; the mesh then interpolates the same binary
                // inside/outside coverage across its ribbon triangles.
                var along = (pointIndex - data.x) * spacing;
                var normalizedAlong = along / Mathf.Max(0.75f, data.y);
                var normalizedLateral = (lateral - data.w) / height;
                var ellipseDistanceSquared = normalizedAlong * normalizedAlong +
                    normalizedLateral * normalizedLateral;
                if (ellipseDistanceSquared < 1f)
                    factor *= 1f - Mathf.Clamp01(data.z);
            }
            return Mathf.Clamp01(factor);
        }

        private static float NearFilamentPassAlpha(float peak, float notchFactor, int passCount)
        {
            // The browser first stacks the band to `peak`, then destination-out
            // multiplies that coverage by the notch factor. Solve the inverse
            // stacking equation for each Unity mesh pass so the final alpha is
            // peak * notchFactor rather than a different exponent-shaped value.
            var target = Mathf.Clamp01(peak) * Mathf.Clamp01(notchFactor);
            return 1f - Mathf.Pow(1f - target, 1f / Mathf.Max(1, passCount));
        }

        private sealed class FilamentRasterPlate
        {
            private const int CoverageSamplesPerAxis = 4;
            private const int CoverageSampleCount = CoverageSamplesPerAxis * CoverageSamplesPerAxis;
            private readonly float _worldWidth;
            private readonly float _worldHeight;
            private readonly int _pixelWidth;
            private readonly int _pixelHeight;
            private readonly Color[] _pixels;

            public FilamentRasterPlate(float worldWidth, float worldHeight, int pixelWidth, int pixelHeight)
            {
                _worldWidth = Mathf.Max(1f, worldWidth);
                _worldHeight = Mathf.Max(1f, worldHeight);
                _pixelWidth = Mathf.Max(1, pixelWidth);
                _pixelHeight = Mathf.Max(1, pixelHeight);
                _pixels = new Color[_pixelWidth * _pixelHeight];
                for (var index = 0; index < _pixels.Length; index++)
                    _pixels[index] = Color.clear;
            }

            public void FillBand(
                Vector2[] points,
                float[] widths,
                float spread,
                float shift,
                Color color,
                float alpha)
            {
                if (points == null || widths == null || points.Length < 2) return;
                var polygon = new Vector2[points.Length * 2];
                for (var index = 0; index < points.Length; index++)
                {
                    var normal = NearFilamentNormal(points, index);
                    var half = widths[Mathf.Min(index, widths.Length - 1)] * spread * 0.5f;
                    var centre = points[index] + normal * (widths[Mathf.Min(index, widths.Length - 1)] * shift);
                    polygon[index] = centre + normal * half;
                    polygon[polygon.Length - 1 - index] = centre - normal * half;
                }
                FillPolygon(polygon, color, alpha);
            }

            public void EraseEllipse(
                Vector2 centre,
                float radiusX,
                float radiusY,
                float rotation,
                float alpha)
            {
                var safeRadiusX = Mathf.Max(0.001f, radiusX);
                var safeRadiusY = Mathf.Max(0.001f, radiusY);
                var cosine = Mathf.Cos(rotation);
                var sine = Mathf.Sin(rotation);
                var extentX = Mathf.Sqrt(
                    safeRadiusX * safeRadiusX * cosine * cosine +
                    safeRadiusY * safeRadiusY * sine * sine);
                var extentY = Mathf.Sqrt(
                    safeRadiusX * safeRadiusX * sine * sine +
                    safeRadiusY * safeRadiusY * cosine * cosine);
                var minX = Mathf.Max(0, Mathf.FloorToInt(WorldToPixel(centre.x - extentX, true)) - 1);
                var maxX = Mathf.Min(_pixelWidth - 1, Mathf.CeilToInt(WorldToPixel(centre.x + extentX, true)) + 1);
                var minY = Mathf.Max(0, Mathf.FloorToInt(WorldToPixel(centre.y - extentY, false)) - 1);
                var maxY = Mathf.Min(_pixelHeight - 1, Mathf.CeilToInt(WorldToPixel(centre.y + extentY, false)) + 1);
                var cut = Mathf.Clamp01(alpha);
                for (var y = minY; y <= maxY; y++)
                {
                    for (var x = minX; x <= maxX; x++)
                    {
                        var coverage = 0f;
                        for (var sampleY = 0; sampleY < CoverageSamplesPerAxis; sampleY++)
                        {
                            for (var sampleX = 0; sampleX < CoverageSamplesPerAxis; sampleX++)
                            {
                                var delta = SampleWorld(x, y, sampleX, sampleY) - centre;
                                var localX = cosine * delta.x + sine * delta.y;
                                var localY = -sine * delta.x + cosine * delta.y;
                                var normalizedX = localX / safeRadiusX;
                                var normalizedY = localY / safeRadiusY;
                                if (normalizedX * normalizedX + normalizedY * normalizedY < 1f)
                                    coverage += 1f / CoverageSampleCount;
                            }
                        }

                        if (coverage <= 0f) continue;
                        var index = y * _pixelWidth + x;
                        var destination = _pixels[index];
                        var remaining = Mathf.Clamp01(1f - cut * coverage);
                        destination.a *= remaining;
                        _pixels[index] = destination;
                    }
                }
            }

            public Texture2D ToTexture(string name)
            {
                var texture = new Texture2D(_pixelWidth, _pixelHeight, TextureFormat.RGBA32, false)
                {
                    name = name + " Texture",
                    filterMode = FilterMode.Bilinear,
                    wrapMode = TextureWrapMode.Clamp,
                };
                texture.SetPixels(_pixels);
                texture.Apply(false, true);
                return texture;
            }

            private void FillPolygon(Vector2[] points, Color color, float alpha)
            {
                if (points == null || points.Length < 3) return;
                var minX = _pixelWidth - 1;
                var minY = _pixelHeight - 1;
                var maxX = 0;
                var maxY = 0;
                for (var index = 0; index < points.Length; index++)
                {
                    var pixel = ToPixel(points[index]);
                    minX = Mathf.Min(minX, Mathf.FloorToInt(pixel.x));
                    maxX = Mathf.Max(maxX, Mathf.CeilToInt(pixel.x));
                    minY = Mathf.Min(minY, Mathf.FloorToInt(pixel.y));
                    maxY = Mathf.Max(maxY, Mathf.CeilToInt(pixel.y));
                }
                minX = Mathf.Clamp(minX, 0, _pixelWidth - 1);
                maxX = Mathf.Clamp(maxX, 0, _pixelWidth - 1);
                minY = Mathf.Clamp(minY, 0, _pixelHeight - 1);
                maxY = Mathf.Clamp(maxY, 0, _pixelHeight - 1);
                var sourceAlpha = Mathf.Clamp01(color.a * alpha);
                if (sourceAlpha <= 0f) return;
                for (var y = minY; y <= maxY; y++)
                {
                    for (var x = minX; x <= maxX; x++)
                    {
                        var coverage = 0;
                        for (var sampleY = 0; sampleY < CoverageSamplesPerAxis; sampleY++)
                        {
                            for (var sampleX = 0; sampleX < CoverageSamplesPerAxis; sampleX++)
                            {
                                if (Contains(points, SampleWorld(x, y, sampleX, sampleY)))
                                    coverage++;
                            }
                        }
                        if (coverage == 0) continue;
                        BlendSourceOver(
                            x,
                            y,
                            color,
                            sourceAlpha * coverage / CoverageSampleCount);
                    }
                }
            }

            private Vector2 ToPixel(Vector2 world)
            {
                return new Vector2(
                    (world.x / _worldWidth + 0.5f) * _pixelWidth,
                    (world.y / _worldHeight + 0.5f) * _pixelHeight);
            }

            private float WorldToPixel(float value, bool horizontal)
            {
                return (value / (horizontal ? _worldWidth : _worldHeight) + 0.5f) *
                    (horizontal ? _pixelWidth : _pixelHeight);
            }

            private Vector2 SampleWorld(int x, int y, int sampleX, int sampleY)
            {
                return new Vector2(
                    ((x + (sampleX + 0.5f) / CoverageSamplesPerAxis) / _pixelWidth - 0.5f) * _worldWidth,
                    ((y + (sampleY + 0.5f) / CoverageSamplesPerAxis) / _pixelHeight - 0.5f) * _worldHeight);
            }

            private void BlendSourceOver(int x, int y, Color color, float sourceAlpha)
            {
                if (sourceAlpha <= 0f) return;
                var index = y * _pixelWidth + x;
                var destination = _pixels[index];
                var destinationAlpha = Mathf.Clamp01(destination.a);
                var outputAlpha = sourceAlpha + destinationAlpha * (1f - sourceAlpha);
                if (outputAlpha <= 0.0001f)
                {
                    _pixels[index] = Color.clear;
                    return;
                }
                _pixels[index] = new Color(
                    (color.r * sourceAlpha + destination.r * destinationAlpha * (1f - sourceAlpha)) / outputAlpha,
                    (color.g * sourceAlpha + destination.g * destinationAlpha * (1f - sourceAlpha)) / outputAlpha,
                    (color.b * sourceAlpha + destination.b * destinationAlpha * (1f - sourceAlpha)) / outputAlpha,
                    outputAlpha);
            }

            private static bool Contains(Vector2[] polygon, Vector2 point)
            {
                var inside = false;
                for (var index = 0; index < polygon.Length; index++)
                {
                    var previous = index == 0 ? polygon.Length - 1 : index - 1;
                    var a = polygon[index];
                    var b = polygon[previous];
                    if ((a.y > point.y) == (b.y > point.y)) continue;
                    var denominator = b.y - a.y;
                    if (Mathf.Abs(denominator) < 0.00001f) continue;
                    var crossing = (b.x - a.x) * (point.y - a.y) / denominator + a.x;
                    if (point.x < crossing) inside = !inside;
                }
                return inside;
            }
        }

        private struct ArenaCycleVisualState
        {
            public float Definition;
            public float Current;
            public float Rim;
            public float Density;
            public float EdgeBias;
        }

        private void UpdateArenaDecor(float dt, bool reducedMotion)
        {
            var cycle = ArenaCycleRules.At(ArenaIdName(_arenaId), _time);
            var visual = ArenaCycleVisual(cycle.CycleId, (float)cycle.Progress);
            var step = Mathf.Clamp(dt, 0, 0.1f);
            var motion = reducedMotion ? 0.25f : 1f;
            _arenaDecorClock += step * motion;

            var angle = ArenaMoteAngle(_arenaId) + visual.Current * 0.35f;
            var speed = ArenaMoteSpeed(_arenaId) * (0.35f + visual.Current * 0.9f) * motion;
            _arenaDecorDrift += new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * speed * step;
            _arenaDecorDrift.x = Mathf.Repeat(_arenaDecorDrift.x, ArenaDecorField);
            _arenaDecorDrift.y = Mathf.Repeat(_arenaDecorDrift.y, ArenaDecorField);
        }

        private static ArenaCycleVisualState ArenaCycleVisual(string cycleId, float progress)
        {
            var eased = Mathf.Sin(Mathf.Clamp01(progress) * Mathf.PI);
            switch (cycleId)
            {
                case "quiet":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.35f, Current = 0.1f, Rim = 0.35f, Density = 0.8f, EdgeBias = 0,
                    };
                case "ionized":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.9f, Current = 0.85f, Rim = 0.5f, Density = 1f, EdgeBias = 0.15f,
                    };
                case "flare":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.6f, Current = 0.45f, Rim = 0.55f + eased * 0.45f,
                        Density = 1f, EdgeBias = 0.1f,
                    };
                case "still":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.3f, Current = 0.08f, Rim = 0.4f, Density = 0.7f, EdgeBias = 0,
                    };
                case "cross":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.55f, Current = 0.9f, Rim = 0.45f, Density = 0.95f, EdgeBias = 0.2f,
                    };
                case "bloom":
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.45f, Current = 0.4f, Rim = 0.5f, Density = 1f,
                        EdgeBias = 0.55f + eased * 0.45f,
                    };
                default:
                    return new ArenaCycleVisualState
                    {
                        Definition = 0.4f, Current = 0.2f, Rim = 0.4f, Density = 1f, EdgeBias = 0,
                    };
            }
        }

